function Library:Unload()
	if not self.Alive then return end
	self.Alive = false
	for _, c in self.Connections do pcall(function() c:Disconnect() end) end
	for _, t in self.Threads do pcall(task.cancel, t) end
	if self.OnUnload then for _, fn in self.OnUnload do pcall(fn) end end
	self.Holder:Clean()
	if getgenv then getgenv().Library = nil end
end

-- ---- one mouse-move / release listener for the whole library ----
-- Every slider, colour picker and draggable used to connect its own UserInputService.InputChanged and InputEnded, so one mouse
-- move ran hundreds of callbacks (slow in heavy games). Now an element joins only while it is being dragged:
-- Library.beginDrag(onMove, onEnd) calls onMove(input) on each move until the button / finger is released, then onEnd(input) once.
local MOVE, TOUCH, MB1 = Enum.UserInputType.MouseMovement, Enum.UserInputType.Touch, Enum.UserInputType.MouseButton1
local moveSubs, endSubs = {}, {}
Library:Connect(UserInputService.InputChanged, function(i)
	if next(moveSubs) == nil then return end
	local t = i.UserInputType
	if t ~= MOVE and t ~= TOUCH then return end
	for fn in moveSubs do pcall(fn, i) end
end)
Library:Connect(UserInputService.InputEnded, function(i)
	if next(endSubs) == nil then return end
	local t = i.UserInputType
	if t ~= MB1 and t ~= TOUCH then return end
	local list = {}
	for fn in endSubs do list[#list + 1] = fn end
	for _, fn in list do pcall(fn, i) end
end)
function Library.beginDrag(onMove, onEnd)
	local finish
	finish = function(i)
		if onMove then moveSubs[onMove] = nil end
		endSubs[finish] = nil
		if onEnd then onEnd(i) end
	end
	if onMove then moveSubs[onMove] = true end
	endSubs[finish] = true
	return finish
end

-- a window must stay reachable: its top edge (where it is dragged) never above the screen, and a strip of it always on screen
local GuiService = game:GetService("GuiService")
function Library.keepOnScreen(target)
	local holder = Library.Holder and Library.Holder.Instance
	if not (holder and target and target.Parent) then return end
	local view = holder.AbsoluteSize
	local a, z = target.AbsolutePosition, target.AbsoluteSize
	-- the holder ignores the top bar inset, but AbsolutePosition does not count it: the screen's top edge is at -inset
	local top = -GuiService:GetGuiInset().Y
	local dx, dy = 0, 0
	if a.Y < top then dy = top - a.Y elseif a.Y > top + view.Y - 40 then dy = top + view.Y - 40 - a.Y end
	if a.X + z.X < 80 then dx = 80 - (a.X + z.X) elseif a.X > view.X - 80 then dx = view.X - 80 - a.X end
	if dx ~= 0 or dy ~= 0 then
		local p = target.Position
		target.Position = UDim2.new(p.X.Scale, p.X.Offset + dx, p.Y.Scale, p.Y.Offset + dy)
	end
end

-- ---- dragging ----
local function makeDraggable(handle, target)
	Library:Connect(handle.InputBegan, function(i)
		if i.UserInputType ~= MB1 and i.UserInputType ~= TOUCH then return end
		local start, startPos = i.Position, target.Position
		Library.beginDrag(function(m)
			local d = m.Position - start
			target.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
			Library.keepOnScreen(target)
		end)
	end)
end
Library.MakeDraggable = makeDraggable

local function listLayout(parent, pad, dir)
	local l = Instance.new("UIListLayout")
	l.Padding = UDim.new(0, pad or 0)
	l.SortOrder = Enum.SortOrder.LayoutOrder
	if dir then l.FillDirection = dir end
	l.Parent = parent
	return l
end
Library.listLayout = listLayout

local function click(inst, fn)
	local b = Instance.new("TextButton")
	b.BackgroundTransparency = 1
	b.Text = ""
	b.AutoButtonColor = false
	b.Size = UDim2.fromScale(1, 1)
	b.ZIndex = inst.ZIndex + 1
	b.Parent = inst
	if fn then Library:Connect(b.MouseButton1Click, fn) end
	return b
end
Library.click = click

-- ---- touch devices ----
-- Library.IsMobile: a phone or tablet (touch, no physical keyboard). Env.Mobile / getgenv().AllisonMobile = true forces it, false turns it off.
do
	local forced = Library.Env.Mobile
	if forced == nil and getgenv then forced = getgenv().AllisonMobile end
	if forced ~= nil then
		Library.IsMobile = forced == true
	else
		Library.IsMobile = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
	end
end
function Library:FitScaleFor(w, h)
	local cam = workspace.CurrentCamera
	local v = cam and cam.ViewportSize or Vector2.new(1280, 720)
	return math.clamp(math.min(v.X * 0.96 / math.max(w, 1), v.Y * 0.92 / math.max(h, 1)), 0.35, 1)
end
-- the circle that opens / closes every window instead of the keybind; drag it to move it (a tap that moves less than 8 px toggles)
function Library:MobileButton(title)
	if self.MobileToggle or not self.Alive then return self.MobileToggle end
	local SIZE = 52
	local cam = workspace.CurrentCamera
	local function viewport() return cam and cam.ViewportSize or Vector2.new(1280, 720) end
	local btn = Instance.new("TextButton")
	btn.Name = "\0"
	btn.AutoButtonColor, btn.Text, btn.BorderSizePixel = false, "", 0
	btn.Size = UDim2.fromOffset(SIZE, SIZE)
	btn.Position = UDim2.new(1, -SIZE - 14, 0.5, -SIZE / 2)
	btn.ZIndex = 9000
	btn.BackgroundColor3 = self.Theme["Window Background"]
	Library.themed(btn, "BackgroundColor3", "Window Background")
	Instance.new("UICorner", btn).CornerRadius = UDim.new(0.5, 0)
	local stroke = Instance.new("UIStroke", btn)
	stroke.Thickness, stroke.ApplyStrokeMode, stroke.Color = 2, Enum.ApplyStrokeMode.Border, self.Theme.Accent
	Library.themed(stroke, "Color", "Accent")
	local scale = Instance.new("UIScale", btn)
	local glyph = Instance.new("TextLabel")
	glyph.Name = "\0"
	glyph.BackgroundTransparency, glyph.Size, glyph.ZIndex = 1, UDim2.fromScale(1, 1), 9001
	glyph.FontFace, glyph.TextSize = self.FontBold, 24
	glyph.Text = string.upper(tostring(title or "A"):sub(1, 1))
	glyph.TextColor3 = self.Theme.Accent
	Library.themed(glyph, "TextColor3", "Accent")
	glyph.Parent = btn
	-- the Allison logo over the letter when its image could be loaded
	local logoId = Build.IconAsset.fx_allisonlogo
	if logoId and logoId ~= "" then
		local logo = Instance.new("ImageLabel")
		logo.Name = "\0"
		logo.BackgroundTransparency, logo.ZIndex, logo.ScaleType = 1, 9002, Enum.ScaleType.Fit
		logo.AnchorPoint, logo.Position, logo.Size = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5), UDim2.fromOffset(36, 18)
		logo.Image, logo.ImageColor3 = logoId, self.Theme.Accent
		Library.themed(logo, "ImageColor3", "Accent")
		logo.Parent = btn
		glyph.Visible = false
	end
	btn.Parent = self.Holder.Instance
	local function anyOpen() for _, w in self.Windows do if w.IsOpen then return true end end return false end
	local function refresh()
		local open = anyOpen()
		Library.fx.tween(btn, { BackgroundTransparency = open and 0 or 0.25 }, 0.15)
		Library.fx.tween(glyph, { TextTransparency = open and 0 or 0.2 }, 0.15)
		local logo = btn:FindFirstChildOfClass("ImageLabel")
		if logo then Library.fx.tween(logo, { ImageTransparency = open and 0 or 0.2 }, 0.15) end
	end
	local drag, moved, startAt, startPos
	self:Connect(btn.InputBegan, function(i)
		if i.UserInputType ~= Enum.UserInputType.Touch and i.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
		drag, moved = i, false
		startAt, startPos = Vector2.new(i.Position.X, i.Position.Y), Vector2.new(btn.AbsolutePosition.X, btn.AbsolutePosition.Y)
		Library.fx.tween(scale, { Scale = 0.92 }, 0.08)
	end)
	self:Connect(UserInputService.InputChanged, function(i)
		if not drag or not (i == drag or i.UserInputType == Enum.UserInputType.MouseMovement) then return end
		local d = Vector2.new(i.Position.X, i.Position.Y) - startAt
		if not moved and d.Magnitude < 8 then return end
		moved = true
		local v = viewport()
		-- the holder ignores the top bar inset, so AbsolutePosition and the input position share one origin
		btn.Position = UDim2.fromOffset(math.clamp(startPos.X + d.X, 4, v.X - SIZE - 4), math.clamp(startPos.Y + d.Y, 4, v.Y - SIZE - 4))
	end)
	self:Connect(UserInputService.InputEnded, function(i)
		if not drag or not (i == drag or i.UserInputType == Enum.UserInputType.MouseButton1) then return end
		local wasTap = not moved
		drag = nil
		Library.fx.tween(scale, { Scale = 1 }, 0.12)
		if wasTap then
			local open = not anyOpen()
			for _, w in self.Windows do w:SetOpen(open) end
			refresh()
		end
	end)
	self.MobileToggle = { Button = btn, Refresh = refresh }
	refresh()
	return self.MobileToggle
end

-- ---- Window ----
-- Aurora Hex: a double-edged flat window, the name centred in the top edge ("aurora hex" = the first word in the accent colour,
-- the rest white), a search field top right, equal-width tabs across the top, the pages below. Dragged by the title row, resized
-- by the grip in the bottom-right corner. Every call makes another window (a second one opens offset from the first).
function Library:Window(Data)
	Data = Data or {}
	local name = field(Data, "Name", "name") or "Otterhook.cc"
	local size = field(Data, "Size", "size")
	local fx = Library.fx
	local W = Build.Window(self.Holder.Instance)
	local root = W.Root
	root.Name = "\0"
	root.AnchorPoint = Vector2.new(0.5, 0.5)
	local nth = #self.Windows
	root.Position = UDim2.new(0.5, nth * 28, 0.5, nth * 28)
	root.Size = typeof(size) == "UDim2" and size or UDim2.fromOffset(550, 570)   -- Otterhook: default 550 x 570
	-- the two-tone title, left in the header: "Cadia.xyz" = the name in white, its extension (from the last dot) in the accent colour.
	-- A name without a dot: the first word white, the rest in the accent.
	local first, rest = tostring(name):match("^(.-)(%.[%w_]+)$")
	if not first then first, rest = tostring(name):match("^(%S+)(%s*.*)$") end
	W.title.Text, W.title2.Text = first or tostring(name), rest or ""
	for _, t in { W.title, W.title2 } do
		t.FontFace = Library.FontBold
		t.AutomaticSize = Enum.AutomaticSize.X
		t.Size = UDim2.new(0, 0, 1, 0)
		t.TextXAlignment = Enum.TextXAlignment.Left
	end
	W.title.LayoutOrder, W.title2.LayoutOrder = 1, 2
	local tl = listLayout(W.titleRow, 0, Enum.FillDirection.Horizontal)
	tl.HorizontalAlignment, tl.VerticalAlignment = Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center
	W.title2.Visible = W.title2.Text ~= ""
	W.titleRow.AutomaticSize = Enum.AutomaticSize.X
	W.titleRow.Size = UDim2.new(0, 0, 0, 16)
	W.titleRow.ZIndex = 3
	W.accentLine.ZIndex = 4
	if W.logo then W.logo.ZIndex = 3 end
	-- depth: the window floats on a wide drop shadow, the header fades into the body, the page panel is sunk (dark, lit bottom edge)
	fx.shadow(root, { radius = 14, transparency = 0.05 })
	fx.shade(W.inner, 0.22)
	fx.shade(W.accentLine, 0.3)
	-- tabs and pages
	listLayout(W.tabs, 0, Enum.FillDirection.Horizontal)
	local window = setmetatable({ Items = {}, Pages = {}, IsOpen = true, Library = self, _W = W, FadeWith = {} }, self)
	window.Items["Outline"] = wrapInst(root)
	window.Items["Title"] = wrapInst(W.titleRow)
	window.Items["Pages"] = wrapInst(W.tabs)
	window.Items["Content"] = wrapInst(W.pages)
	window.Items["Search"] = wrapInst(W.search)
	pcall(function()
		local sw = W.search and W.search.Size.X.Offset or 130
		W.dragBar.Position = UDim2.new(0, 2, 0, 2)
		W.dragBar.Size = UDim2.new(1, -(sw + 14), 0, 28)
	end)
	-- where the window is grabbed: a grip of dots at the left of the header, the header lights up under the mouse, and a tooltip
	pcall(function()
		local bar = W.dragBar
		bar.BackgroundColor3 = Library.Theme["Element Hover"] or Library.Theme.Element
		Library.themed(bar, "BackgroundColor3", "Element Hover")
		bar.BackgroundTransparency = 1
		bar.BorderSizePixel = 0
		local grip = Instance.new("Frame")
		grip.Name = "\0Grip"
		grip.BackgroundTransparency = 1
		grip.AnchorPoint = Vector2.new(0, 0.5)
		grip.Position, grip.Size = UDim2.new(0, 8, 0.5, 0), UDim2.fromOffset(8, 12)
		grip.ZIndex = bar.ZIndex + 1
		grip.Parent = bar
		grip.Visible = false   -- Cadia: the title sits where the grip dots would
		local dots = {}
		for r = 0, 2 do
			for c = 0, 1 do
				local d = Instance.new("Frame")
				d.Name = "\0"
				d.BorderSizePixel = 0
				d.Size = UDim2.fromOffset(2, 2)
				d.Position = UDim2.fromOffset(c * 5, r * 5)
				d.BackgroundColor3 = Library.Theme["Dim Text"]
				Library.themed(d, "BackgroundColor3", "Dim Text")
				d.ZIndex = grip.ZIndex
				d.Parent = grip
				dots[#dots + 1] = d
			end
		end
		Library:Connect(bar.MouseEnter, function()
			Library.fx.tween(bar, { BackgroundTransparency = 0.75 }, 0.12)
			for _, d in dots do Library.fx.tween(d, { BackgroundColor3 = Library.Theme.Accent }, 0.12) end
		end)
		Library:Connect(bar.MouseLeave, function()
			Library.fx.tween(bar, { BackgroundTransparency = 1 }, 0.18)
			for _, d in dots do Library.fx.tween(d, { BackgroundColor3 = Library.Theme["Dim Text"] }, 0.18) end
		end)
		if Library.attachTooltip then Library.attachTooltip(bar, "Drag here to move the menu") end
	end)
	makeDraggable(W.titleRow, root)
	makeDraggable(W.dragBar, root)
	window.SearchItems, window.SectionList = {}, {}
	-- the search field: a real TextBox over the design's text
	W.searchText.Visible = false
	local sbox = Instance.new("TextBox")
	sbox.BackgroundTransparency, sbox.BorderSizePixel = 1, 0
	sbox.Size, sbox.Position = UDim2.new(1, -20, 1, 0), UDim2.new(0, 18, 0, 0)
	sbox.FontFace, sbox.TextSize, sbox.TextXAlignment = Library.Font, 12, Enum.TextXAlignment.Left
	sbox.ZIndex = 5
	sbox.TextColor3, sbox.PlaceholderColor3 = Library.Theme.Text, Library.Theme["Dim Text"]
	sbox.PlaceholderText, sbox.Text, sbox.ClearTextOnFocus = "search", "", false
	sbox.Parent = W.search
	window.Items["SearchBox"] = wrapInst(sbox)
	Library:Connect(sbox:GetPropertyChangedSignal("Text"), function() if Library.SearchWindow then Library.SearchWindow(window, sbox.Text) end end)
	local searchStroke = W.search:FindFirstChildOfClass("UIStroke")
	Library:Connect(sbox.Focused, function() if searchStroke then Library.themed(searchStroke, "Color", "Accent") end end)
	Library:Connect(sbox.FocusLost, function() if searchStroke then Library.themed(searchStroke, "Color", "Outline") end end)
	-- resize from the grip (sizes are offsets; the window's centre anchor moves by half the growth so the top-left corner stays put)
	do
		local dragging, start, startSize, startPos = false, nil, nil, nil
		local btn = click(W.grip)
		local resize
		Library:Connect(btn.InputBegan, function(i)
			if i.UserInputType ~= Enum.UserInputType.MouseButton1 and i.UserInputType ~= Enum.UserInputType.Touch then return end
			dragging, start, startSize, startPos = true, Vector2.new(i.Position.X, i.Position.Y), root.Size, root.Position
			Library.beginDrag(resize, function() dragging = false end)
		end)
		resize = function(i)
			if not dragging then return end
			local d = Vector2.new(i.Position.X, i.Position.Y) - start
			local sc = root:FindFirstChildOfClass("UIScale")
			local k = (sc and sc.Scale > 0) and sc.Scale or 1
			local w = math.max(startSize.X.Offset + d.X / k, 480)
			local h = math.max(startSize.Y.Offset + d.Y / k, 360)
			root.Size = UDim2.new(startSize.X.Scale, w, startSize.Y.Scale, h)
			root.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + (w - startSize.X.Offset) * k / 2, startPos.Y.Scale, startPos.Y.Offset + (h - startSize.Y.Offset) * k / 2)
		end
	end
	-- open / close: the window fades and pops in, and fades and shrinks away. It animates the UIScale already on the window (a script's DPI setting puts
	-- one there) around its current value, or a temporary one that is removed afterwards. The fade is a CanvasGroup over the whole screen that holds the
	-- window (and window.FadeWith: frames that belong to it) only while it runs, because text in a CanvasGroup is softer.
	local anim = { token = 0 }
	local function fadeGroup()
		if not anim.group then
			local g = Instance.new("CanvasGroup")
			g.Name = "\0"
			g.BackgroundTransparency, g.BorderSizePixel = 1, 0
			g.Size = UDim2.fromScale(1, 1)
			g.ZIndex = root.ZIndex
			g.Parent = root.Parent
			anim.group, anim.home = g, root.Parent
		end
		anim.group.Visible = true
		root.Parent = anim.group
		for _, f in window.FadeWith do if f.Parent then f.Parent = anim.group end end
		return anim.group
	end
	local function fadeDone()
		if not anim.group then return end
		if root.Parent ~= anim.home then root.Parent = anim.home end
		for _, f in window.FadeWith do if f.Parent and f.Parent ~= anim.home then f.Parent = anim.home end end
		anim.group.Visible = false
	end
	function window:SetOpen(bool)
		self.IsOpen = bool
		if bool then task.defer(function() pcall(Library.keepOnScreen, root) end) end
		anim.token += 1
		local my = anim.token
		if Library.UpdateBlur then Library.UpdateBlur() end
		if self.OnOpen then self.OnOpen(bool) end
		if Library.MobileToggle then Library.MobileToggle.Refresh() end
		if not (Library.Animations and Library.SmoothOpen) then
			-- the cheap path: show / hide at once. (An animation that was still running is finished first, so nothing stays in the CanvasGroup.)
			if anim.base then
				local sc0 = anim.temp or root:FindFirstChildOfClass("UIScale")
				if sc0 then sc0.Scale = anim.base end
				anim.base = nil
				if anim.temp then anim.temp:Destroy() anim.temp = nil end
			end
			fadeDone()
			root.Visible = bool
			return
		end
		local sc = anim.temp or root:FindFirstChildOfClass("UIScale")
		if not anim.base then
			if not sc then
				sc = Instance.new("UIScale")
				sc.Name = "\0Open"
				sc.Parent = root
				anim.temp = sc
			end
			anim.base = sc.Scale
		end
		local base = anim.base
		local function finish()
			if anim.token ~= my then return end
			sc.Scale = base
			anim.base = nil
			if anim.temp then anim.temp:Destroy() anim.temp = nil end
			fadeDone()
		end
		local group = fadeGroup()
		if bool then
			if not root.Visible then
				sc.Scale = base * 0.94
				group.GroupTransparency = 1
			end
			root.Visible = true
			fx.tween(group, { GroupTransparency = 0 }, 0.2, Enum.EasingStyle.Quad)
			fx.tween(sc, { Scale = base }, 0.22, Enum.EasingStyle.Quint).Completed:Connect(finish)
		else
			fx.tween(group, { GroupTransparency = 1 }, 0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			fx.tween(sc, { Scale = base * 0.94 }, 0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.In).Completed:Connect(function()
				if anim.token == my then root.Visible = false end
				finish()
			end)
		end
	end
	Library:Connect(UserInputService.InputBegan, function(i, gpe)
		if gpe and UserInputService:GetFocusedTextBox() then return end
		if tostring(i.KeyCode) == Library.MenuKeybind or tostring(i.UserInputType) == Library.MenuKeybind then window:SetOpen(not window.IsOpen) end
	end)
	-- phones and tablets: the window is scaled to fit the screen (window.UserScale, e.g. a script's DPI setting, multiplies it) and the
	-- circle button opens / closes the menu instead of the keybind
	window.UserScale = 1
	function window:Refit()
		if anim.base then return end   -- an open / close animation owns the scale right now
		local sc = root:FindFirstChildOfClass("UIScale")
		if not Library.IsMobile then
			if sc and sc.Name == "\0Fit" then sc.Scale = self.UserScale end
			return
		end
		if not sc then
			sc = Instance.new("UIScale")
			sc.Name = "\0Fit"
			sc.Parent = root
		end
		Library.FitScale = Library:FitScaleFor(root.Size.X.Offset, root.Size.Y.Offset)
		sc.Scale = Library.FitScale * self.UserScale
	end
	if Library.IsMobile then
		-- not on every Size change: the resize grip would fight the fit. A script that sets the size after creating the window calls window:Refit().
		task.delay(0.5, function() if Library.Alive then window:Refit() end end)
		local cam = workspace.CurrentCamera
		if cam then Library:Connect(cam:GetPropertyChangedSignal("ViewportSize"), function() window:Refit() end) end
		root.Position = UDim2.fromScale(0.5, 0.5)
		window:Refit()
		Library:MobileButton(name)
	end
	self.Windows[#self.Windows + 1] = window
	self.Window_ = self.Window_ or window
	return window
end

-- popups (dropdown lists, colour pickers, key modes) live INSIDE the window frame: coordinates relative to it need no inset maths and
-- they move with the window
-- elements register themselves for the window search (name -> frame)
function Library.regSearch(section, root, name)
	if not (section and section.Window and root) then return end
	table.insert(section.Window.SearchItems, { root = root, name = tostring(name or ""), section = section })
end
function Library.popupRoot(section) return section.Window._W.Root end
function Library.popupAt(popup, root, anchor, dy)
	local ra, a, s = root.AbsolutePosition, anchor.AbsolutePosition, anchor.AbsoluteSize
	popup.Position = UDim2.new(0, a.X - ra.X, 0, a.Y - ra.Y + s.Y + (dy or 4))
end

-- A popup (dropdown list, colour picker, keybind mode list) is placed once, in window coordinates. When its anchor then moves inside
-- the window (the page was scrolled) the popup would stay behind, floating over something else, so it is closed instead.
-- Moving the whole window does not count (the popup is a child of the window and moves with it); neither does the window's own
-- open / scale animation (the offset is compared unscaled). Returns a function that stops watching.
function Library.watchAnchor(anchor, root, close)
	local function rel()
		local sc = root:FindFirstChildOfClass("UIScale")
		local k = (sc and sc.Scale > 0) and sc.Scale or 1
		return (anchor.AbsolutePosition - root.AbsolutePosition) / k
	end
	local r0 = rel()
	local conn
	conn = anchor:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
		local r = rel()
		if math.abs(r.X - r0.X) > 2 or math.abs(r.Y - r0.Y) > 2 then
			conn:Disconnect()
			close()
		end
	end)
	return function() if conn.Connected then conn:Disconnect() end end
end

-- ---- Page ----
-- Otterhook: the top row holds the CATEGORIES, a second row of sub-tabs (the pages of the category and their SubPages) sits under it
-- when the category has more than one page. Data.Category starts a category; once one was given, a page without it joins the current
-- category (like a sidebar heading); before that every page is a category of its own (the plain Window:Page{Name} use).
-- Data.SubName = the page's label in the sub-tab row (default: its Name). Page:SubPage{Name, Columns} adds a page right after it.
local SUBH, SUBW_MIN = 26, 66
function Library:Page(Data)
	Data = Data or {}
	local window = self
	local W = window._W
	local fx = Library.fx
	window.Groups = window.Groups or {}

	local function relayout(g)
		local show = #g.Pages > 1
		local x = 0
		for _, p in g.Pages do
			p.SubRoot.Position = UDim2.new(0, x, 0, 0)
			x += p.SubRoot.Size.X.Offset + 2
			p.Holder.Position = UDim2.new(0, 0, 0, show and (SUBH + 2) or 0)
			p.Holder.Size = UDim2.new(1, 0, 1, show and -(SUBH + 2) or 0)
		end
		g.SubBar.Visible = show and window.Current ~= nil and window.Current.Group == g
	end

	local function show(page, instant)
		local g = page.Group
		window.Current = page
		g.Last = page
		for _, gr in window.Groups do
			local on = gr == g
			Library:ChangeItemTheme(gr.T.bar, { BackgroundColor3 = on and "Header" or "Window Background" })
			fx.tween(gr.T.bar, { BackgroundColor3 = on and Library.Theme.Header or Library.Theme["Window Background"] }, instant and 0 or 0.18)
			Library:ChangeItemTheme(gr.T.label, { TextColor3 = on and "Bright Text" or "Dim Text" })
			fx.tween(gr.T.label, { TextColor3 = on and Library.Theme["Bright Text"] or Library.Theme["Dim Text"] }, instant and 0 or 0.18)
			gr.T.label.FontFace = on and Library.FontBold or Library.Font
			if gr.icon then fx.tween(gr.icon, { ImageColor3 = on and Library.Theme.Accent or Library.Theme["Dim Text"] }, instant and 0 or 0.18) end
			gr.SubBar.Visible = on and #gr.Pages > 1
		end
		for _, p in window.Pages do
			local on = p == page
			if p.Group == g then
				Library:ChangeItemTheme(p.SubT.bar, { BackgroundColor3 = on and "Header" or "Window Background" })
				fx.tween(p.SubT.bar, { BackgroundColor3 = on and Library.Theme.Header or Library.Theme["Window Background"] }, instant and 0 or 0.15)
				Library:ChangeItemTheme(p.SubT.label, { TextColor3 = on and "Bright Text" or "Dim Text" })
				fx.tween(p.SubT.label, { TextColor3 = on and Library.Theme["Bright Text"] or Library.Theme["Dim Text"] }, instant and 0 or 0.15)
				p.SubLine.Visible = on
			end
			if on then
				if not p.Holder.Visible and not instant then
					local base = p.Holder.Position
					p.Holder.Position = base + UDim2.fromOffset(0, 8)
					p.Holder.Visible = true
					fx.tween(p.Holder, { Position = base }, 0.22)
				else
					p.Holder.Visible = true
				end
			else
				p.Holder.Visible = false
			end
		end
	end
	window.ShowPage = show

	local function newGroup(name, iconKey)
		local g = { Name = name, Pages = {} }
		g.T = Build.Tab(W.tabs)
		g.T.Root.LayoutOrder = #window.Groups + 1
		g.T.label.Text = tostring(name)
		g.T.label.Position, g.T.label.Size = UDim2.fromOffset(0, -1), UDim2.new(1, 0, 1, 0)   -- (-1: optical centre, measured)
		g.T.bar.ZIndex, g.T.label.ZIndex = 1, 2
		fx.shade(g.T.bar, 0.3)
		-- the icon (Font Awesome Free, assets/tab_icons.json) left of the name: Data.Icon, else the category / page name ("Anti-Aim" -> antiaim). The name stays
		-- centred on the tab; the icon hangs to its left and is left out when the tab is too narrow for it.
		local iconId = Build.IconAsset["tab_" .. iconKey]
		if iconId and iconId ~= "" then
			local icon = Instance.new("ImageLabel")
			icon.Name = "\0"
			icon.BackgroundTransparency, icon.BorderSizePixel = 1, 0
			icon.Image = iconId
			icon.AnchorPoint = Vector2.new(0, 0.5)
			icon.Size = UDim2.fromOffset(14, 14)
			icon.ImageColor3 = Library.Theme["Dim Text"]
			icon.ZIndex = 3
			icon.Parent = g.T.Root
			local function place()
				local b = g.T.label.TextBounds.X
				local w = g.T.Root.AbsoluteSize.X
				local sc = W.Root:FindFirstChildOfClass("UIScale")
				if sc and sc.Scale > 0 then w = w / sc.Scale end
				icon.Visible = (w - b) / 2 >= 24
				-- icon (14) + gap (7) + name are centred as one group: the name moves right by half the icon's share
				local shift = icon.Visible and math.floor(21 / 2 + 0.5) or 0
				g.T.label.Position = UDim2.fromOffset(shift, -1)   -- (-1: Ubuntu sits ~1 px low in its line box, measured)
				icon.Position = UDim2.new(0.5, -(b / 2) - 21 + shift, 0.5, 0)
			end
			g.T.label:GetPropertyChangedSignal("TextBounds"):Connect(place)
			g.T.Root:GetPropertyChangedSignal("AbsoluteSize"):Connect(place)
			place()
			g.icon = icon
		end
		g.SubBar = Instance.new("Frame")
		g.SubBar.Name = "\0"
		g.SubBar.BackgroundTransparency, g.SubBar.BorderSizePixel = 1, 0
		g.SubBar.Size = UDim2.new(1, 0, 0, SUBH)
		g.SubBar.ZIndex = 5
		g.SubBar.Visible = false
		g.SubBar.Parent = W.pages
		local rule = Instance.new("Frame")
		rule.Name = "\0"
		rule.BorderSizePixel = 0
		rule.Position, rule.Size = UDim2.new(0, 0, 1, -1), UDim2.new(1, 0, 0, 1)
		rule.ZIndex = 5
		Library:AddToTheme(rule, { BackgroundColor3 = "Border" })
		rule.Parent = g.SubBar
		table.insert(window.Groups, g)
		local n = #window.Groups
		for _, gr in window.Groups do gr.T.Root.Size = UDim2.new(1 / n, 0, 1, 0) end
		local btn = click(g.T.Root, function() show(g.Last or g.Pages[1]) end)
		fx.hover(btn, function() if window.Current and window.Current.Group ~= g then fx.tween(g.T.label, { TextColor3 = Library.Theme.Text }, 0.12) end end,
			function() if window.Current and window.Current.Group ~= g then fx.tween(g.T.label, { TextColor3 = Library.Theme["Dim Text"] }, 0.18) end end)
		return g
	end

	local function build(d, group, parent)
		local name = field(d, "Name", "name") or "Page"
		local columns = field(d, "Columns", "columns") or 2
		local label = tostring(field(d, "SubName", "subname") or name)
		local holder = Instance.new("Frame")
		holder.Name = "\0"
		holder.BackgroundTransparency = 1
		holder.Size = UDim2.fromScale(1, 1)
		holder.Visible = false
		holder.Parent = W.pages
		listLayout(holder, 0, Enum.FillDirection.Horizontal)
		local page = setmetatable({ Items = {}, ColumnsData = {}, Window = window, Library = Library, Name = name, Columns = columns, Group = group, Holder = holder, Subs = {} }, Library)
		for i = 1, columns do
			local col = Instance.new("ScrollingFrame")
			col.Name = "\0"
			col.BackgroundTransparency = 1
			col.BorderSizePixel = 0
			col.ScrollBarThickness = 2
			col.ScrollBarImageColor3 = Library.Theme.Accent
			Library:AddToTheme(col, { ScrollBarImageColor3 = "Accent" })
			col.CanvasSize = UDim2.new()
			col.AutomaticCanvasSize = Enum.AutomaticSize.Y
			col.Size = UDim2.new(1 / columns, 0, 1, 0)
			col.Parent = holder
			local cpad = Instance.new("UIPadding")
			cpad.PaddingLeft = UDim.new(0, i == 1 and 1 or 3)
			cpad.PaddingRight = UDim.new(0, i == columns and 4 or 3)
			cpad.PaddingTop = UDim.new(0, 1)
			cpad.PaddingBottom = UDim.new(0, 6)
			cpad.Parent = col
			listLayout(col, 6)
			page.ColumnsData[i] = wrapInst(col)
		end
		-- the sub-tab button (a Tab of the design sheet, narrower)
		local S = Build.Tab(group.SubBar)
		local w = math.clamp(math.floor(#label * 7 + 22), SUBW_MIN, 150)
		S.Root.Size = UDim2.new(0, w, 1, -1)
		S.label.Text = label
		S.label.Position, S.label.Size = UDim2.fromOffset(0, -1), UDim2.new(1, 0, 1, 0)   -- (-1: optical centre, measured)
		S.bar.ZIndex, S.label.ZIndex = 6, 7
		fx.shade(S.bar, 0.3)
		local line = Instance.new("Frame")
		line.Name = "\0"
		line.BorderSizePixel = 0
		line.AnchorPoint, line.Position, line.Size = Vector2.new(0, 1), UDim2.new(0, 0, 1, 0), UDim2.new(1, 0, 0, 2)
		line.ZIndex = 8
		line.Visible = false
		Library:AddToTheme(line, { BackgroundColor3 = "Accent" })
		line.Parent = S.Root
		page.SubT, page.SubRoot, page.SubLine, page.SubLabel = S, S.Root, line, S.label
		page.Items["Inactive"] = wrapInst(S.Root)
		page.Items["Page"] = wrapInst(holder)
		-- where it goes in the category: right after its parent page (and the sub-pages that parent already has)
		local at = #group.Pages + 1
		if parent then
			local last = parent.Subs[#parent.Subs] or parent
			for i, p in group.Pages do if p == last then at = i + 1 end end
			table.insert(parent.Subs, page)
		end
		table.insert(group.Pages, at, page)
		table.insert(window.Pages, page)
		relayout(group)
		function page:Select() show(page) end
		function page:SubPage(sd) return build(sd or {}, group, parent or page) end
		function page:Turn(b, keep)
			if b then show(page, keep) elseif window.Current ~= page then holder.Visible = false end
		end
		local btn = click(S.Root, function() show(page) end)
		fx.hover(btn, function() if window.Current ~= page then fx.tween(S.label, { TextColor3 = Library.Theme.Text }, 0.12) end end,
			function() if window.Current ~= page then fx.tween(S.label, { TextColor3 = Library.Theme["Dim Text"] }, 0.18) end end)
		if #window.Pages == 1 then
			show(page, true)
		else
			-- not the open page: its sub-tab is drawn in the idle colours
			Library:ChangeItemTheme(S.bar, { BackgroundColor3 = "Window Background" })
			Library:ChangeItemTheme(S.label, { TextColor3 = "Dim Text" })
			S.bar.BackgroundColor3 = Library.Theme["Window Background"]
			S.label.TextColor3 = Library.Theme["Dim Text"]
			if window.Current and window.Current.Group == group then group.SubBar.Visible = #group.Pages > 1 end
		end
		return page
	end

	local category = field(Data, "Category", "category")
	local iconKey = tostring(field(Data, "Icon", "icon") or string.lower((tostring(category or field(Data, "Name", "name") or "page"):gsub("[^%w]", ""))))
	local group
	if category then
		for _, g in window.Groups do if g.Name == category then group = g end end
		group = group or newGroup(category, iconKey)
		window.CurGroup = group
	elseif window.CurGroup then
		group = window.CurGroup
	else
		group = newGroup(field(Data, "Name", "name") or "Page", iconKey)
	end
	return build(Data, group, nil)
end

-- ---- Section (a header bar with the accent line on its left; a click on the header folds the section) ----
function Library:Section(Data)
	Data = Data or {}
	local page = self
	local fx = Library.fx
	local name = field(Data, "Name", "name") or "Section"
	local side = field(Data, "Side", "side") or 1
	local colWrap = page.ColumnsData[math.clamp(side, 1, page.Columns)]
	local S = Build.Section(colWrap.Instance)
	S.title.Text = tostring(name)
	S.title.Position += UDim2.fromOffset(0, -2)   -- Otterhook: centred in the 20 px header (was 2 px low)
	S.fold.Position += UDim2.fromOffset(0, -2)
	S.card.Position = UDim2.new()
	S.content.AutomaticSize = Enum.AutomaticSize.Y
	S.content.Position, S.content.Size = UDim2.new(0, 5, 0, 24), UDim2.new(1, -10, 0, 0)
	local contentList = listLayout(S.content, 2)
	S.head.ZIndex, S.accent.ZIndex = 2, 3
	-- depth: the header is lit from above, the card drops a soft shadow on the panel
	fx.shade(S.head, 0.26)
	fx.shade(S.accent, 0.3)
	fx.shadow(S.card, { radius = 6, transparency = 0.45 })
	local section = setmetatable({ Items = {}, Page = page, Window = page.Window, Library = Library, Name = name, Collapsed = false }, Library)
	-- The height follows the elements (set here, not AutomaticSize: an auto-sized card would also count its drop shadow, which sticks out)
	local function fit()
		local h = section.Collapsed and 20 or (24 + contentList.AbsoluteContentSize.Y + 6)
		S.Root.Size = UDim2.new(1, 0, 0, h + 2)
		S.card.Size = UDim2.new(1, 0, 0, h)
	end
	contentList:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(fit)
	local function fold(b)
		section.Collapsed = b and true or false
		S.content.Visible = not section.Collapsed
		S.fold.Text = section.Collapsed and "+" or "-"
		fit()
	end
	fit()
	function section:SetCollapsed(b) fold(b) end
	local hb = click(S.head, function() fold(not section.Collapsed) end)
	fx.hover(hb, function() fx.tween(S.fold, { TextColor3 = Library.Theme.Accent }, 0.12) end, function() fx.tween(S.fold, { TextColor3 = Library.Theme["Dim Text"] }, 0.18) end)
	if field(Data, "Collapsed", "collapsed") then fold(true) end
	table.insert(page.Window.SectionList, { section = section, root = S.Root, page = page, name = tostring(name) })
	section.Items["Section"] = wrapInst(S.Root)
	section.Items["Content"] = wrapInst(S.content)
	section._S = S
	return section
end


-- ===== runtime/fx.lua =====
-- runtime part 1b (Otterhook): fx - drop shadows, glows, bevels, hover / press / ripple and the shared tween. Uses Library, Build from core.
-- The shadow / glow images (fx_shadow, fx_glow, fx_ripple; tools/fxassets.mjs) are 128 px 9-slice PNGs whose box (24..104, radius 10)
-- is punched out: they are parented INSIDE the element (a child always draws above its parent with ZIndexBehavior.Sibling) and only
-- the halo outside the element shows. Without getcustomasset the images are "" and the effects quietly do nothing.
local fx = {}
Library.fx = fx
Library.Animations = true
-- The open / close fade + scale (window.SetOpen) puts the whole window, the ESP preview and the chat into one full-screen CanvasGroup and scales
-- it, which redraws hundreds of elements every frame for 0.2 s: a frame drop in heavy games. Off by default; a script can offer it as a setting.
Library.SmoothOpen = true   -- Cadia: the animated open / close is on (a script can still switch it off)
-- Aurora Hex is flat (imgui): no bevels, glows or ripples unless an element forces one (opt.force / fx.bevel(..., true)). Drop shadows
-- ARE drawn, square like the boxes: two layers of fx_shadowsq (a 3 px dropped, square-holed 9-slice), a wide soft ambient one and a
-- tight key one just under the box, so floating panels sit above the window. Library.Shadows = false turns them off.
local FLAT = true
local SLICE = Rect.new(34, 34, 94, 94)
local SLICE_SQ = Rect.new(26, 26, 102, 102)
Library.Shadows = true
-- Cadia keeps the sharp square boxes but is not flat: fills are lit from above (fx.shade / fx.bevel) and floating things drop shadows.
-- Library.Depth = false makes it flat again (before the window is built).
Library.Depth = true

-- every animation goes through here; Library.Animations = false makes them instant
function fx.tween(inst, props, t, style, dir)
	local tw = TweenService:Create(inst, TweenInfo.new(Library.Animations and (t or 0.2) or 0, style or Enum.EasingStyle.Quint, dir or Enum.EasingDirection.Out), props)
	tw:Play()
	return tw
end

-- a UIPadding on the element moves and shrinks its children, so the halo is pushed back out by the same amount
local function padOf(inst)
	local p = inst:FindFirstChildOfClass("UIPadding")
	if not p then return 0, 0, 0, 0 end
	return p.PaddingLeft.Offset, p.PaddingRight.Offset, p.PaddingTop.Offset, p.PaddingBottom.Offset
end

-- fx.shadow(inst, { radius, transparency, color (theme key or Color3), glow }) -> ImageLabel
-- radius = the element's corner radius, so the punched-out hole matches its corners
local function layer(inst, spread, transparency, l, r, t, b, name)
	local img = Instance.new("ImageLabel")
	img.Name = name
	img.BackgroundTransparency, img.BorderSizePixel = 1, 0
	img.Image = Build.IconAsset.fx_shadowsq or ""
	img.ScaleType = Enum.ScaleType.Slice
	img.SliceCenter = SLICE_SQ
	img.SliceScale = spread / 24
	img.Position = UDim2.new(0, -spread - l, 0, -spread - t)
	img.Size = UDim2.new(1, spread * 2 + l + r, 1, spread * 2 + t + b)
	img.ImageTransparency = transparency
	img.ZIndex = 0
	img.Parent = inst
	Library:AddToTheme(img, { ImageColor3 = "Shadow" })
	return img
end
-- the layered square shadow: the ambient layer is returned (callers tween its ImageTransparency); the key layer follows it
local function squareShadow(inst, opt)
	local l, r, t, b = padOf(inst)
	local size = math.clamp((opt.radius or 10) / 12, 0.3, 1)   -- the old corner radius doubles as "how far it floats"
	local amb = layer(inst, 24 * size, 1, l, r, t, b, "ShadowAmbient")
	-- the key layer (dark, short, right under the box) only for things that float: panels, popups, windows (radius >= 10).
	-- Buttons and swatches (there are hundreds) keep the one soft layer.
	local key = (opt.radius or 10) >= 10 and layer(inst, math.max(6 * size, 3), 1, l, r, t, b, "ShadowKey") or nil
	local function follow()
		local a = amb.ImageTransparency
		-- the ambient layer is soft and wide (it carries the given transparency); the key layer is darker and short
		if key then key.ImageTransparency = 1 - (1 - a) * 0.85 end
	end
	if key then amb:GetPropertyChangedSignal("ImageTransparency"):Connect(follow) end
	amb.ImageTransparency = math.clamp((opt.transparency or 0.35) + 0.1, 0, 1)
	follow()
	return amb
end
function fx.shadow(inst, opt)
	opt = opt or {}
	if not opt.glow and Library.Shadows and Build.IconAsset.fx_shadowsq then return squareShadow(inst, opt) end
	if FLAT and not opt.force then return Instance.new("ImageLabel") end
	local s = (opt.radius or 10) / 10
	local spread = 24 * s
	local l, r, t, b = padOf(inst)
	local img = Instance.new("ImageLabel")
	img.Name = opt.glow and "\0Glow" or "\0Shadow"
	img.BackgroundTransparency, img.BorderSizePixel = 1, 0
	img.Image = Build.IconAsset[opt.glow and "fx_glow" or "fx_shadow"] or ""
	img.ScaleType = Enum.ScaleType.Slice
	img.SliceCenter = SLICE
	img.SliceScale = s
	img.Position = UDim2.new(0, -spread - l, 0, -spread - t)
	img.Size = UDim2.new(1, spread * 2 + l + r, 1, spread * 2 + t + b)
	img.ImageTransparency = opt.transparency or 0.35
	img.ZIndex = 0
	img.Parent = inst
	local c = opt.color or (opt.glow and "Accent" or "Shadow")
	if type(c) == "string" then Library:AddToTheme(img, { ImageColor3 = c }) else img.ImageColor3 = c end
	return img
end
-- an accent halo that starts hidden; fx.glowTo(img, on) fades it
function fx.glow(inst, radius, strength)
	if FLAT then return nil end
	local g = fx.shadow(inst, { radius = radius, glow = true, transparency = 1 })
	g:SetAttribute("On", 1 - (strength or 0.55))
	return g
end
function fx.glowTo(g, on, t) if g then fx.tween(g, { ImageTransparency = on and g:GetAttribute("On") or 1 }, t or 0.25) end end

-- top-lit 3D look: the fill darkens towards the bottom and the border is bright on top, fading out downwards
function fx.bevel(inst, depth, force)
	if Library.Depth == false and not force then return end
	depth = depth or 0.14
	if not inst:FindFirstChildOfClass("UIGradient") then
		local g = Instance.new("UIGradient")
		g.Name = "\0Bevel"
		g.Rotation = 90
		local d = math.floor(255 * (1 - depth))
		g.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(d, d, d))
		g.Parent = inst
	end
	local st = inst:FindFirstChildOfClass("UIStroke")
	if st and not st:FindFirstChildOfClass("UIGradient") then
		Library:AddToTheme(st, { Color = "Highlight" })
		local g = Instance.new("UIGradient")
		g.Name = "\0Bevel"
		g.Rotation = 90
		g.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(110, 110, 110))
		g.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(0.5, 0.55), NumberSequenceKeypoint.new(1, 0.7) })
		g.Parent = st
	end
end

-- fx.shade(inst, depth): only the top-lit gradient of the fill (the edge keeps its own colour): bars, checkboxes, headers
function fx.shade(inst, depth)
	if Library.Depth == false or not inst or inst:FindFirstChildOfClass("UIGradient") then return end
	local g = Instance.new("UIGradient")
	g.Name = "\0Shade"
	g.Rotation = 90
	local d = math.floor(255 * (1 - (depth or 0.2)))
	g.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(d, d, d))
	g.Parent = inst
	return g
end

-- fx.hover(button, enter, leave): the click overlay TextButton receives the mouse (it covers the element)
function fx.hover(button, enter, leave)
	Library:Connect(button.MouseEnter, enter)
	Library:Connect(button.MouseLeave, leave)
end

-- fx.press(inst, button, depth): the element sinks (UIScale) while held
function fx.press(inst, button, depth)
	local sc = Instance.new("UIScale")
	sc.Name = "\0Press"
	sc.Parent = inst
	Library:Connect(button.MouseButton1Down, function() fx.tween(sc, { Scale = depth or 0.965 }, 0.08) end)
	local function up() fx.tween(sc, { Scale = 1 }, 0.35, Enum.EasingStyle.Back) end
	Library:Connect(button.MouseButton1Up, up)
	Library:Connect(button.MouseLeave, up)
	return sc
end

-- fx.ripple(inst, x, y): a soft accent disc grows from the click point and fades (clipped to the element's rectangle)
function fx.ripple(inst, x, y)
	if FLAT or not Library.Animations then return end
	local clip = inst:FindFirstChild("FxRipples")   -- (a "\0" name reads back empty, so this one is findable)
	if not clip then
		clip = Instance.new("Frame")
		clip.Name = "FxRipples"
		clip.BackgroundTransparency, clip.BorderSizePixel = 1, 0
		clip.Size = UDim2.fromScale(1, 1)
		clip.ClipsDescendants = true
		clip.ZIndex = 1
		clip.Parent = inst
	end
	local a, s = inst.AbsolutePosition, inst.AbsoluteSize
	local d = Instance.new("ImageLabel")
	d.BackgroundTransparency, d.BorderSizePixel = 1, 0
	d.Image = Build.IconAsset.fx_ripple or ""
	d.AnchorPoint = Vector2.new(0.5, 0.5)
	d.Position = UDim2.fromScale((x - a.X) / math.max(s.X, 1), (y - a.Y) / math.max(s.Y, 1))
	d.Size = UDim2.new(0, 0, 0, 0)
	d.ImageColor3 = Library.Theme.Accent
	d.ImageTransparency = 0.55
	local ar = Instance.new("UIAspectRatioConstraint")
	ar.DominantAxis = Enum.DominantAxis.Width
	ar.Parent = d
	d.Parent = clip
	fx.tween(d, { Size = UDim2.fromScale(2.4, 2.4), ImageTransparency = 1 }, 0.55)
	task.delay(0.6, function() pcall(function() d:Destroy() end) end)
end


-- ===== runtime/elements1.lua =====
-- Otterhook runtime part 2: Toggle, Button, Label (+ the add-on row for colorpicker / keybind). Uses Library, Build, field, click, listLayout from core.

-- right-aligned row for the add-ons (colour swatches, key pills) of a toggle / label row
local function addonRow(rowRoot, rightMargin)
	local row = Instance.new("Frame")
	row.Name = "\0"
	row.BackgroundTransparency = 1
	row.AnchorPoint = Vector2.new(1, 0.5)
	row.Position = UDim2.new(1, -rightMargin, 0.5, 0)
	row.Size = UDim2.new(0, 0, 0, 15)
	row.AutomaticSize = Enum.AutomaticSize.X
	row.ZIndex = 3
	row.Parent = rowRoot
	local l = Library.listLayout(row, 4, Enum.FillDirection.Horizontal)
	l.HorizontalAlignment = Enum.HorizontalAlignment.Right
	l.VerticalAlignment = Enum.VerticalAlignment.Center
	l.SortOrder = Enum.SortOrder.LayoutOrder
	return row
end
Library.addonRow = addonRow

local function tooltipFor(inst, text) end   -- tooltips come with the HUD phase

-- ---- Toggle ----
function Library:Toggle(Data)
	Data = Data or {}
	local section = self
	local flag = field(Data, "Flag", "flag") or Library:NextFlag()
	local fx = Library.fx
	local T = Build.Toggle(section.Items["Content"].Instance)
	T.Root.Size = UDim2.new(1, 0, 0, 18)
	T.label.Text = tostring(field(Data, "Name", "name") or "Toggle")
	Library.attachTooltip(T.Root, field(Data, "Tooltip", "tooltip"))
	Library.regSearch(section, T.Root, T.label.Text)
	T.label.Position, T.label.Size = UDim2.new(0, 19, 0, -1), UDim2.new(1, -19, 1, 0)   -- Otterhook: level with the box (was 1 px low)
	fx.shade(T.check, 0.3)
	local risky = field(Data, "Risky", "risky")
	local callback = field(Data, "Callback", "callback")
	local toggle = { Value = false, Flag = flag, Listeners = {}, Items = { Toggle = Library.Wrap(T.Root), Text = Library.Wrap(T.label) }, Section = section }
	toggle.Count = 0
	-- the checkbox: box = the 9 px square (Inline off, Accent on), check = the inner square, which pops in when it turns on
	T.check.AnchorPoint, T.check.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
	T.check.Size = UDim2.fromScale(1, 1)
	local checkScale = Instance.new("UIScale", T.check)
	local hovering = false
	local function paint(instant)
		local on = toggle.Value
		local t = instant and 0 or 0.14
		Library:ChangeItemTheme(T.box, { BackgroundColor3 = on and "Accent" or "Inline" })
		Library:ChangeItemTheme(T.check, { BackgroundColor3 = "Accent" })
		fx.tween(T.box, { BackgroundColor3 = on and Library.Theme.Accent or (hovering and Library.Theme["Element Hover"] or Library.Theme.Inline) }, t)
		fx.tween(T.check, { BackgroundTransparency = on and 0 or 1 }, t)
		checkScale.Scale = on and 0.4 or 1
		if on then fx.tween(checkScale, { Scale = 1 }, instant and 0 or 0.18, Enum.EasingStyle.Back) end
		if risky then T.label.TextColor3 = Library.Theme.Risky
		else
			-- Cadia: the name of a toggle that is on is written in the accent colour
			Library:ChangeItemTheme(T.label, { TextColor3 = on and "Accent" or "Dim Text" })
			fx.tween(T.label, { TextColor3 = on and Library.Theme.Accent or Library.Theme[hovering and "Text" or "Dim Text"] }, t)
		end
	end
	local function set(v, silent)
		toggle.Value = v and true or false
		Library.Flags[flag] = toggle.Value
		paint()
		for _, l in toggle.Listeners do l(toggle.Value) end
		if not silent and callback then Library:SafeCall(callback, toggle.Value) end
	end
	function toggle:Set(v) set(v) end
	function toggle:Get() return toggle.Value end
	function toggle:SetVisibility(b) T.Root.Visible = b end
	Library.SetFlags[flag] = function(v) set(v) end
	Library.Flags[flag] = false paint(true)
	local btn = click(T.Root, function() set(not toggle.Value) end)
	-- hover: the label brightens and an off box lightens
	fx.hover(btn, function()
		hovering = true
		if not risky and not toggle.Value then fx.tween(T.label, { TextColor3 = Library.Theme.Text }, 0.12) end
		if not toggle.Value then fx.tween(T.box, { BackgroundColor3 = Library.Theme["Element Hover"] }, 0.12) end
	end, function()
		hovering = false
		if not risky and not toggle.Value then fx.tween(T.label, { TextColor3 = Library.Theme["Dim Text"] }, 0.18) end
		if not toggle.Value then fx.tween(T.box, { BackgroundColor3 = Library.Theme.Inline }, 0.18) end
	end)
	if field(Data, "Default", "default") then set(true) end

	-- add-ons: :Colorpicker / :Keybind put their widgets in the row left of the box
	local row
	local function addons() if not row then row = addonRow(T.Root, 1) end return row end
	function toggle:Colorpicker(d) return Library.AddColorpicker(toggle, addons(), d) end
	function toggle:Keybind(d) return Library.AddKeybind(toggle, addons(), d, toggle) end
	return toggle
end

-- a button: hover lightens it, a press sinks it a little and flashes its edge in the accent colour
function Library.raiseButton(root, btn)
	local fx = Library.fx
	fx.bevel(root, 0.22)
	local sh = fx.shadow(root, { radius = 6, transparency = 0.5 })
	fx.press(root, btn)
	fx.hover(btn, function()
		fx.tween(root, { BackgroundColor3 = Library.Theme["Element Hover"] }, 0.15)
		fx.tween(sh, { ImageTransparency = 0.25 }, 0.15)
	end, function()
		fx.tween(root, { BackgroundColor3 = Library.Theme.Element }, 0.25)
		fx.tween(sh, { ImageTransparency = 0.5 }, 0.25)
	end)
	local st = root:FindFirstChildOfClass("UIStroke")
	if st then
		Library:Connect(btn.MouseButton1Down, function() st.Color = Library.Theme.Accent end)
		Library:Connect(btn.MouseButton1Up, function() fx.tween(st, { Color = Library.Theme.Outline }, 0.3) end)
		Library:Connect(btn.MouseLeave, function() fx.tween(st, { Color = Library.Theme.Outline }, 0.3) end)
	end
end

-- ---- Button (+ SubButton: a second button in the same row) ----
-- ---- confirmation for risky buttons ----
-- A button whose name says it overwrites, deletes, resets, leaves the server or spends money asks first, in a small box on top of
-- the button itself: the action, what it does, and confirm / cancel. Data.Confirm on a Button: true = always ask, a string = ask
-- with that message, false = never ask; nil = decided from the name by Library.RiskyButtons.
-- { pattern on the lowercased name, the message, red (destructive) confirm }
Library.RiskyButtons = {
	{ "^delete", "This deletes it for good.", true },
	{ "^unload", "The menu and every feature are switched off.", true },
	{ "^clear", "This cannot be undone.", true },
	{ "^reset .*stat", "The counters are set back to zero.", true },
	{ "^reset session", "The counters are set back to zero.", true },
	{ "^save config", "The saved file is overwritten with your current settings.", false },
	{ "^save ", "The saved one is overwritten.", false },
	{ "^load config", "Your current settings are replaced by the config.", false },
	{ "^load selected", "Your current settings are replaced.", false },
	{ "^import", "Your current settings are replaced by the imported ones.", false },
	{ "autoload", "This changes which config loads when the script starts.", false },
	{ "server hop", "You leave this server.", false },
	{ "^join", "You leave this server.", false },
	{ "^buy", "This spends in-game money.", false },
	{ "^steal", "Other players or the game may notice this.", false },
}
function Library.riskyMessage(name)
	local n = tostring(name or ""):lower()
	for _, r in Library.RiskyButtons do
		if n:find(r[1]) then return r[2], r[3] end
	end
	return nil
end

-- Library:Confirm({ Title, Text, Yes, No, Danger, Anchor, Root }, onYes): the ConfirmBox of the design sheet (Build.ConfirmBox:
-- double edge, accent line, warning icon, title, message, cancel / confirm) sits right above Anchor (the button) inside Root (the
-- window), as wide as the button, with its notch pointing at it; below the button when there is no room above; with no Anchor it is
-- centred in Root. Danger paints the line, the icon and confirm in Risky. Escape or a click anywhere else cancels. Returns { Close }.
local openConfirm
function Library:Confirm(Data, onYes)
	Data = Data or {}
	local fx = Library.fx
	if openConfirm then openConfirm(false) end
	local root = Data.Root or (Library.Windows[1] and Library.Windows[1]._W.Root) or Library.Holder.Instance
	local anchor = Data.Anchor
	local C = Build.ConfirmBox(root)
	local box = C.Root
	box.Name = "ConfirmBox"
	box.ZIndex = 3001
	C.cancel.AnchorPoint, C.cancel.Position, C.cancel.Size = Vector2.new(0, 1), UDim2.new(0, 10, 1, -8), UDim2.new(0.5, -13, 0, 20)
	C.confirm.AnchorPoint, C.confirm.Position, C.confirm.Size = Vector2.new(1, 1), UDim2.new(1, -10, 1, -8), UDim2.new(0.5, -13, 0, 20)
	local H0 = box.Size.Y.Offset
	local H = H0
	C.title.Text = tostring(Data.Title or "Are you sure?")
	C.title.FontFace = Library.FontBold
	C.title.TextTruncate = Enum.TextTruncate.AtEnd
	C.text.Text = tostring(Data.Text or "")
	C.text.TextWrapped, C.text.TextYAlignment = true, Enum.TextYAlignment.Top
	C.cancelText.Text = tostring(Data.No or "cancel")
	C.confirmText.Text = tostring(Data.Yes or "confirm")
	C.confirmText.FontFace = Library.FontBold
	if Data.Danger then
		Library.themed(C.line, "BackgroundColor3", "Risky")
		Library.themed(C.icon, "ImageColor3", "Risky")
		Library.themed(C.confirm, "BackgroundColor3", "Risky")
	end
	-- where: above the button (window coordinates, without the window's DPI scale), else below it, else centred
	local sc = root:FindFirstChildOfClass("UIScale")
	local k = (sc and sc.Scale > 0) and sc.Scale or 1
	local below = false
	-- the box is as tall as its message: the text's own height (wrapped at the box width) replaces the design's two lines
	local textH0 = C.text.Size.Y.Offset
	local function fitHeight(W)
		local tw = W + C.text.Size.X.Offset   -- the text spans the box minus its margins (Size.X = 1, -m)
		local okB, bounds = pcall(function()
			local p = Instance.new("GetTextBoundsParams")
			p.Text, p.Font, p.Size, p.Width = C.text.Text, C.text.FontFace, C.text.TextSize, tw
			return game:GetService("TextService"):GetTextBoundsAsync(p)
		end)
		local th = (okB and bounds) and math.ceil(bounds.Y) or textH0
		if C.text.Text == "" then th = 0 end
		C.text.Size = UDim2.new(C.text.Size.X.Scale, C.text.Size.X.Offset, 0, th)
		H = H0 - textH0 + th + 6   -- (+6: 10 px between the message and the buttons)
		box.Size = UDim2.fromOffset(W, H)
	end
	fx.shadow(box, { radius = 12, transparency = 0.15 })
	fx.bevel(C.confirm, 0.18, true)
	fx.bevel(C.cancel, 0.14, true)
	if anchor then
		local W = math.max(anchor.AbsoluteSize.X / k, 160)   -- the width of the button it sits on (only a very narrow button gets a wider box)
		fitHeight(W)
		local ra, a, s = root.AbsolutePosition, anchor.AbsolutePosition, anchor.AbsoluteSize
		local x, top = (a.X - ra.X) / k, (a.Y - ra.Y) / k
		local y = top - H - 6
		if y < 4 then y, below = top + s.Y / k + 6, true end
		box.Position = UDim2.fromOffset(x, y)
		-- the window can shift its children (padding): measure where the box landed and correct by the difference
		local wantX, wantY = ra.X + x * k, ra.Y + y * k
		local got = box.AbsolutePosition
		box.Position = UDim2.fromOffset(x + (wantX - got.X) / k, y + (wantY - got.Y) / k)
		-- the notch: a turned square of the box colour on the edge facing the button, over the button's middle (inside the box)
		local cx = math.clamp((a.X + s.X / 2 - box.AbsolutePosition.X) / k, 14, W - 14)
		C.caret.AnchorPoint, C.caret.Rotation = Vector2.new(0.5, 0.5), 45
		C.caret.Position = below and UDim2.new(0, cx, 0, 0) or UDim2.new(0, cx, 1, 0)
		C.caret.ZIndex = 3
	else
		fitHeight(box.Size.X.Offset)
		C.caret.Visible = false
		box.AnchorPoint, box.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
	end
	local done = false
	local conns = {}
	local function close(yes)
		if done then return end
		done = true
		openConfirm = nil
		for _, c in conns do pcall(function() c:Disconnect() end) end
		fx.tween(box, { Position = box.Position + UDim2.fromOffset(0, below and 4 or -4) }, 0.1)
		task.delay(0.1, function() pcall(function() box:Destroy() end) end)
		if yes and onYes then task.spawn(function() Library:SafeCall(onYes) end) end
	end
	openConfirm = close
	-- the two buttons: hover lightens them, a press flashes their edge in the accent colour
	local function wire(frame, label, yes)
		local base = frame.BackgroundColor3
		local edge = frame:FindFirstChildOfClass("UIStroke")
		local b = click(frame, function() close(yes) end)
		conns[#conns + 1] = b.MouseEnter:Connect(function()
			fx.tween(frame, { BackgroundColor3 = base:Lerp(Color3.new(1, 1, 1), 0.1) }, 0.1)
			if not yes then fx.tween(label, { TextColor3 = Library.Theme["Bright Text"] }, 0.1) end
		end)
		conns[#conns + 1] = b.MouseLeave:Connect(function()
			fx.tween(frame, { BackgroundColor3 = base }, 0.12)
			if not yes then fx.tween(label, { TextColor3 = Library.Theme.Text }, 0.12) end
		end)
		if edge then conns[#conns + 1] = b.MouseButton1Down:Connect(function() edge.Color = Library.Theme.Accent end) end
	end
	wire(C.confirm, C.confirmText, true)
	wire(C.cancel, C.cancelText, false)
	-- Escape, or a click outside the box (the click that opened it is over by now)
	local opened = os.clock()
	conns[#conns + 1] = UserInputService.InputBegan:Connect(function(i)
		if i.KeyCode == Enum.KeyCode.Escape then close(false) return end
		if (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) and os.clock() - opened > 0.05
			and not Library:IsMouseOverFrame(box) then
			close(false)
		end
	end)
	-- in: a short slide toward the button
	local pos = box.Position
	box.Position = pos + UDim2.fromOffset(0, below and 6 or -6)
	fx.tween(box, { Position = pos }, 0.15)
	return { Close = function() close(false) end }
end

-- what a button click does: straight away, or after the confirmation when the button is risky
function Library.guardedClick(section, anchor, name, confirm, fn)
	local msg, danger
	if confirm == nil then msg, danger = Library.riskyMessage(name)
	elseif confirm == true then msg = "This cannot be undone."
	elseif type(confirm) == "string" then msg = confirm end
	return function()
		if not fn then return end
		if not msg then Library:SafeCall(fn) return end
		local root = section and section.Window and section.Window._W and section.Window._W.Root
		Library:Confirm({ Title = tostring(name) .. "?", Text = msg, Danger = danger, Anchor = anchor, Root = root }, fn)
	end
end

-- Library.markRisky(root, label, name, explicitRisky, confirm): colours a destructive button (see above)
function Library.markRisky(root, label, name, explicitRisky, confirm)
	local msg, danger = Library.riskyMessage(name)
	local kind
	if explicitRisky then kind = "Risky"
	elseif confirm == nil and msg and danger then kind = "Risky" end
	if not kind then return end
	Library:ChangeItemTheme(label, { TextColor3 = kind })
	label.TextColor3 = Library.Theme[kind]
	local bar = Instance.new("Frame")
	bar.Name = "RiskBar"
	bar.BorderSizePixel = 0
	bar.Size = UDim2.new(0, 2, 1, 0)
	bar.ZIndex = root.ZIndex + 1
	bar.Parent = root
	Library:AddToTheme(bar, { BackgroundColor3 = kind })
end

function Library:Button(Data)
	Data = Data or {}
	local section = self
	local B = Build.Button(section.Items["Content"].Instance)
	B.Root.Size = UDim2.new(1, 0, 0, 22)
	B.label.Text = tostring(field(Data, "Name", "name") or "Button")
	Library.attachTooltip(B.Root, field(Data, "Tooltip", "tooltip"))
	Library.regSearch(section, B.Root, B.label.Text)
	local callback = field(Data, "Callback", "callback")
	Library.markRisky(B.Root, B.label, B.label.Text, field(Data, "Risky", "risky"), field(Data, "Confirm", "confirm"))
	local btn = click(B.Root, Library.guardedClick(section, B.Root, B.label.Text, field(Data, "Confirm", "confirm"), callback))
	Library.raiseButton(B.Root, btn)
	local obj = { Items = { Button = Library.Wrap(B.Root) }, Section = section }
	function obj:SetVisibility(b) B.Root.Visible = b end
	function obj:SubButton(d)
		d = d or {}
		-- two buttons share the row: this one is halved and a new one is placed beside it
		B.Root.Size = UDim2.new(0.5, -2, 0, 22)
		local list = Library.listLayout(B.Root.Parent, 4)
		local sub = Build.Button(section.Items["Content"].Instance)
		sub.Root.Size = UDim2.new(0.5, -2, 0, 22)
		sub.Root.Position = UDim2.new(0.5, 2, 0, 0)
		sub.label.Text = tostring(field(d, "Name", "name") or "Button")
		Library.markRisky(sub.Root, sub.label, sub.label.Text, field(d, "Risky", "risky"), field(d, "Confirm", "confirm"))
		local cb = field(d, "Callback", "callback")
		Library.raiseButton(sub.Root, click(sub.Root, Library.guardedClick(section, sub.Root, sub.label.Text, field(d, "Confirm", "confirm"), cb)))
		return { SetVisibility = function(_, b) sub.Root.Visible = b end }
	end
	return obj
end

-- ---- Buttons({ { Name, Callback, Confirm, Risky }, ... }): up to four buttons sharing one row ----
function Library:Buttons(List)
	local section = self
	local n = math.max(#List, 1)
	local row = Instance.new("Frame")
	row.Name = "\0"
	row.BackgroundTransparency, row.BorderSizePixel = 1, 0
	row.Size = UDim2.new(1, 0, 0, 26)
	row.Parent = section.Items["Content"].Instance
	local GAP = 6
	local out = {}
	for i, d in List do
		local B = Build.Button(row)
		-- n buttons and n - 1 gaps fill the row exactly
		B.Root.Size = UDim2.new(1 / n, -GAP * (n - 1) / n, 0, 22)
		B.Root.Position = UDim2.new((i - 1) / n, GAP * (i - 1) / n, 0, 2)
		B.label.Text = tostring(field(d, "Name", "name") or "Button")
		Library.regSearch(section, row, B.label.Text)
		Library.markRisky(B.Root, B.label, B.label.Text, field(d, "Risky", "risky"), field(d, "Confirm", "confirm"))
		local btn = click(B.Root, Library.guardedClick(section, B.Root, B.label.Text, field(d, "Confirm", "confirm"), field(d, "Callback", "callback")))
		Library.raiseButton(B.Root, btn)
		out[i] = { Items = { Button = Library.Wrap(B.Root) }, SetVisibility = function(_, b) B.Root.Visible = b end }
	end
	function out:SetVisibility(b) row.Visible = b end
	return out
end

-- ---- Keybind({ Name, Default, Mode, Callback, Menu }): a key on its own row. Menu = true makes it the key that opens / closes the menu ----
function Library:Keybind(Data)
	Data = Data or {}
	local section = self
	local lab = section:Label(tostring(field(Data, "Name", "name") or "Keybind"))
	local d = table.clone(Data)
	local kb
	if field(Data, "Menu", "menu") then
		local user = field(Data, "Callback", "callback")
		d.Passive = true
		d.Callback = function(...)
			if kb then
				local _, key = kb:Get()
				if key and key ~= "None" then Library.MenuKeybind = key end
			end
			if user then user(...) end
		end
		if d.Default == nil and d.default == nil then
			local a, b = tostring(Library.MenuKeybind):match("^Enum%.(%w+)%.(%w+)$")
			pcall(function() d.Default = Enum[a][b] end)
		end
	end
	kb = lab:Keybind(d)
	if field(Data, "Menu", "menu") then
		local _, key = kb:Get()
		if key and key ~= "None" then Library.MenuKeybind = key end
	end
	kb.Label = lab
	return kb
end

-- ---- Label(Text, Alignment) ----
function Library:Label(Text, Alignment)
	local section = self
	local L = Build.Label(section.Items["Content"].Instance)
	L.Root.Size = UDim2.new(1, 0, 0, 18)
	L.Root.AutomaticSize = Enum.AutomaticSize.Y
	L.text.Position = UDim2.new(0, 0, 0, 1)
	L.text.Size = UDim2.new(1, 0, 0, 0)
	L.text.AutomaticSize = Enum.AutomaticSize.Y
	L.text.TextWrapped = true
	L.text.RichText = true
	L.text.Text = tostring(Text or "Label")
	Library.regSearch(section, L.Root, L.text.Text)
	local a = tostring(Alignment or "Left"):lower()
	L.text.TextXAlignment = a == "center" and Enum.TextXAlignment.Center or a == "right" and Enum.TextXAlignment.Right or Enum.TextXAlignment.Left
	local label = { Items = { Label = Library.Wrap(L.Root), Text = Library.Wrap(L.text) }, Section = section }
	function label:SetVisibility(b) L.Root.Visible = b end
	function label:SetText(t) L.text.Text = tostring(t) end
	local row
	local function addons() if not row then row = addonRow(L.Root, 0) L.text.Size = UDim2.new(1, -80, 0, 0) end return row end
	function label:Colorpicker(d) return Library.AddColorpicker(label, addons(), d) end
	function label:Keybind(d) return Library.AddKeybind(label, addons(), d, nil) end
	return label
end


-- ===== runtime/elements2.lua =====
-- Otterhook runtime part 3: Slider, Dropdown (single / multi), Listbox, Textbox. Behaviour = uilibnewBlxStrike.lua (flags, Set/Get, callbacks).

local function setText(inst, t) inst.Text = t end

-- a field (flat in Aurora): returns the accent glow for focus / open, which the flat style does not have (nil)
function Library.insetField(f)
	return Library.fx.glow(f, 8, 0.6)
end

-- ---- Slider ----
function Library:Slider(Data)
	Data = Data or {}
	local section = self
	local flag = field(Data, "Flag", "flag") or Library:NextFlag()
	local min, max = field(Data, "Min", "min") or 0, field(Data, "Max", "max") or 100
	local step = field(Data, "Decimals", "decimals") or 1
	local suffix = field(Data, "Suffix", "suffix") or ""
	local callback = field(Data, "Callback", "callback")
	local fx = Library.fx
	local T = Build.Slider(section.Items["Content"].Instance)
	T.Root.Size = UDim2.new(1, 0, 0, 33)
	T.label.Text = tostring(field(Data, "Name", "name") or "Slider")
	Library.attachTooltip(T.Root, field(Data, "Tooltip", "tooltip"))
	Library.regSearch(section, T.Root, T.label.Text)
	-- Range = true: two ends on one bar, the value is { low, high }
	local range = field(Data, "Range", "range") and true or false
	local decimals = 0
	do local f = tostring(step):match("%.(%d+)") decimals = f and #f or 0 end
	local function fmt(v) return string.format("%." .. decimals .. "f", v) end
	local slider = { Value = range and { min, max } or min, Flag = flag, Items = { Slider = Library.Wrap(T.Root) }, Section = section, Range = range }
	-- the Cadia bar: the fill is lit from above, the value is written in the middle of the bar with a dark outline so it reads on both
	local trackStroke = T.track:FindFirstChildOfClass("UIStroke")
	T.fill.Position, T.fill.Size = UDim2.new(), UDim2.new(0, 0, 1, 0)
	T.knob.Visible = false
	T.value.Position, T.value.Size, T.value.ZIndex = UDim2.new(0, 0, 0, -1), UDim2.fromScale(1, 1), 3
	T.value.FontFace = Library.FontBold
	local outline = Instance.new("UIStroke")
	outline.Thickness, outline.Color, outline.Transparency = 1, Color3.new(0, 0, 0), 0.45
	outline.Parent = T.value
	fx.shade(T.fill, 0.3)
	fx.shade(T.track, 0.25)
	local function snap(v)
		v = math.clamp(math.floor(v / step + 0.5) * step, min, max)
		return tonumber(fmt(v)) or v
	end
	local function paint()
		local span = math.max(max - min, 1e-9)
		if range then
			local a, b = (slider.Value[1] - min) / span, (slider.Value[2] - min) / span
			Library:TweenTo(T.fill, { Position = UDim2.new(a, 0, 0, 0), Size = UDim2.new(b - a, 0, 1, 0) }, 0.1)
			T.value.Text = fmt(slider.Value[1]) .. " - " .. fmt(slider.Value[2]) .. suffix
		else
			Library:TweenTo(T.fill, { Size = UDim2.new((slider.Value - min) / span, 0, 1, 0) }, 0.1)
			T.value.Text = fmt(slider.Value) .. suffix
		end
	end
	local function set(v)
		if range then
			if type(v) ~= "table" then return end
			local a, b = tonumber(v[1]), tonumber(v[2])
			if not (a and b) then return end
			a, b = snap(a), snap(b)
			if a > b then a, b = b, a end
			slider.Value = { a, b }
		else
			v = tonumber(v)
			if not v then return end
			slider.Value = snap(v)
		end
		Library.Flags[flag] = slider.Value
		paint()
		if callback then Library:SafeCall(callback, slider.Value) end
	end
	function slider:Set(v) set(v) end
	function slider:Get() return slider.Value end
	function slider:SetVisibility(b) T.Root.Visible = b end
	local dragging, pick = false, nil
	local function fromX(x)
		local w = T.track.AbsoluteSize.X
		local v = min + (max - min) * math.clamp((x - T.track.AbsolutePosition.X) / math.max(w, 1), 0, 1)
		if range then
			-- the end nearer to the click is the one that is dragged
			if not pick then pick = math.abs(v - slider.Value[1]) <= math.abs(v - slider.Value[2]) and 1 or 2 end
			if pick == 1 then set({ math.min(v, slider.Value[2]), slider.Value[2] }) else set({ slider.Value[1], math.max(v, slider.Value[1]) }) end
		else
			set(v)
		end
	end
	local hit = Instance.new("TextButton")
	hit.BackgroundTransparency, hit.Text, hit.AutoButtonColor = 1, "", false
	hit.Size, hit.ZIndex = UDim2.fromScale(1, 1), 5
	hit.Parent = T.track
	local hovering = false
	local function lit()
		local on = hovering or dragging
		if trackStroke then fx.tween(trackStroke, { Color = on and Library.Theme.Accent or Library.Theme.Outline }, 0.15) end
	end
	fx.hover(hit, function() hovering = true lit() end, function() hovering = false lit() end)
	-- (on the library's shared move listener while dragged: no per-slider global input connections)
	Library:Connect(hit.InputBegan, function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
			dragging, pick = true, nil
			fromX(i.Position.X) lit()
			Library.beginDrag(function(m) fromX(m.Position.X) end, function() dragging, pick = false, nil lit() end)
		end
	end)
	local default = field(Data, "Default", "default")
	if default == nil then default = range and { min, max } or min end
	set(default)
	Library.SetFlags[flag] = set
	return slider
end

-- ---- shared by Dropdown and Listbox: the option store (single / multi) ----
local function optionStore(opts)
	-- opts: multi, makeRow(name) -> { row, text }, onValue(value) (text), callback, flag, container
	local st = { Value = opts.multi and {} or nil, Options = {}, multi = opts.multi }
	local fx = Library.fx
	local function paintRow(o)
		local sel = o.selected
		Library:ChangeItemTheme(o.text, { TextColor3 = sel and "Accent" or (o.idle or "Dim Text") })
		Library:ChangeItemTheme(o.row, { BackgroundColor3 = "Element" })
		o.text.FontFace = sel and Library.FontBold or Library.Font
		fx.tween(o.text, { TextColor3 = sel and Library.Theme.Accent or Library.Theme[o.idle or "Dim Text"] }, 0.15)
		fx.tween(o.row, { BackgroundTransparency = 1 }, 0.2)
			end
	function st.add(name)
		local r = opts.makeRow(name)
		local o = { row = r.row, text = r.text, bar = r.bar, selected = false, idle = r.idle }
		st.Options[name] = o
		paintRow(o)
		Library:Connect(r.button.MouseButton1Click, function() st.click(name) end)
		fx.hover(r.button, function() if not o.selected then fx.tween(o.row, { BackgroundTransparency = 0.4 }, 0.12) fx.tween(o.text, { TextColor3 = Library.Theme["Bright Text"] }, 0.12) end end,
			function() if not o.selected then fx.tween(o.row, { BackgroundTransparency = 1 }, 0.18) fx.tween(o.text, { TextColor3 = Library.Theme[o.idle or "Dim Text"] }, 0.18) end end)
		return o
	end
	function st.remove(name)
		local o = st.Options[name]
		if o then pcall(function() o.row:Destroy() end) st.Options[name] = nil end
	end
	local function fire()
		Library.Flags[opts.flag] = st.Value
		if opts.onValue then opts.onValue(st.Value) end
		if opts.callback then Library:SafeCall(opts.callback, st.Value) end
	end
	function st.click(name)
		local o = st.Options[name]
		if not o then return end
		if st.multi then
			local at = table.find(st.Value, name)
			if at then table.remove(st.Value, at) o.selected = false else table.insert(st.Value, name) o.selected = true end
		elseif o.selected then
			o.selected, st.Value = false, nil
		else
			for _, other in st.Options do other.selected = false paintRow(other) end
			o.selected, st.Value = true, name
		end
		paintRow(o)
		fire()
	end
	function st.set(v)
		if st.multi then
			if type(v) ~= "table" then return end
			st.Value = v
			for _, o in st.Options do o.selected = false end
			for _, name in v do
				local o = st.Options[name]
				if not o then break end
				o.selected = true
			end
			for _, o in st.Options do paintRow(o) end
			Library.Flags[opts.flag] = st.Value
			if opts.onValue then opts.onValue(st.Value) end
			if opts.callback then Library:SafeCall(opts.callback, st.Value) end
		else
			local o = st.Options[v]
			if not o then return end
			for _, other in st.Options do other.selected = false paintRow(other) end
			o.selected = true
			paintRow(o)
			st.Value = v
			Library.Flags[opts.flag] = v
			if opts.onValue then opts.onValue(v) end
			if opts.callback then Library:SafeCall(opts.callback, v) end
		end
	end
	function st.refresh(list)
		for name in st.Options do st.remove(name) end
		for _, name in list do st.add(name) end
		-- the kept selection is shown again on the new rows (flags and callbacks are not touched)
		local keep = st.multi and st.Value or (st.Value and { st.Value } or {})
		for _, name in keep do local o = st.Options[name] if o then o.selected = true paintRow(o) end end
	end
	return st
end

local function optionRow(parentScroll, centred)
	return function(name)
		local O = Build.Option(parentScroll)
		O.Root.Size = UDim2.new(1, 0, 0, 20)
		O.Root.BackgroundTransparency = 1
		O.text.Text = tostring(name)
		O.text.Position, O.text.Size = UDim2.new(0, 6, 0, 0), UDim2.new(1, -12, 1, 0)
		O.text.TextTruncate = Enum.TextTruncate.AtEnd
		if centred then O.text.TextXAlignment = Enum.TextXAlignment.Center end
		local b = Instance.new("TextButton")
		b.BackgroundTransparency, b.Text, b.Size, b.ZIndex = 1, "", UDim2.fromScale(1, 1), O.Root.ZIndex + 2
		b.Parent = O.Root
		-- a listbox shows its rows in the normal text colour, a dropdown list dims the ones that are not chosen
		return { row = O.Root, text = O.text, button = b, idle = centred and "Text" or "Dim Text" }
	end
end

-- ---- Dropdown ----
function Library:Dropdown(Data)
	Data = Data or {}
	local section = self
	local flag = field(Data, "Flag", "flag") or Library:NextFlag()
	local multi = field(Data, "Multi", "multi") and true or false
	local maxSize = field(Data, "MaxSize", "maxsize") or 140
	local callback = field(Data, "Callback", "callback")
	local fx = Library.fx
	local T = Build.Dropdown(section.Items["Content"].Instance)
	T.Root.Size = UDim2.new(1, 0, 0, 42)
	T.label.Text = tostring(field(Data, "Name", "name") or "Dropdown")
	Library.attachTooltip(T.Root, field(Data, "Tooltip", "tooltip"))
	Library.regSearch(section, T.Root, T.label.Text)
	T.value.Text = "None"
	T.value.TextTruncate = Enum.TextTruncate.AtEnd
	T.value.Position, T.value.Size = UDim2.new(0, 7, 0, 0), UDim2.new(1, -28, 1, -1)
	fx.shade(T.field, 0.2)
	local winRoot = Library.popupRoot(section)
	local P = Build.Panel(winRoot)
	P.Root.Visible = false
	P.Root.ZIndex = 1000
	P.Root.Size = UDim2.new(0, 212, 0, 60)
	fx.shadow(P.Root, { radius = 10, transparency = 0.15 })
	fx.bevel(P.Root, 0.08)
	local fieldGlow = Library.insetField(T.field)
	local scroll = Instance.new("ScrollingFrame")
	scroll.BackgroundTransparency, scroll.BorderSizePixel = 1, 0
	scroll.ScrollBarThickness, scroll.ScrollBarImageColor3 = 2, Library.Theme.Inline
	scroll.CanvasSize, scroll.AutomaticCanvasSize = UDim2.new(), Enum.AutomaticSize.Y
	scroll.Size, scroll.ZIndex = UDim2.fromScale(1, 1), 1001
	scroll.Parent = P.rows
	Library.listLayout(scroll, 0)
	-- the search field on top of the list (Search = false leaves it out): typing hides the rows that do not match
	local searchable = field(Data, "Search", "search")
	if searchable == nil then searchable = true end
	local SEARCH_H = searchable and 25 or 0
	local sbox, applySearch
	if searchable then
		local sf = Instance.new("Frame")
		sf.Name = "\0"
		sf.BorderSizePixel = 0
		sf.Position, sf.Size, sf.ZIndex = UDim2.new(0, 2, 0, 2), UDim2.new(1, -4, 0, 20), 1001
		sf.Parent = P.rows
		Library:AddToTheme(sf, { BackgroundColor3 = "Element" })
		local ss = Instance.new("UIStroke", sf)
		ss.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		Library:AddToTheme(ss, { Color = "Outline" })
		sbox = Instance.new("TextBox")
		sbox.Name = "\0"
		sbox.BackgroundTransparency, sbox.BorderSizePixel = 1, 0
		sbox.Position, sbox.Size, sbox.ZIndex = UDim2.new(0, 6, 0, 0), UDim2.new(1, -12, 1, 0), 1002
		sbox.FontFace, sbox.TextSize, sbox.TextXAlignment = Library.Font, 13, Enum.TextXAlignment.Left
		sbox.PlaceholderText, sbox.Text, sbox.ClearTextOnFocus = "Search...", "", false
		Library:AddToTheme(sbox, { TextColor3 = "Text", PlaceholderColor3 = "Dim Text" })
		sbox.Parent = sf
		scroll.Position, scroll.Size = UDim2.new(0, 0, 0, SEARCH_H), UDim2.new(1, 0, 1, -SEARCH_H)
	end
	local dd = { Flag = flag, Items = { Dropdown = Library.Wrap(T.Root) }, Section = section }
	local store = optionStore({
		multi = multi, flag = flag, callback = callback, makeRow = optionRow(scroll),
		onValue = function(v)
			if multi then T.value.Text = #v > 0 and table.concat(v, ", ") or "None" else T.value.Text = v and tostring(v) or "None" end
		end,
	})
	if sbox then
		applySearch = function()
			local q = string.lower(sbox.Text)
			for name, o in store.Options do o.row.Visible = q == "" or string.find(string.lower(tostring(name)), q, 1, true) ~= nil end
		end
		Library:Connect(sbox:GetPropertyChangedSignal("Text"), applySearch)
	end
	local open, debounce = false, false
	-- the list unrolls downwards from the field (height tween), and rolls back up before it hides
	local function target()
		local s = T.field.AbsoluteSize
		local count = 0 for _ in store.Options do count += 1 end
		return s.X, math.min(count * 20 + 4, maxSize + 4) + SEARCH_H
	end
	local openToken = 0
	local unwatch
	local setOpen
	setOpen = function(b)
		if unwatch then unwatch() unwatch = nil end
		open = b
		openToken += 1
		local my = openToken
		fx.tween(T.chevron, { Rotation = b and 180 or 0 }, 0.18)
		fx.glowTo(fieldGlow, b)
		local w, h = target()
		local sc = winRoot:FindFirstChildOfClass("UIScale")
		w = w / (sc and sc.Scale or 1)   -- AbsoluteSize is scaled by the window's UIScale, Size is not
		if b then
			Library.popupAt(P.Root, winRoot, T.field, 2)
			local s = sc and sc.Scale or 1
			local x, below = P.Root.Position.X.Offset / s, P.Root.Position.Y.Offset / s
			-- no room below the field inside the window: the list opens upwards, growing from just above the field
			local fieldH = T.field.AbsoluteSize.Y / s
			if below + h > winRoot.AbsoluteSize.Y / s - 8 then
				P.Root.AnchorPoint = Vector2.new(0, 1)
				P.Root.Position = UDim2.new(0, x, 0, below - fieldH - 8)
			else
				P.Root.AnchorPoint = Vector2.new(0, 0)
				P.Root.Position = UDim2.new(0, x, 0, below)
			end
			if not P.Root.Visible then P.Root.Size = UDim2.new(0, w, 0, 0) end
			P.Root.Visible = true
			fx.tween(P.Root, { Size = UDim2.new(0, w, 0, h) }, 0.18)
			unwatch = Library.watchAnchor(T.field, winRoot, function() unwatch = nil setOpen(false) end)   -- the page scrolled: close
			debounce = true
			task.delay(0.1, function() debounce = false end)
		else
			if sbox then sbox:ReleaseFocus() end
			fx.tween(P.Root, { Size = UDim2.new(0, w, 0, 0) }, 0.12).Completed:Connect(function()
				if openToken == my then P.Root.Visible = false if sbox then sbox.Text = "" end end
			end)
		end
	end
	click(T.field, function() setOpen(not open) end)
	Library:Connect(UserInputService.InputBegan, function(i)
		if open and not debounce and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) and not Library:IsMouseOverFrame(P.Root) and not Library:IsMouseOverFrame(T.field) then setOpen(false) end
	end)
	for _, name in field(Data, "Items", "items") or {} do store.add(name) end
	function dd:Set(v) store.set(v) end
	function dd:Get() return store.Value end
	function dd:Add(name) store.add(name) end
	function dd:Remove(name) store.remove(name) end
	function dd:Refresh(list) store.refresh(list) end
	function dd:SetVisibility(b) T.Root.Visible = b if not b then setOpen(false) end end
	local default = field(Data, "Default", "default")
	if default then store.set(default) end
	Library.SetFlags[flag] = function(v) store.set(v) end
	Library.OnUnload = Library.OnUnload or {}
	table.insert(Library.OnUnload, function() pcall(function() P.Root:Destroy() end) end)
	return dd
end

-- ---- Listbox ----
function Library:Listbox(Data)
	Data = Data or {}
	local section = self
	local flag = field(Data, "Flag", "flag") or Library:NextFlag()
	local multi = field(Data, "Multi", "multi") and true or false
	local items0 = field(Data, "Items", "items") or {}
	local size = field(Data, "Size", "size") or math.clamp(#items0 * 20 + 6, 46, 175)
	local callback = field(Data, "Callback", "callback")
	local T = Build.Listbox(section.Items["Content"].Instance)
	local lname = field(Data, "Name", "name")
	local top = (lname ~= nil and lname ~= "") and 17 or 2
	T.Root.Size = UDim2.new(1, 0, 0, size + top + 3)
	T.field.Position, T.field.Size = UDim2.new(0, 1, 0, top), UDim2.new(1, -2, 0, size)
	T.label.Visible = top > 2
	Library.insetField(T.field)
	T.label.Text = tostring(lname or "Listbox")
	Library.attachTooltip(T.Root, field(Data, "Tooltip", "tooltip"))
	Library.regSearch(section, T.Root, T.label.Text)
	local scroll = Instance.new("ScrollingFrame")
	scroll.BackgroundTransparency, scroll.BorderSizePixel = 1, 0
	scroll.ScrollBarThickness, scroll.ScrollBarImageColor3 = 2, Library.Theme.Inline
	scroll.CanvasSize, scroll.AutomaticCanvasSize = UDim2.new(), Enum.AutomaticSize.Y
	scroll.Size = UDim2.fromScale(1, 1)
	scroll.Parent = T.rows
	Library.listLayout(scroll, 0)
	local lb = { Flag = flag, Items = { Listbox = Library.Wrap(T.Root) }, Section = section }
	local store = optionStore({ multi = multi, flag = flag, callback = callback, makeRow = optionRow(scroll, true) })
	for _, name in field(Data, "Items", "items") or {} do store.add(name) end
	local ldef = field(Data, "Default", "default")
	if ldef ~= nil then store.set(ldef) end
	function lb:Set(v) store.set(v) end
	function lb:Get() return store.Value end
	function lb:Add(name) store.add(name) end
	function lb:Remove(name) store.remove(name) end
	function lb:Refresh(list) store.refresh(list) end
	function lb:SetVisibility(b) T.Root.Visible = b end
	Library.SetFlags[flag] = function(v) store.set(v) end
	return lb
end

-- ---- Textbox ----
function Library:Textbox(Data)
	Data = Data or {}
	local section = self
	local flag = field(Data, "Flag", "flag") or Library:NextFlag()
	local callback = field(Data, "Callback", "callback")
	local T = Build.Textbox(section.Items["Content"].Instance)
	T.Root.Size = UDim2.new(1, 0, 0, 42)
	local glow = Library.insetField(T.field)
	local fieldStroke = T.field:FindFirstChildOfClass("UIStroke")
	T.label.Text = tostring(field(Data, "Name", "name") or "Textbox")
	Library.attachTooltip(T.Root, field(Data, "Tooltip", "tooltip"))
	Library.regSearch(section, T.Root, T.label.Text)
	T.input.Visible = false
	local box = Instance.new("TextBox")
	box.BackgroundTransparency, box.BorderSizePixel = 1, 0
	box.Size, box.Position = UDim2.new(1, -14, 1, 0), UDim2.new(0, 7, 0, 0)
	box.FontFace, box.TextSize = Library.Font, 13
	box.TextColor3, box.PlaceholderColor3 = Library.Theme.Text, Library.Theme["Dim Text"]
	box.PlaceholderText = tostring(field(Data, "Placeholder", "placeholder") or "...")
	box.TextXAlignment, box.ClearTextOnFocus, box.Text = Enum.TextXAlignment.Left, false, ""
	box.TextTruncate = Enum.TextTruncate.AtEnd
	box.Parent = T.field
	local tb = { Value = "", Flag = flag, Items = { Textbox = Library.Wrap(T.Root) }, Section = section }
	local function set(v)
		tb.Value = tostring(v)
		Library.Flags[flag] = tb.Value
		box.Text = tb.Value
		box.TextColor3 = Library.Theme.Text
		if callback then Library:SafeCall(callback, tb.Value) end
	end
	Library:Connect(box.Focused, function()
		box.TextColor3 = Library.Theme.Accent
		Library.fx.glowTo(glow, true)
		if fieldStroke then Library.themed(fieldStroke, "Color", "Accent") end
	end)
	Library:Connect(box.FocusLost, function()
		Library.fx.glowTo(glow, false)
		if fieldStroke then Library.themed(fieldStroke, "Color", "Outline") end
		set(box.Text)
	end)
	function tb:Set(v) set(v) end
	function tb:Get() return tb.Value end
	function tb:SetVisibility(b) T.Root.Visible = b end
	set(field(Data, "Default", "default") or "")
	Library.SetFlags[flag] = set
	return tb
end


-- ===== runtime/elements3.lua =====
-- runtime part 4: Colorpicker and Keybind (the add-ons of a Toggle / Label). Behaviour = uilibnewBlxStrike.lua.

local Keys = {
	[Enum.KeyCode.LeftShift] = "Shift", [Enum.KeyCode.RightShift] = "RShift", [Enum.KeyCode.LeftControl] = "Ctrl", [Enum.KeyCode.RightControl] = "RCtrl",
	[Enum.KeyCode.Delete] = "Del", [Enum.KeyCode.Insert] = "Ins", [Enum.KeyCode.Backspace] = "Bksp", [Enum.KeyCode.Escape] = "Esc", [Enum.KeyCode.CapsLock] = "Caps",
	[Enum.KeyCode.LeftAlt] = "Alt", [Enum.KeyCode.RightAlt] = "RAlt", [Enum.KeyCode.Return] = "Enter", [Enum.KeyCode.Space] = "Space",
	[Enum.UserInputType.MouseButton1] = "M1", [Enum.UserInputType.MouseButton2] = "M2", [Enum.UserInputType.MouseButton3] = "M3",
}
local function keyText(keyString)
	if not keyString or keyString == "None" or keyString == "[-]" then return "-" end
	for enum, short in Keys do if tostring(enum) == keyString then return short end end
	return (tostring(keyString):gsub("Enum%.KeyCode%.", ""):gsub("Enum%.UserInputType%.", ""))
end

-- ---- Colorpicker ----
local HUE_SEQ = ColorSequence.new({
	ColorSequenceKeypoint.new(0, Color3.fromHSV(0, 1, 1)), ColorSequenceKeypoint.new(1 / 6, Color3.fromHSV(1 / 6, 1, 1)),
	ColorSequenceKeypoint.new(2 / 6, Color3.fromHSV(2 / 6, 1, 1)), ColorSequenceKeypoint.new(3 / 6, Color3.fromHSV(3 / 6, 1, 1)),
	ColorSequenceKeypoint.new(4 / 6, Color3.fromHSV(4 / 6, 1, 1)), ColorSequenceKeypoint.new(5 / 6, Color3.fromHSV(5 / 6, 1, 1)),
	ColorSequenceKeypoint.new(1, Color3.fromHSV(1, 1, 1)),
})
local openPicker   -- only one popup open at a time

function Library.AddColorpicker(owner, row, Data)
	Data = Data or {}
	local flag = field(Data, "Flag", "flag") or Library:NextFlag()
	local callback = field(Data, "Callback", "callback")
	local S = Build.Swatch(row)
	S.Root.LayoutOrder = 2
	S.Root.Size = UDim2.new(0, 26, 0, 11)
	Library.fx.shade(S.color, 0.25)
	-- the swatch's own background shows through a transparent colour: a neutral tone, not the accent
	Library:ChangeItemTheme(S.Root, { BackgroundColor3 = "Inline" })
	S.Root.BackgroundColor3 = Library.Theme.Inline
	Library.fx.shadow(S.Root, { radius = 5, transparency = 0.45 })
	local winRoot = Library.popupRoot(owner.Section)
	local P = Build.ColorPopup(winRoot)
	P.Root.Visible, P.Root.ZIndex = false, 1000
	Library.fx.shadow(P.Root, { radius = 12, transparency = 0.1 })
	Library.fx.bevel(P.Root, 0.08)
	local popScale = Instance.new("UIScale", P.Root)
	local cp = { Flag = flag, Color = Color3.new(1, 1, 1), Alpha = 0, Hue = 0, Sat = 0, Val = 1, Items = {} }
	cp.Items.Swatch = Library.Wrap(S.Root)
	Library.Flags[flag] = {}

	-- the square: hue colour + white-to-clear (left to right) + clear-to-black (top to bottom)
	P.sv.BackgroundColor3 = Color3.fromHSV(0, 1, 1)
	local w = Instance.new("Frame")
	w.BackgroundColor3, w.BorderSizePixel, w.Size, w.ZIndex = Color3.new(1, 1, 1), 0, UDim2.fromScale(1, 1), P.sv.ZIndex + 1
	w.Parent = P.sv
	-- (square: imgui)
	local g1 = Instance.new("UIGradient", w) g1.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) })
	local b = Instance.new("Frame")
	b.BackgroundColor3, b.BorderSizePixel, b.Size, b.ZIndex = Color3.new(0, 0, 0), 0, UDim2.fromScale(1, 1), P.sv.ZIndex + 2
	b.Parent = P.sv
	-- (square: imgui)
	local g2 = Instance.new("UIGradient", b) g2.Rotation = 90 g2.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) })
	P.svCursor.ZIndex = 10
	P.svCursor.Parent = P.sv
	local hg = Instance.new("UIGradient", P.hue) hg.Color = HUE_SEQ hg.Rotation = 90   -- Cadia: the hue bar stands beside the square
	P.hue.BackgroundColor3 = Color3.new(1, 1, 1)
	P.hueCursor.ZIndex = 5
	P.alphaCursor.ZIndex = 5
	local ag = Instance.new("UIGradient", P.alpha) Library.themed(P.alpha, "BackgroundColor3", Color3.new(1, 1, 1))
	local hexBox = Instance.new("TextBox")
	hexBox.BackgroundTransparency, hexBox.BorderSizePixel, hexBox.Size, hexBox.Position = 1, 0, UDim2.new(1, -16, 1, 0), UDim2.new(0, 8, 0, 0)
	hexBox.FontFace, hexBox.TextSize, hexBox.TextColor3, hexBox.TextXAlignment, hexBox.ClearTextOnFocus = Library.Font, 12, Library.Theme.Text, Enum.TextXAlignment.Left, false
	hexBox.Position, hexBox.Size, hexBox.TextSize, hexBox.ZIndex = UDim2.new(0, 6, 0, 0), UDim2.new(1, -12, 1, 0), 13, 3
	hexBox.Parent = P.hexField
	P.hex.Visible = false
	-- the "r, g, b, a" field (a = opacity, 0 - 1)
	local rgbBox = hexBox:Clone()
	rgbBox.Parent = P.rgbField
	P.rgb.Visible = false
	for _, f in { P.rgbField, P.hexField } do Library.fx.shade(f, 0.2) end
	if P.inner then P.inner.ZIndex = 0 Library.fx.shade(P.inner, 0.2) end
	local function byte(x) return math.floor(x * 255 + 0.5) end

	local function update(silent)
		cp.Color = Color3.fromHSV(cp.Hue, cp.Sat, cp.Val)
		-- the design binds these to the Accent theme colour; Library.themed with a Color3 drops that binding, otherwise the next theme
		-- change (every config load applies the theme) would paint every swatch in the accent colour
		Library.themed(S.color, "BackgroundColor3", cp.Color)
		S.color.BackgroundTransparency = cp.Alpha * 0.8
		P.sv.BackgroundColor3 = Color3.fromHSV(cp.Hue, 1, 1)
		P.svCursor.Position = UDim2.new(cp.Sat, -3, 1 - cp.Val, -3)
		P.hueCursor.Position = UDim2.new(0, -1, cp.Hue, -1)
		-- cp.Alpha is a transparency (0 = solid), like the other libs; the bar and the fields show opacity, so solid is on the right
		P.alphaCursor.Position = UDim2.new(1 - cp.Alpha, -1, 0, -1)
		ag.Color = ColorSequence.new(Library.Theme.Inline, cp.Color)
		if not hexBox:IsFocused() then hexBox.Text = "#" .. cp.Color:ToHex():upper() .. string.format("%02X", byte(1 - cp.Alpha)) end
		if not rgbBox:IsFocused() then
			rgbBox.Text = string.format("%d, %d, %d, %s", byte(cp.Color.R), byte(cp.Color.G), byte(cp.Color.B), tostring(math.floor((1 - cp.Alpha) * 100 + 0.5) / 100))
		end
		Library.Flags[flag] = { HexValue = cp.Color:ToHex(), Color = cp.Color, Alpha = cp.Alpha, Flag = flag }
		if not silent and callback then Library:SafeCall(callback, cp.Color, cp.Alpha) end
	end
	local function set(color, alpha)
		if type(color) == "string" then local ok, c = pcall(Color3.fromHex, color) if not ok then return end color = c end
		if typeof(color) ~= "Color3" then return end
		cp.Hue, cp.Sat, cp.Val = color:ToHSV()
		cp.Alpha = math.clamp(tonumber(alpha) or 0, 0, 1)
		update()
	end
	function cp:Set(c, a) set(c, a) end
	function cp:Get() return cp.Color, cp.Alpha end
	function cp:SetVisibility(v) S.Root.Visible = v end

	-- popup
	local open, debounce = false, false
	local unwatch
	local setOpen
	setOpen = function(v)
		if v and openPicker and openPicker ~= setOpen then openPicker(false) end
		if unwatch then unwatch() unwatch = nil end
		open = v
		P.Root.Visible = v
		openPicker = v and setOpen or nil
		if v then
			Library.popupAt(P.Root, winRoot, S.Root, 6)
			unwatch = Library.watchAnchor(S.Root, winRoot, function() unwatch = nil setOpen(false) end)   -- the page scrolled: close
			local x = math.min(P.Root.Position.X.Offset, winRoot.AbsoluteSize.X - 206)
			if Library.fitPopup then Library.fitPopup(P.Root, winRoot, S.Root, 198, 258) end
			P.Root.Position = UDim2.new(0, x, 0, math.min(P.Root.Position.Y.Offset, winRoot.AbsoluteSize.Y - 266))
			-- pops in from slightly smaller
			popScale.Scale = 0.9
			Library.fx.tween(popScale, { Scale = 1 }, 0.3, Enum.EasingStyle.Back)
			debounce = true
			task.delay(0.1, function() debounce = false end)
		end
	end
	Library:Connect(UserInputService.InputBegan, function(i)
		if open and not debounce and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) and not Library:IsMouseOverFrame(P.Root) and not Library:IsMouseOverFrame(S.Root) then setOpen(false) end
	end)
	local drag
	local apply
	local function bind(frame, kind)
		Library:Connect(frame.InputBegan, function(i)
			if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
				drag = kind
				apply(i.Position)
				Library.beginDrag(function(m) apply(m.Position) end, function() drag = nil end)
			end
		end)
	end
	bind(P.sv, "sv") bind(P.hue, "hue") bind(P.alpha, "alpha")
	apply = function(pos)
		if drag == "sv" then
			cp.Sat = math.clamp((pos.X - P.sv.AbsolutePosition.X) / P.sv.AbsoluteSize.X, 0, 1)
			cp.Val = 1 - math.clamp((pos.Y - P.sv.AbsolutePosition.Y) / P.sv.AbsoluteSize.Y, 0, 1)
		elseif drag == "hue" then
			cp.Hue = math.clamp((pos.Y - P.hue.AbsolutePosition.Y) / P.hue.AbsoluteSize.Y, 0, 0.999)
		elseif drag == "alpha" then
			cp.Alpha = 1 - math.clamp((pos.X - P.alpha.AbsolutePosition.X) / P.alpha.AbsoluteSize.X, 0, 1)
		else return end
		update()
	end
	Library:Connect(hexBox.FocusLost, function()
		-- #RRGGBB keeps the opacity, #RRGGBBAA sets it
		local h = (hexBox.Text:gsub("[#%s]", ""))
		local a = cp.Alpha
		if #h == 8 then
			local n = tonumber(h:sub(7, 8), 16)
			if n then a = 1 - n / 255 end
			h = h:sub(1, 6)
		end
		set(h, a)
		update(true)
	end)
	Library:Connect(rgbBox.FocusLost, function()
		local r, g, b, a = rgbBox.Text:match("(%d+)%D+(%d+)%D+(%d+)%D*([%d%.]*)")
		if r then
			local op = tonumber(a)
			set(Color3.fromRGB(math.min(tonumber(r), 255), math.min(tonumber(g), 255), math.min(tonumber(b), 255)), op and (1 - math.clamp(op, 0, 1)) or cp.Alpha)
		end
		update(true)
	end)

	-- ---- animation: Rainbow / Fade Alpha (flags <flag>AnimationModeDropdown / AnimationIntensitySlider / AnimationSpeedSlider) ----
	local anim = { mode = nil, speed = 0.2, intensity = 50 }
	local flagMode, flagInt, flagSpeed = flag .. "AnimationModeDropdown", flag .. "AnimationIntensitySlider", flag .. "AnimationSpeedSlider"
	Library.Flags[flagInt], Library.Flags[flagSpeed] = anim.intensity, anim.speed
	local oldColor, oldAlpha
	local menuRows = {}
	local function paintAnim()
		for mode, o in menuRows do
			Library.themed(o.text, "TextColor3", anim.mode == mode and "Accent" or "Dim Text")
		end
	end
	local function setMode(mode)
		if mode ~= "Rainbow" and mode ~= "Fade Alpha" then mode = nil end
		if mode == anim.mode then return end
		if mode and not anim.mode then oldColor, oldAlpha = cp.Color, cp.Alpha end
		local was = anim.mode
		anim.mode = mode
		Library.Flags[flagMode] = mode
		paintAnim()
		if was and not mode and oldColor then set(oldColor, oldAlpha) end   -- the colour from before the animation comes back
	end
	local function setSpeed(v) anim.speed = math.clamp(math.floor((tonumber(v) or 0.2) * 100) / 100, 0, 5) Library.Flags[flagSpeed] = anim.speed paintAnim() end
	local function setIntensity(v) anim.intensity = math.clamp(math.floor(tonumber(v) or 50), 0, 100) Library.Flags[flagInt] = anim.intensity paintAnim() end
	local function trackDrag(track, apply)
		local down = false
		local function at(x) apply(math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)) end
		local hit = Instance.new("TextButton")
		hit.BackgroundTransparency, hit.Text, hit.Size, hit.Position, hit.ZIndex = 1, "", UDim2.new(1, 0, 0, 16), UDim2.new(0, 0, 0, -6), 6
		hit.Parent = track
		Library:Connect(hit.InputBegan, function(i)
			if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
				down = true at(i.Position.X)
				Library.beginDrag(function(m) at(m.Position.X) end, function() down = false end)
			end
		end)
	end
	-- right click on the swatch: Copy / Paste (the colour, shared by every picker of the menu) and the two animations
	do
		local M = Build.Panel(winRoot)
		M.Root.Visible, M.Root.ZIndex = false, 1000
		M.Root.Size = UDim2.new(0, 84, 0, 4 * 20 + 4)
		Library.fx.shadow(M.Root, { radius = 10, transparency = 0.15 })
		Library.fx.bevel(M.Root, 0.08)
		Library.listLayout(M.rows, 0)
		local function item(text, fn, mode)
			local O = Build.Option(M.rows)
			O.Root.Size, O.Root.BackgroundTransparency = UDim2.new(1, 0, 0, 20), 1
			O.text.Text = text
			O.text.Position, O.text.Size = UDim2.new(0, 6, 0, 0), UDim2.new(1, -12, 1, 0)
			local b = click(O.Root, function() fn() M.Root.Visible = false end)
			Library.fx.hover(b, function() Library.fx.tween(O.text, { TextColor3 = Library.Theme["Bright Text"] }, 0.1) end,
				function() Library.fx.tween(O.text, { TextColor3 = (mode and anim.mode == mode) and Library.Theme.Accent or Library.Theme["Dim Text"] }, 0.15) end)
			if mode then menuRows[mode] = { text = O.text } end
		end
		item("Copy", function()
			Library.ColorClipboard = { cp.Color, cp.Alpha }
			pcall(function() (setclipboard or toclipboard)("#" .. cp.Color:ToHex():upper()) end)
		end)
		item("Paste", function() local c = Library.ColorClipboard if c then set(c[1], c[2]) end end)
		item("Rainbow", function() setMode(anim.mode == "Rainbow" and nil or "Rainbow") end, "Rainbow")
		item("Fade Alpha", function() setMode(anim.mode == "Fade Alpha" and nil or "Fade Alpha") end, "Fade Alpha")
		local sb = click(S.Root)
		sb.ZIndex += 1
		Library:Connect(sb.MouseButton1Click, function() setOpen(not open) end)
		Library:Connect(sb.MouseButton2Click, function()
			M.Root.Visible = not M.Root.Visible
			Library.popupAt(M.Root, winRoot, S.Root, 3)
		end)
		Library:Connect(UserInputService.InputBegan, function(i)
			if M.Root.Visible and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) and not Library:IsMouseOverFrame(M.Root) then M.Root.Visible = false end
		end)
		Library.OnUnload = Library.OnUnload or {}
		table.insert(Library.OnUnload, function() pcall(function() M.Root:Destroy() end) end)
	end
	paintAnim()
	Library.animatedPickers = Library.animatedPickers or {}
	Library.animatedPickers[#Library.animatedPickers + 1] = function()
		if not anim.mode then return end
		if anim.mode == "Rainbow" then
			set(Color3.fromHSV(math.abs(math.sin(tick() * anim.speed)), 1, 1), cp.Alpha)
		else
			set(cp.Color, math.clamp(math.abs(math.sin(tick() % math.max(anim.intensity, 0.01)) * anim.speed), 0, 1))
		end
	end
	if not Library.animClock then
		local lastAnim = 0
		Library.animClock = Library:Connect(RunService.Heartbeat, function()
			local now = os.clock()
			if now - lastAnim < 1 / 30 then return end
			lastAnim = now
			for _, step in Library.animatedPickers do step() end
		end)
	end
	Library.SetFlags[flagMode] = setMode
	Library.SetFlags[flagSpeed] = setSpeed
	Library.SetFlags[flagInt] = setIntensity
	cp.SetAnimation = function(_, mode) setMode(mode) end

	Library.OnUnload = Library.OnUnload or {}
	table.insert(Library.OnUnload, function() pcall(function() P.Root:Destroy() end) end)
	local default = field(Data, "Default", "default") or Color3.new(1, 1, 1)
	set(default, field(Data, "Alpha", "alpha"))
	-- SetFlags keeps the current alpha (a config stores the colour as hex)
	Library.SetFlags[flag] = function(v) if type(v) == "table" then set(v.Color or v.HexValue, v.Alpha) else set(v, cp.Alpha) end end
	return cp
end

-- ---- Keybind ----
function Library.AddKeybind(owner, row, Data, ownerToggle)
	Data = Data or {}
	local flag = field(Data, "Flag", "flag") or Library:NextFlag()
	local name = field(Data, "Name", "name") or "Keybind"
	local callback = field(Data, "Callback", "callback")
	local passive = field(Data, "Passive", "passive") and true or false
	local K = Build.KeyPill(row)
	K.Root.LayoutOrder = 1
	local kb = { Toggled = false, Key = nil, Mode = "Toggle", Flag = flag, Picking = false, Items = {}, ShowInList = field(Data, "ShowInList", "showinlist") ~= false }
	K.text.FontFace = Library.FontBold
	K.text.TextXAlignment = Enum.TextXAlignment.Right
	K.text.Position += UDim2.fromOffset(0, -2)   -- Otterhook: level with the row label (was 2 px low)
	kb.Items.Pill = Library.Wrap(K.Root)
	local keyItem = Library.KeyList and Library.KeyList:Add("None", "None", "None")
	if keyItem and keyItem.Instance then keyItem.Instance.Visible = false end

	local function writeFlags()
		local f = Library.Flags[flag]
		if type(f) ~= "table" then f = {} Library.Flags[flag] = f end
		f.Mode, f.Key, f.Toggled = kb.Mode, kb.Key, kb.Toggled
	end
	local function update()
		if ownerToggle then kb.Toggled = ownerToggle.Value == true end   -- a toggle's keybind shows the toggle's real state
		writeFlags()
		K.text.Text = "[" .. keyText(kb.Key) .. "]"
		K.Root.Size = UDim2.new(0, math.max(18, #K.text.Text * 7 + 2), 0, 14)
		Library:ChangeItemTheme(K.text, { TextColor3 = kb.Toggled and "Text" or "Dim Text" })
		Library.fx.tween(K.text, { TextColor3 = kb.Toggled and Library.Theme.Text or Library.Theme["Dim Text"] }, 0.2)
		if keyItem then keyItem:Set(kb.Mode, name, keyText(kb.Key), kb.ShowInList) keyItem:SetStatus(kb.Toggled) end
	end
	local function fire() if callback then Library:SafeCall(callback, kb.Toggled) end end

	function kb:Get() return kb.Toggled, kb.Key, kb.Mode end
	function kb:SetVisibility(v) K.Root.Visible = v end
	function kb:SetMode(mode)
		kb.Mode = mode
		if ownerToggle then
			if mode == "Always" and not passive and not ownerToggle.Value then ownerToggle:Set(true) end
			kb.Toggled = ownerToggle.Value == true
		else kb.Toggled = mode == "Always" end
		update() fire()
	end
	function kb:Press(down)
		if ownerToggle and not passive then
			if kb.Mode == "Toggle" then ownerToggle:Set(not ownerToggle.Value)
			elseif kb.Mode == "Hold" then ownerToggle:Set(down == true)
			elseif kb.Mode == "Always" then ownerToggle:Set(true) end
			kb.Toggled = ownerToggle.Value == true
		elseif ownerToggle then kb.Toggled = ownerToggle.Value == true
		elseif kb.Mode == "Toggle" then kb.Toggled = not kb.Toggled
		elseif kb.Mode == "Hold" then kb.Toggled = down == true
		else kb.Toggled = true end
		update() fire()
	end
	function kb:Set(v)
		if typeof(v) == "EnumItem" then
			kb.Key = (v == Enum.KeyCode.Escape or v == Enum.KeyCode.Backspace) and "None" or tostring(v)
			update() fire()
		elseif type(v) == "string" and table.find({ "Toggle", "Hold", "Always" }, v) then
			kb:SetMode(v)
		elseif type(v) == "table" then
			local k = v.Key
			if typeof(k) == "EnumItem" then k = tostring(k) end
			kb.Key = (k == nil or k == "Backspace" or k == "[-]") and "None" or tostring(k)
			kb:SetMode(table.find({ "Toggle", "Hold", "Always" }, v.Mode) and v.Mode or "Toggle")   -- like the old lib: Always switches the toggle on
		end
		kb.Picking = false
	end

	-- right click: mode popup
	local winRoot = Library.popupRoot(owner.Section)
	local P = Build.Panel(winRoot)
	P.Root.Visible, P.Root.ZIndex = false, 1000
	P.Root.Size = UDim2.new(0, 112, 0, 20 + 3 * 20 + 8)
	Library.fx.shadow(P.Root, { radius = 10, transparency = 0.15 })
	Library.fx.bevel(P.Root, 0.08)
	Library.listLayout(P.rows, 0)
	Instance.new("UIPadding", P.rows).PaddingLeft = UDim.new(0, 4)
	-- "Show In List": whether this bind appears in the keybind list
	local modeRows = {}
	local function paintModes()
		for mode, t in modeRows do Library.themed(t, "TextColor3", kb.Mode == mode and "Accent" or "Dim Text") end
	end
	do
		local Sh = Build.Toggle(P.rows)
		Sh.Root.Size = UDim2.new(1, -4, 0, 20)
		Sh.label.Text = "Show In List"
		Sh.label.Position, Sh.label.Size = UDim2.new(0, 19, 0, 0), UDim2.new(1, -19, 1, 0)
		Sh.box.Position = UDim2.new(0, 1, 0, 4)
		Sh.check.AnchorPoint, Sh.check.Position, Sh.check.Size = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5), UDim2.fromScale(1, 1)
		local function paintShow()
			local on = kb.ShowInList
			Library.themed(Sh.box, "BackgroundColor3", on and "Accent" or "Inline")
			Sh.check.BackgroundTransparency = on and 0 or 1
			Library.themed(Sh.label, "TextColor3", on and "Accent" or "Dim Text")
		end
		paintShow()
		click(Sh.Root, function() kb.ShowInList = not kb.ShowInList paintShow() update() end)
		function kb:SetShowInList(b) kb.ShowInList = b and true or false paintShow() update() end
	end
	for _, mode in { "Toggle", "Hold", "Always" } do
		local O = Build.Option(P.rows)
		O.Root.Size, O.Root.BackgroundTransparency = UDim2.new(1, -4, 0, 20), 1
		O.text.Text = mode
		O.text.Position, O.text.Size = UDim2.new(0, 2, 0, 0), UDim2.new(1, -8, 1, 0)
		modeRows[mode] = O.text
		click(O.Root, function() kb:SetMode(mode) P.Root.Visible = false end)
	end
	local rb = click(K.Root)
	local unwatchKb
	Library:Connect(rb.MouseButton2Click, function()
		if unwatchKb then unwatchKb() unwatchKb = nil end
		P.Root.Visible = not P.Root.Visible
		paintModes()
		Library.popupAt(P.Root, winRoot, K.Root, 4)
		if P.Root.Visible then unwatchKb = Library.watchAnchor(K.Root, winRoot, function() unwatchKb = nil P.Root.Visible = false end) end
	end)
	Library:Connect(rb.MouseButton1Click, function()
		if kb.Picking then return end
		kb.Picking = true
		K.text.Text = "[...]"
		Library.fx.tween(K.text, { TextColor3 = Library.Theme.Accent }, 0.15)
		local c
		c = UserInputService.InputBegan:Connect(function(i)
			if i.UserInputType == Enum.UserInputType.Keyboard then kb:Set(i.KeyCode) else kb:Set(i.UserInputType) end
			c:Disconnect()
		end)
	end)
	Library:Connect(UserInputService.InputBegan, function(i)
		if P.Root.Visible and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) and not Library:IsMouseOverFrame(P.Root) and not Library:IsMouseOverFrame(K.Root) then P.Root.Visible = false end
		if kb.Picking or UserInputService:GetFocusedTextBox() then return end
		if kb.Key and (tostring(i.KeyCode) == kb.Key or tostring(i.UserInputType) == kb.Key) then
			if kb.Mode == "Toggle" then kb:Press() elseif kb.Mode == "Hold" then kb:Press(true) end
		end
	end)
	Library:Connect(UserInputService.InputEnded, function(i)
		if kb.Key and (tostring(i.KeyCode) == kb.Key or tostring(i.UserInputType) == kb.Key) and kb.Mode == "Hold" then kb:Press(false) end
	end)
	if ownerToggle then
		table.insert(ownerToggle.Listeners, function() update() end)
	end

	Library.OnUnload = Library.OnUnload or {}
	table.insert(Library.OnUnload, function() pcall(function() P.Root:Destroy() end) end)
	local default = field(Data, "Default", "default")
	local mode = field(Data, "Mode", "mode") or "Toggle"
	if default then kb:Set({ Key = default, Mode = mode }) else kb.Mode = mode update() end
	Library.SetFlags[flag] = function(v) kb:Set(v) end
	return kb
end


-- ===== runtime/hud.lua =====
-- Otterhook runtime part 5: HUD - notifications, watermark, keybind list, tooltips.

local GuiService = game:GetService("GuiService")
local function fade(inst, props, time) return Library:TweenTo(inst, props, time or 0.18) end

-- how far down the corners start: under Roblox's top bar when it is showing
local function cornerY()
	local ok, on = pcall(function() return game:GetService("StarterGui"):GetCore("TopbarEnabled") end)
	if ok and on == false then return 12 end
	local inset = GuiService:GetGuiInset()
	return inset.Y + 8
end

-- ---- Notification(Text, Duration, Color, Icon): stacked in the top left corner, slides in and fades out ----
do
	local holder = Instance.new("Frame")
	holder.Name = "\0"
	holder.BackgroundTransparency = 1
	holder.AnchorPoint = Vector2.new(0, 0)
	holder.Position = UDim2.new(0, 12, 0, cornerY())
	holder.Size = UDim2.new(0, 10, 0, 10)
	holder.AutomaticSize = Enum.AutomaticSize.XY
	holder.ZIndex = 2000
	holder.Parent = Library.Holder.Instance
	local l = Library.listLayout(holder, 6)
	l.HorizontalAlignment = Enum.HorizontalAlignment.Left
	Library.NotifHolder = Library.Wrap(holder)
end
function Library:Notification(Text, Duration, Color, Icon)
	if type(Text) == "table" then Text, Duration, Color = Text.text or Text.Text or Text.name, Text.time or Text.Duration, Text.color or Text.Color end
	local fx = Library.fx
	local N = Build.Notification(Library.NotifHolder.Instance)
	local root, text, bar, progress = N.Root, N.text, N.bar, N.progress
	local duration = tonumber(Duration) or 4
	root.AutomaticSize = Enum.AutomaticSize.X
	root.Size = UDim2.new(0, 0, 0, 30)
	root.ZIndex = 2001
	Library:ChangeItemTheme(root, { BackgroundColor3 = "Section Background" })
	root.BackgroundColor3 = Library.Theme["Section Background"]
	Library:ChangeItemTheme(text, { TextColor3 = "Bright Text" })
	text.TextColor3 = Library.Theme["Bright Text"]
	local pad = Instance.new("UIPadding", root)
	pad.PaddingRight = UDim.new(0, 12)
	text.Position = UDim2.new(0, 12, 0, 0)
	text.Size = UDim2.new(0, 0, 1, -1)
	text.AutomaticSize = Enum.AutomaticSize.X
	text.TextWrapped = false
	text.RichText = true
	text.Text = tostring(Text or "")
	text.ZIndex = 2003
	bar.AnchorPoint, bar.Position, bar.Size = Vector2.new(0, 0), UDim2.new(), UDim2.new(0, 2, 1, 0)
	bar.ZIndex = 2002
	progress.Position, progress.Size, progress.ZIndex = UDim2.new(0, 0, 1, -1), UDim2.new(1, 12, 0, 1), 2002
	if typeof(Color) == "Color3" then bar.BackgroundColor3, progress.BackgroundColor3 = Color, Color end
	local shadow = fx.shadow(root, { radius = 10, transparency = 0.25 })
	fx.bevel(root, 0.1)
	local sc = Instance.new("UIScale", root)
	-- pops in (scale + fade), the bottom bar drains for the duration, then it fades and shrinks away
	local stroke = root:FindFirstChildOfClass("UIStroke")
	local function alpha(a, t)
		fade(root, { BackgroundTransparency = a }, t)
		fade(text, { TextTransparency = a }, t)
		fade(bar, { BackgroundTransparency = a }, t)
		fade(progress, { BackgroundTransparency = a == 1 and 1 or 0.3 }, t)
		fade(shadow, { ImageTransparency = a == 1 and 1 or 0.25 }, t)
		if stroke then fade(stroke, { Transparency = a }, t) end
	end
	root.BackgroundTransparency, text.TextTransparency, bar.BackgroundTransparency, progress.BackgroundTransparency, shadow.ImageTransparency = 1, 1, 1, 1, 1
	if stroke then stroke.Transparency = 1 end
	sc.Scale = 0.85
	alpha(0, 0.22)
	fx.tween(sc, { Scale = 1 }, 0.35, Enum.EasingStyle.Back)
	fx.tween(progress, { Size = UDim2.new(0, 0, 0, 1) }, duration, Enum.EasingStyle.Linear)
	task.delay(duration, function()
		if not root.Parent then return end
		alpha(1, 0.2)
		fx.tween(sc, { Scale = 0.9 }, 0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		task.wait(0.22)
		pcall(function() root:Destroy() end)
	end)
	return root
end

-- ---- Watermark(Text, Icon) ----
function Library:Watermark(Text, Icon)
	local Wm = Build.Watermark(Library.Holder.Instance)
	local root = Wm.Root
	root.AnchorPoint = Vector2.new(1, 0)
	root.Position = UDim2.new(1, -12, 0, cornerY())
	root.AutomaticSize = Enum.AutomaticSize.X
	root.Size = UDim2.new(0, 0, 0, 24)
	root.ZIndex = 1500
	local pad = Instance.new("UIPadding", root)
	pad.PaddingRight = UDim.new(0, 8)
	if Wm.line then Wm.line.Size = UDim2.new(1, 8, 0, 2) Wm.line.ZIndex = 1502 end
	Library.fx.shadow(root, { radius = 10, transparency = 0.3 })
	Library.fx.bevel(root, 0.1)
	Wm.text.Position = UDim2.new(0, 26, 0, 1)
	Wm.text.Size = UDim2.new(0, 0, 1, -1)
	Wm.text.AutomaticSize = Enum.AutomaticSize.X
	Wm.text.TextWrapped = false
	Wm.text.RichText = true
	Wm.text.Text = tostring(Text or "Otterhook.cc")
	Wm.text.ZIndex = 1502
	Wm.logo.ZIndex = 1502
	if Icon and Icon ~= "" then pcall(function() Wm.logo.Image = tostring(Icon) end) end
	Library.MakeDraggable(root, root)
	local wm = { Instance = root }
	function wm:SetVisibility(b) root.Visible = b end
	function wm:SetText(t) Wm.text.Text = tostring(t) end
	return wm
end

-- ---- KeybindList: Library.KeyList:Add(Mode, Name, Key) -> row { Instance, Set, SetStatus } ----
function Library:KeybindList()
	if Library.KeyList then return Library.KeyList end
	local Kw = Build.KeybindWindow(Library.Holder.Instance)
	local root = Kw.Root
	root.Position = UDim2.new(0, 14, 0.38, 0)
	root.ZIndex = 1500
	-- The height follows the rows (set below), not AutomaticSize: an auto-sized window also counts every child that sticks out below it, and a
	-- drop shadow (a script's depth pass adds one) sticks out 24 px, so the window grew an empty band under the last row.
	local WIDTH, HEAD = 180, 21
	root.Size = UDim2.new(0, WIDTH, 0, HEAD + 4)
	Library.fx.shadow(root, { radius = 12, transparency = 0.2 })
	-- the header bar with the accent line on its left, "Keybinds"; under it one row per bind: the name on the left, [key] on the right.
	-- A bind that is off is dimmed, one that is on is bright.
	Kw.header.Position, Kw.header.Size = UDim2.new(), UDim2.new(1, 0, 0, HEAD)
	Kw.line.Position, Kw.line.Size, Kw.line.ZIndex = UDim2.new(), UDim2.new(0, 2, 0, HEAD), 1503
	Kw.header.ZIndex, Kw.title.ZIndex = 1501, 1502
	Kw.title.Position, Kw.title.Size = UDim2.new(0, 9, 0, 0), UDim2.new(1, -12, 1, 0)
	Kw.title.Text = "Keybinds"
	Library.fx.shade(Kw.header, 0.26)
	Kw.rows.AutomaticSize = Enum.AutomaticSize.Y
	Kw.rows.Position = UDim2.new(0, 6, 0, HEAD + 3)
	Kw.rows.Size = UDim2.new(1, -12, 0, 0)
	local rowsLayout = Library.listLayout(Kw.rows, 0)
	local function fitHeight()
		local h = rowsLayout.AbsoluteContentSize.Y
		root.Size = UDim2.new(0, WIDTH, 0, HEAD + (h > 0 and h + 6 or 0))
	end
	rowsLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(fitHeight)
	fitHeight()
	Library.MakeDraggable(Kw.header, root)
	local list = { Instance = root, Rows = {} }
	function list:SetVisibility(b) root.Visible = b end
	function list:SetTitle(t) Kw.title.Text = tostring(t) end
	function list:Add(Mode, Name, Key)
		local R = Build.KeybindRow(Kw.rows)
		R.Root.Size = UDim2.new(1, 0, 0, 18)
		R.Root.ZIndex = 1502
		R.text.ZIndex, R.key.ZIndex = 1503, 1503
		R.text.Position, R.text.Size = UDim2.new(), UDim2.new(1, -52, 1, 0)
		R.text.TextTruncate = Enum.TextTruncate.AtEnd
		R.key.AnchorPoint, R.key.Position, R.key.Size = Vector2.new(1, 0), UDim2.new(1, 0, 0, 0), UDim2.new(0, 60, 1, 0)
		R.key.FontFace = Library.FontBold
		local row = { Instance = R.Root, Label = R.text }
		local mode, name, key, status, shown = Mode, Name, Key, false, true
		local function draw()
			local k = tostring(key or ""):gsub("Enum%.KeyCode%.", ""):gsub("Enum%.UserInputType%.", ""):gsub("[%[%]]", "")
			R.text.Text = tostring(name)
			R.key.Text = "[" .. k .. "]"
			local c = status and "Text" or "Dim Text"
			Library:ChangeItemTheme(R.text, { TextColor3 = c })
			Library:ChangeItemTheme(R.key, { TextColor3 = c })
			fade(R.text, { TextColor3 = Library.Theme[c] }, 0.15)
			fade(R.key, { TextColor3 = Library.Theme[c] }, 0.15)
		end
		row.Draw = draw
		function row:Set(m, n, k, show)
			mode, name, key = m, n, k
			if show ~= nil then shown = show and true or false end
			draw()
			local text = tostring(k or "")
			-- a keybind with no key bound, or one taken off the list ("Show In List"), stays off the list
			R.Root.Visible = shown and text ~= "" and text ~= "None" and text ~= "-" and text ~= "[-]" and not string.find(text, "Unknown", 1, true)
		end
		function row:SetStatus(on)
			on = on == true
			if on == status then return end
			status = on
			draw()
		end
		row:Set(Mode, Name, Key)
		self.Rows[#self.Rows + 1] = row
		return row
	end
	Library.KeyList = list
	return list
end

-- ---- tooltips: one shared tooltip; every registered element is tested against the mouse (clicks overlays do not matter) ----
do
	local entries = {}
	local T
	local current, since, shown = nil, 0, nil
	-- hover events, not a scan: every mouse move used to test every registered element (position, size and all its parents'
	-- visibility), which in a big menu meant thousands of property reads per move
	function Library.attachTooltip(inst, text)
		if type(text) ~= "string" or text == "" then return end
		local e = { inst = inst, text = text }
		entries[#entries + 1] = e
		Library:Connect(inst.MouseEnter, function()
			if current ~= e then
				current, since = e, os.clock()
				if shown then shown.Root.Visible = false shown = nil end
			end
		end)
		Library:Connect(inst.MouseLeave, function()
			if current == e then
				current = nil
				if shown then shown.Root.Visible = false shown = nil end
			end
		end)
	end
	local function visible(inst)
		local p = inst
		while p and p ~= Library.Holder.Instance do
			if p:IsA("GuiObject") and not p.Visible then return false end
			p = p.Parent
		end
		return p ~= nil
	end
	local function under(mouse)
		for i = #entries, 1, -1 do
			local e = entries[i]
			if not e.inst.Parent then table.remove(entries, i)
			else
				local a, s = e.inst.AbsolutePosition, e.inst.AbsoluteSize
				if mouse.X >= a.X and mouse.X <= a.X + s.X and mouse.Y >= a.Y and mouse.Y <= a.Y + s.Y and visible(e.inst) then return e end
			end
		end
	end
	local function ensure()
		if T then return T end
		T = Build.Tooltip(Library.Holder.Instance)
		T.Root.Visible = false
		T.Root.ZIndex = 3000
		T.Root.AutomaticSize = Enum.AutomaticSize.X
		T.Root.Size = UDim2.new(0, 0, 0, 22)
		local pad = Instance.new("UIPadding", T.Root)
		pad.PaddingRight = UDim.new(0, 6)
		Library.fx.shadow(T.Root, { radius = 8, transparency = 0.25 })
		Library.fx.bevel(T.Root, 0.12)
		T.text.Position = UDim2.new(0, 6, 0, 0)
		T.text.Size = UDim2.new(0, 0, 1, 0)
		T.text.AutomaticSize = Enum.AutomaticSize.X
		T.text.TextWrapped = false
		T.text.ZIndex = 3001
		return T
	end
	Library:Connect(UserInputService.InputChanged, function(i)
		if not shown or i.UserInputType ~= Enum.UserInputType.MouseMovement then return end   -- only a shown tooltip follows the mouse
		local mouse = UserInputService:GetMouseLocation() - GuiService:GetGuiInset()
		shown.Root.Position = UDim2.new(0, mouse.X + 14, 0, mouse.Y + 18)
	end)
	Library:Connect(RunService.Heartbeat, function()
		if current and not shown and os.clock() - since > 0.35 and current.inst.Parent and visible(current.inst) then
			local t = ensure()
			t.text.Text = current.text
			local mouse = UserInputService:GetMouseLocation() - GuiService:GetGuiInset()
			t.Root.Position = UDim2.new(0, mouse.X + 14, 0, mouse.Y + 18)
			t.Root.Visible = true
			shown = t
		end
	end)
	Library:Connect(UserInputService.InputBegan, function(i)
		if (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) and shown then shown.Root.Visible = false shown = nil current = nil end
	end)
end


-- ===== runtime/features.lua =====
-- runtime part 6: element search and menu blur.

-- ---- search: Library.SearchWindow(window, query) ----
-- Elements register their frame + name (Library.regSearch); a section whose NAME matches shows all its elements; otherwise only matching ones.
-- Pages with no match are dimmed in the tab row; when the open page has no match the first page with one opens.
function Library.SearchWindow(window, query)
	query = tostring(query or ""):lower()
	local W = window._W
	local searching = query ~= ""
	local perSection, perPage, found = {}, {}, 0
	local nameMatch = {}
	for _, s in window.SectionList do nameMatch[s.section] = searching and s.name:lower():find(query, 1, true) ~= nil end
	for _, item in window.SearchItems do
		local match = (not searching) or nameMatch[item.section] or item.name:lower():find(query, 1, true) ~= nil
		if searching then
			if not item.hidden and not match then item.prev, item.hidden = item.root.Visible, true item.root.Visible = false
			elseif item.hidden and match then item.hidden = false item.root.Visible = item.prev ~= false end
		elseif item.hidden then
			item.hidden = false
			item.root.Visible = item.prev ~= false
		end
		if match and (not searching or item.root.Visible) then
			perSection[item.section] = true
			if searching and not nameMatch[item.section] then found += 1 end
		end
	end
	for _, s in window.SectionList do
		local show = (not searching) or perSection[s.section] or nameMatch[s.section]
		s.root.Visible = show and true or false
		if searching and show then perPage[s.page] = true if nameMatch[s.section] then found += 1 end end
	end
	local current
	for _, p in window.Pages do if p.Items["Page"].Instance.Visible then current = p end end
	local first
	for _, p in window.Pages do
		local has = (not searching) or perPage[p]
		local tab = p.Items["Inactive"].Instance
		local label = tab:FindFirstChild("label")
		if label then label.TextTransparency = has and 0 or 0.55 end
		if has and not first then first = p end
	end
	if searching and first and current and not perPage[current] then
		for _, p in window.Pages do p:Turn(p == first) end
	end
	if W.pageTitle then W.pageTitle.Text = searching and (tostring(found) .. " found") or (current and current.Name or W.pageTitle.Text) end
end

-- ---- menu blur + translucent window ----
Library.Blur = { Enabled = true, Size = 14, Transparency = 0.04 }
do
	local Lighting = game:GetService("Lighting")
	local effect = Instance.new("BlurEffect")
	effect.Name = "\0"
	effect.Size = 0
	effect.Enabled = true
	local function sweep()
		for _, c in Lighting:GetChildren() do
			if c:IsA("BlurEffect") and c:GetAttribute("OtterhookBlur") and c ~= effect then pcall(function() c:Destroy() end) end
		end
	end
	effect:SetAttribute("OtterhookBlur", true)
	pcall(sweep)
	pcall(function() effect.Parent = Lighting end)
	function Library.UpdateBlur()
		local anyOpen = false
		for _, w in Library.Windows do if w.IsOpen then anyOpen = true end end
		local target = (Library.Blur.Enabled and anyOpen) and Library.Blur.Size or 0
		Library:TweenTo(effect, { Size = target }, 0.25)
		for _, w in Library.Windows do
			Library:TweenTo(w._W.Root, { BackgroundTransparency = Library.Blur.Enabled and Library.Blur.Transparency or 0 }, 0.25)
		end
	end
	function Library:SetBlur(enabled, size, transparency)
		Library.Blur.Enabled = enabled and true or false
		if size then Library.Blur.Size = size end
		if transparency then Library.Blur.Transparency = transparency end
		Library.UpdateBlur()
	end
	Library.OnUnload = Library.OnUnload or {}
	table.insert(Library.OnUnload, function() pcall(function() effect:Destroy() end) pcall(sweep) end)
	task.defer(Library.UpdateBlur)
end


-- ===== runtime/pages.lua =====
-- Otterhook runtime part 7: the two special pages, Page:PlayerList and Page:SkinChanger (behaviour = uilibnewBlxStrike.lua, new look).

local function pageBox(page, title, height)
	local S = Build.Section(page.ColumnsData[1].Instance)
	S.Root.AutomaticSize = Enum.AutomaticSize.None
	S.Root.Size = UDim2.new(1, 0, 0, height + 7)
	-- the title in the groupbox's top edge (a mask strip of the window colour, growing with the text)
	S.title.Text = title
	S.title.AutomaticSize = Enum.AutomaticSize.X
	S.title.Position, S.title.Size = UDim2.new(0, 3, 0, 0), UDim2.new(0, 0, 1, 0)
	S.titleMask.AutomaticSize = Enum.AutomaticSize.X
	S.titleMask.Size = UDim2.new(0, 0, 0, 12)
	Instance.new("UIPadding", S.titleMask).PaddingRight = UDim.new(0, 3)
	S.titleMask.ZIndex, S.title.ZIndex = 3, 4
	S.card.AutomaticSize = Enum.AutomaticSize.None
	S.card.Size, S.card.Position = UDim2.new(1, 0, 0, height), UDim2.new(0, 0, 0, 7)
	S.content.AutomaticSize = Enum.AutomaticSize.None
	S.content.Position, S.content.Size = UDim2.new(0, 8, 0, 14), UDim2.new(1, -16, 1, -22)
	for _, c in S.content:GetChildren() do if c:IsA("UIListLayout") then c:Destroy() end end
	return S
end

local function fixedFrame(parent, pos, size)
	local f = Instance.new("Frame")
	f.Name = "\0"
	f.BackgroundTransparency = 1
	f.Position, f.Size = pos, size
	f.Parent = parent
	return f
end

local function label(parent, text, pos, size, color, textSize, align)
	local t = Instance.new("TextLabel")
	t.Name = "\0"
	t.BackgroundTransparency = 1
	t.FontFace, t.TextSize = Library.Font, textSize or 12
	t.TextColor3 = color or Library.Theme.Text
	t.TextXAlignment = align or Enum.TextXAlignment.Left
	t.TextTruncate = Enum.TextTruncate.AtEnd
	t.Text = text
	t.Position, t.Size = pos, size
	t.Parent = parent
	return t
end

-- ============================ PlayerList ============================
function Library:PlayerList(Data)
	local page = self
	if page.Columns ~= 1 then
		Library:Notification("Playerlist can only be added to a page with 1 column.", 5, Color3.fromRGB(235, 90, 90))
		return nil
	end
	Data = Data or {}
	local S = pageBox(page, "Players", 419)
	local content = S.content
	local scroll = Instance.new("ScrollingFrame")
	scroll.Name = "\0"
	scroll.BackgroundTransparency, scroll.BorderSizePixel = 1, 0
	scroll.ScrollBarThickness, scroll.ScrollBarImageColor3 = 2, Library.Theme.Inline
	scroll.CanvasSize, scroll.AutomaticCanvasSize = UDim2.new(), Enum.AutomaticSize.Y
	scroll.Position, scroll.Size = UDim2.new(), UDim2.new(1, 0, 0, 315)
	scroll.Parent = content
	Library.listLayout(scroll, 4)

	local DEFAULT_AVATAR = "rbxassetid://98200387761744"
	local avatar = Instance.new("ImageLabel")
	avatar.Name = "\0"
	avatar.BackgroundColor3, avatar.BorderSizePixel = Library.Theme.Element, 0
	avatar.Image = DEFAULT_AVATAR
	avatar.Position, avatar.Size = UDim2.new(0, 0, 0, 325), UDim2.new(0, 70, 0, 70)
	avatar.Parent = content
	Instance.new("UICorner", avatar).CornerRadius = UDim.new(0, 8)
	local userName = label(content, "None", UDim2.new(0, 80, 0, 330), UDim2.new(0.5, -90, 0, 16), Library.Theme.Text)
	local userId = label(content, "None", UDim2.new(0, 80, 0, 350), UDim2.new(0.5, -90, 0, 16), Library.Theme["Dim Text"])

	local pl = { Window = page.Window, Page = page, Player = nil, Players = {}, Items = { Playerlist = Library.Wrap(S.Root) } }

	local STATUS = {
		Neutral = { "Neutral", Color3.fromRGB(180, 180, 180) }, Priority = { "Priority", Color3.fromRGB(255, 50, 50) },
		Friendly = { "Friendly", Color3.fromRGB(83, 255, 83) },
	}
	-- the status dropdown (flag PlayerListPlayerStatus) sits at the bottom right
	local dropHost = fixedFrame(content, UDim2.new(1, -208, 0, 330), UDim2.new(0, 208, 0, 60))
	local fakeSection = { Items = { Content = Library.Wrap(dropHost) }, Window = page.Window, Page = page, Section = nil }
	fakeSection.Section = fakeSection
	local drop = Library.Dropdown(fakeSection, {
		Name = "Status", Flag = "PlayerListPlayerStatus", Items = { "Neutral", "Priority", "Friendly" }, Default = "All", MaxSize = 75,
		Callback = function(value)
			local p = pl.Player
			if not p or p == Players.LocalPlayer then return end
			local rec = pl.Players[p.Name]
			if not rec then return end
			local st = STATUS[value] or STATUS.Neutral
			rec.PlayerStatus.Instance.Text = st[1]
			rec.PlayerStatus.Instance.TextColor3 = st[2]
			if Library.OnPrioritize then pcall(Library.OnPrioritize, p.Name, value) end
		end,
	})
	fakeSection.Items.Content.Instance.Size = UDim2.new(0, 208, 0, 60)

	local function selectedInfo(p)
		if p then
			userName.Text = p.DisplayName .. " (@" .. p.Name .. ")"
			userId.Text = tostring(p.UserId)
			task.spawn(function()
				local ok, img = pcall(function() return Players:GetUserThumbnailAsync(p.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size420x420) end)
				if ok and pl.Player == p then avatar.Image = img end
			end)
		else
			avatar.Image = DEFAULT_AVATAR
			userName.Text, userId.Text = "None", "None"
		end
	end

	function pl:Add(player)
		local R = Build.PlayerRow(scroll)
		R.Root.Size = UDim2.new(1, 0, 0, 18)
		R.name.Text = player.Name
		local teamName = player.Team and player.Team.Name or "None"
		R.team.Text = teamName
		R.team.TextColor3 = player.Team and player.TeamColor.Color or Color3.fromRGB(180, 180, 180)
		local isMe = player == Players.LocalPlayer
		R.status.Text = isMe and "LocalPlayer" or "Neutral"
		R.status.TextColor3 = isMe and Library.Theme.Accent or Color3.fromRGB(180, 180, 180)
		R.bg.BackgroundTransparency = 1
		local rec = {
			Name = player.Name, Selected = false, Player = player,
			PlayerButton = Library.Wrap(R.Root), PlayerName = Library.Wrap(R.name), PlayerTeam = Library.Wrap(R.team),
			PlayerStatus = Library.Wrap(R.status), PlayerBackground = Library.Wrap(R.bg),
		}
		function rec:Toggle(mode)
			local active = mode == "Active"
			R.bg.BackgroundTransparency = active and 0 or 1
			R.name.TextColor3 = active and Library.Theme.Accent or Library.Theme.Text
		end
		function rec:Set()
			if rec.Selected then
				rec.Selected = false
				rec:Toggle("Inactive")
				pl.Player = nil
				selectedInfo(nil)
			else
				for _, o in pl.Players do o.Selected = false o:Toggle("Inactive") end
				rec.Selected = true
				rec:Toggle("Active")
				pl.Player = player
				selectedInfo(player)
			end
			if Data.Callback then Library:SafeCall(Data.Callback, pl.Player, rec.PlayerStatus, rec.PlayerTeam) end
		end
		Library.click(R.Root, function() rec:Set() end)
		pl.Players[player.Name] = rec
		return rec
	end
	function pl:Remove(name)
		local rec = pl.Players[name]
		if not rec then return end
		pcall(function() rec.PlayerButton.Instance:Destroy() end)
		if pl.Player and pl.Player.Name == name then pl.Player = nil selectedInfo(nil) end
		pl.Players[name] = nil
	end
	for _, p in Players:GetPlayers() do pl:Add(p) end
	Library:Connect(Players.PlayerAdded, function(p) pl:Add(p) end)
	Library:Connect(Players.PlayerRemoving, function(p) if pl.Players[p.Name] then pl:Remove(p.Name) end end)
	page.PlayerListData = pl
	return pl
end

-- ============================ SkinChanger ============================
local RARITY_RANK = { Stock = 0, Blue = 1, Purple = 2, Pink = 3, Red = 4, Forbidden = 5, Special = 6 }

-- ============================ SkinChanger 3D preview ============================
-- Data.Preview = function(weapon, skin) -> Instance | nil (a fresh model; skin nil = the weapon's default) adds a "Preview" box under the
-- Skin Changer box: the model turns in a ViewportFrame (drag to orbit, wheel / slider to zoom, "auto rotate" toggle). The builder runs in a
-- thread of its own (it may yield), the result is dropped when another item was asked for meanwhile. Data.PreviewHeight (default 280).
local function skinPreview(page, Data)
	local builder = field(Data, "Preview", "preview")
	if type(builder) ~= "function" then return nil end
	local fx = Library.fx
	local S = pageBox(page, "Preview", field(Data, "PreviewHeight", "previewheight") or 280)
	local content = S.content
	local MIN, MAX = 0.5, 3
	local pv = { Zoom = 1, Spin = true, Yaw = 0, Pitch = 0.12, Dragging = false }
	local caption = label(content, "", UDim2.new(), UDim2.new(1, 0, 0, 16), Library.Theme["Dim Text"], 13, Enum.TextXAlignment.Center)
	Library.themed(caption, "TextColor3", "Dim Text")
	-- the view: a dark frame with the viewport in it, a transparent button over it for the mouse
	local frame = Instance.new("Frame")
	frame.Name = "\0"
	frame.BorderSizePixel = 0
	frame.Position, frame.Size = UDim2.fromOffset(0, 20), UDim2.new(1, 0, 1, -48)
	frame.BackgroundColor3 = Library.Theme["Dark Liner"]
	Library.themed(frame, "BackgroundColor3", "Dark Liner")
	frame.ClipsDescendants = true
	frame.Parent = content
	local stroke = Instance.new("UIStroke", frame)
	stroke.Color, stroke.ApplyStrokeMode = Library.Theme.Outline, Enum.ApplyStrokeMode.Border
	Library.themed(stroke, "Color", "Outline")
	local vpf = Instance.new("ViewportFrame")
	vpf.Name = "\0"
	vpf.BackgroundTransparency, vpf.BorderSizePixel = 1, 0
	vpf.Size = UDim2.fromScale(1, 1)
	vpf.Ambient, vpf.LightColor = Color3.fromRGB(165, 165, 165), Color3.new(1, 1, 1)
	vpf.LightDirection = Vector3.new(-0.4, -1, -0.6)
	vpf.Parent = frame
	local cam = Instance.new("Camera")
	cam.FieldOfView = 30
	cam.Parent = vpf
	vpf.CurrentCamera = cam
	local world = Instance.new("WorldModel")
	world.Parent = vpf
	local empty = label(frame, "", UDim2.new(), UDim2.fromScale(1, 1), Library.Theme["Dim Text"], 13, Enum.TextXAlignment.Center)
	Library.themed(empty, "TextColor3", "Dim Text")
	empty.ZIndex = 2

	-- the model: scripts / sounds / animators out, parts anchored, the long axis along X, centred on the origin
	local model, fitDist, halfLen = nil, 6, 2
	local function setModel(m)
		if model then model:Destroy() model = nil end
		if typeof(m) ~= "Instance" then return end
		if not m:IsA("Model") then
			local wrap = Instance.new("Model")
			m.Parent = wrap
			m = wrap
		end
		for _, d in m:GetDescendants() do
			if d:IsA("BaseScript") or d:IsA("Sound") or d:IsA("AnimationController") or d:IsA("Animator") or d:IsA("Humanoid") then d:Destroy()
			elseif d:IsA("BasePart") then d.Anchored, d.CanCollide = true, false end
		end
		-- the box in WORLD axes, from the parts (Model:GetBoundingBox / GetExtentsSize follow the model's own pivot, which turning it does not change)
		local function worldBox()
			local lo, hi = Vector3.new(math.huge, math.huge, math.huge), Vector3.new(-math.huge, -math.huge, -math.huge)
			for _, d in m:GetDescendants() do
				if d:IsA("BasePart") then
					local cf, s = d.CFrame, d.Size
					local r, u, l = cf.RightVector, cf.UpVector, cf.LookVector
					local half = Vector3.new(
						(math.abs(r.X) * s.X + math.abs(u.X) * s.Y + math.abs(l.X) * s.Z) / 2,
						(math.abs(r.Y) * s.X + math.abs(u.Y) * s.Y + math.abs(l.Y) * s.Z) / 2,
						(math.abs(r.Z) * s.X + math.abs(u.Z) * s.Y + math.abs(l.Z) * s.Z) / 2)
					lo, hi = lo:Min(cf.Position - half), hi:Max(cf.Position + half)
				end
			end
			return lo, hi
		end
		local lo, hi = worldBox()
		if hi.X < lo.X then m:Destroy() return end   -- no parts
		if hi.Z - lo.Z > (hi.X - lo.X) * 1.1 then   -- the long axis along X: a turn from where it is
			m:PivotTo(CFrame.Angles(0, math.rad(90), 0) * m:GetPivot())
			lo, hi = worldBox()
		end
		m:PivotTo(CFrame.new(-(lo + hi) / 2) * m:GetPivot())
		local sz = hi - lo
		m.Parent = world
		model = m
		halfLen = math.max(sz.X, sz.Z) / 2
		-- the height (not the length) fills the view: the view is wide and short
		fitDist = math.max(sz.Y, sz.Z * 0.6, 0.4) / (2 * math.tan(math.rad(cam.FieldOfView) / 2)) * 1.7
	end
	local token = 0
	function pv.Show(weapon, skin)
		local key = tostring(weapon) .. "|" .. tostring(skin)
		if key == pv.key then return end
		pv.key = key
		token += 1
		local mine = token
		caption.Text = weapon and (tostring(weapon) .. (skin and ("  -  " .. tostring(skin)) or "  -  default")) or ""
		if not weapon then setModel(nil) empty.Text = "" return end
		task.spawn(function()
			local ok, m = pcall(builder, weapon, skin)
			if mine ~= token or not Library.Alive then
				if ok and typeof(m) == "Instance" then pcall(function() m:Destroy() end) end
				return
			end
			if ok and typeof(m) == "Instance" then
				setModel(m)
				empty.Text = ""
			else
				setModel(nil)
				empty.Text = "No preview for this item."
			end
		end)
	end

	-- the camera: orbit around the model, auto rotate, zoom
	Library:Connect(RunService.RenderStepped, function(dt)
		if not model then return end
		local g = vpf
		local holder = Library.Holder.Instance
		while g and g ~= holder do
			if g:IsA("GuiObject") and not g.Visible then return end   -- another tab / the menu closed
			g = g.Parent
		end
		if pv.Spin and not pv.Dragging then pv.Yaw += dt * 0.7 end
		local d = math.max(fitDist / pv.Zoom, halfLen * 0.9)
		local dir = Vector3.new(math.sin(pv.Yaw) * math.cos(pv.Pitch), math.sin(pv.Pitch), math.cos(pv.Yaw) * math.cos(pv.Pitch))
		cam.CFrame = CFrame.lookAt(dir * d, Vector3.zero)
	end)
	local hit = Instance.new("TextButton")
	hit.Name = "\0"
	hit.Text, hit.AutoButtonColor, hit.BackgroundTransparency = "", false, 1
	hit.Size, hit.ZIndex = UDim2.fromScale(1, 1), 20
	hit.Parent = frame
	local MB1, TOUCH = Enum.UserInputType.MouseButton1, Enum.UserInputType.Touch
	local lastPos
	Library:Connect(hit.InputBegan, function(i)
		if i.UserInputType == MB1 or i.UserInputType == TOUCH then pv.Dragging, lastPos = true, i.Position end
	end)
	Library:Connect(UserInputService.InputChanged, function(i)
		if pv.Dragging and lastPos and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == TOUCH) then
			local d = i.Position - lastPos
			lastPos = i.Position
			pv.Yaw -= d.X * 0.012
			pv.Pitch = math.clamp(pv.Pitch + d.Y * 0.01, -1.2, 1.2)
		end
	end)
	Library:Connect(UserInputService.InputEnded, function(i)
		if i.UserInputType == MB1 or i.UserInputType == TOUCH then pv.Dragging = false end
	end)

	-- the bottom row: zoom slider (left), auto rotate toggle (right)
	local row = fixedFrame(content, UDim2.new(0, 0, 1, -22), UDim2.new(1, 0, 0, 20))
	local zoomRow = fixedFrame(row, UDim2.new(), UDim2.new(1, -150, 1, 0))
	local function small(txt, x, align, width)
		local t = label(zoomRow, txt, UDim2.fromScale(x, 0), UDim2.new(0, width, 1, 0), Library.Theme["Dim Text"], 12, align)
		t.AnchorPoint = Vector2.new(x, 0)
		Library.themed(t, "TextColor3", "Dim Text")
		return t
	end
	small("zoom", 0, Enum.TextXAlignment.Left, 36)
	local value = small("1x", 1, Enum.TextXAlignment.Right, 40)
	local track = Instance.new("Frame")
	track.Name = "\0"
	track.BorderSizePixel = 0
	track.BackgroundColor3 = Library.Theme.Inline
	Library.themed(track, "BackgroundColor3", "Inline")
	track.Position, track.Size = UDim2.new(0, 42, 0.5, -4), UDim2.new(1, -88, 0, 8)
	track.Parent = zoomRow
	local trackStroke = Instance.new("UIStroke", track)
	trackStroke.Color = Library.Theme.Outline
	Library.themed(trackStroke, "Color", "Outline")
	local fill = Instance.new("Frame")
	fill.Name = "\0"
	fill.BorderSizePixel = 0
	fill.BackgroundColor3 = Library.Theme.Accent
	Library.themed(fill, "BackgroundColor3", "Accent")
	fill.Parent = track
	local zflag = tostring(field(Data, "ZoomFlag", "zoomflag") or "SkinPreviewZoom")
	local function setZoom(v)
		v = tonumber(v)
		if not v then return end
		v = math.clamp(Library:Round(v, 0.05), MIN, MAX)
		pv.Zoom = v
		Library.Flags[zflag] = v
		fill.Size = UDim2.new((v - MIN) / (MAX - MIN), 0, 1, 0)
		value.Text = string.format("%.2gx", v)
	end
	Library.SetFlags[zflag] = setZoom
	setZoom(1)
	local zhit = Library.click(track)
	zhit.Size, zhit.Position = UDim2.new(1, 0, 1, 8), UDim2.fromOffset(0, -4)
	local zdrag = false
	local function at(x) setZoom(MIN + (MAX - MIN) * math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)) end
	Library:Connect(zhit.InputBegan, function(i) if i.UserInputType == MB1 or i.UserInputType == TOUCH then zdrag = true at(i.Position.X) end end)
	Library:Connect(UserInputService.InputChanged, function(i) if zdrag and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == TOUCH) then at(i.Position.X) end end)
	Library:Connect(UserInputService.InputEnded, function(i) if i.UserInputType == MB1 or i.UserInputType == TOUCH then zdrag = false end end)
	Library:Connect(hit.InputChanged, function(i)
		if i.UserInputType == Enum.UserInputType.MouseWheel then setZoom(pv.Zoom + i.Position.Z * 0.1) end
	end)
	-- auto rotate: the design sheet's Toggle
	do
		local T = Build.Toggle(row)
		T.Root.AnchorPoint, T.Root.Position, T.Root.Size = Vector2.new(1, 0), UDim2.new(1, 0, 0, 0), UDim2.new(0, 140, 0, 19)
		T.label.Text = "auto rotate"
		T.label.Size = UDim2.new(1, -18, 0, 15)
		T.check.AnchorPoint, T.check.Position, T.check.Size = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5), UDim2.fromScale(1, 1)
		local sflag = tostring(field(Data, "SpinFlag", "spinflag") or "SkinPreviewSpin")
		local function set(v)
			v = v and true or false
			pv.Spin = v
			Library.Flags[sflag] = v
			Library:ChangeItemTheme(T.box, { BackgroundColor3 = v and "Accent" or "Inline" })
			fx.tween(T.box, { BackgroundColor3 = v and Library.Theme.Accent or Library.Theme.Inline }, 0.14)
			fx.tween(T.check, { BackgroundTransparency = v and 0 or 1 }, 0.14)
		end
		Library.SetFlags[sflag] = set
		Library.click(T.Root, function() set(not pv.Spin) end)
		set(true)
	end
	return pv
end

function Library:SkinChanger(Data)
	local page = self
	if page.Columns ~= 1 then
		Library:Notification("SkinChanger can only be added to a page with 1 column.", 5, Color3.fromRGB(235, 90, 90))
		return nil
	end
	Data = Data or {}
	local flag = field(Data, "Flag", "flag") or Library:NextFlag()
	local callback = field(Data, "Callback", "callback") or function() end
	local height = field(Data, "Height", "height") or 640
	local S = pageBox(page, "Skin Changer", height)
	local pv = skinPreview(page, Data)   -- the 3D preview box under it (when the script gives a builder)
	local content = S.content
	local ch = { Window = page.Window, Page = page, Flag = flag, Callback = callback, Catalog = field(Data, "Catalog", "catalog") or {}, Height = height,
		Selected = {}, Category = 1, Weapon = nil, Query = "", Items = { SkinChanger = Library.Wrap(S.Root) } }

	local function save()
		local ok, json = pcall(function() return HttpService:JSONEncode(ch.Selected) end)
		Library.Flags[flag] = (ok and next(ch.Selected) ~= nil) and json or "{}"   -- an empty selection is "{}" (not "[]")
	end
	save()
	local function fire(w, skin)
		task.spawn(function()
			local ok, err = pcall(callback, w, skin)
			if not ok then warn("[SkinChanger] callback: " .. tostring(err)) end
		end)
	end

	-- layout: categories / weapon chips + search / cards / info / buttons
	local catRow = fixedFrame(content, UDim2.new(), UDim2.new(1, 0, 0, 28))
	Library.listLayout(catRow, 6, Enum.FillDirection.Horizontal)
	local chipRow = Instance.new("ScrollingFrame")
	chipRow.Name = "\0"
	chipRow.BackgroundTransparency, chipRow.BorderSizePixel = 1, 0
	chipRow.ScrollBarThickness = 0
	chipRow.CanvasSize, chipRow.AutomaticCanvasSize, chipRow.ScrollingDirection = UDim2.new(), Enum.AutomaticSize.X, Enum.ScrollingDirection.X
	chipRow.Position, chipRow.Size = UDim2.new(0, 0, 0, 34), UDim2.new(1, -186, 0, 28)
	chipRow.Parent = content
	Library.listLayout(chipRow, 6, Enum.FillDirection.Horizontal)
	local searchHost = Build.Textbox(content)
	searchHost.Root.Position, searchHost.Root.Size = UDim2.new(1, -178, 0, 34), UDim2.new(0, 178, 0, 28)
	searchHost.label.Visible = false
	searchHost.field.Position, searchHost.field.Size = UDim2.new(), UDim2.new(1, 0, 1, 0)
	searchHost.input.Visible = false
	local sbox = Instance.new("TextBox")
	sbox.BackgroundTransparency, sbox.BorderSizePixel = 1, 0
	sbox.Size, sbox.Position = UDim2.new(1, -20, 1, 0), UDim2.new(0, 10, 0, 0)
	sbox.FontFace, sbox.TextSize, sbox.TextXAlignment = Library.Font, 14, Enum.TextXAlignment.Left
	sbox.TextColor3, sbox.PlaceholderColor3 = Library.Theme.Text, Library.Theme["Dim Text"]
	sbox.PlaceholderText, sbox.Text, sbox.ClearTextOnFocus = "Search skins...", "", false
	sbox.Parent = searchHost.field
	local grid = Instance.new("ScrollingFrame")
	grid.Name = "\0"
	grid.BackgroundTransparency, grid.BorderSizePixel = 1, 0
	grid.ScrollBarThickness, grid.ScrollBarImageColor3 = 3, Library.Theme.Inline
	grid.CanvasSize, grid.AutomaticCanvasSize = UDim2.new(), Enum.AutomaticSize.Y
	grid.Position, grid.Size = UDim2.new(0, 0, 0, 72), UDim2.new(1, 0, 1, -72 - 62)
	grid.Parent = content
	local gl = Instance.new("UIGridLayout")
	local GAP, MIN_CARD = 8, 150
	gl.CellSize, gl.CellPadding, gl.SortOrder = UDim2.new(0, 150, 0, 188), UDim2.new(0, GAP, 0, GAP), Enum.SortOrder.LayoutOrder
	gl.Parent = grid
	local emptyLabel = label(content, "", UDim2.new(0, 0, 0, 110), UDim2.new(1, 0, 0, 20), Library.Theme["Dim Text"], 14, Enum.TextXAlignment.Center)
	local info = label(content, "", UDim2.new(0, 0, 1, -54), UDim2.new(1, 0, 0, 18), Library.Theme["Dim Text"], 12)
	local btnRow = fixedFrame(content, UDim2.new(0, 0, 1, -30), UDim2.new(1, 0, 0, 30))
	local resetWeapon = Build.Button(btnRow)
	resetWeapon.Root.Size, resetWeapon.Root.Position = UDim2.new(0.5, -4, 0, 30), UDim2.new()
	resetWeapon.label.Text = "Reset Weapon"
	local resetAll = Build.Button(btnRow)
	resetAll.Root.Size, resetAll.Root.Position = UDim2.new(0.5, -4, 0, 30), UDim2.new(0.5, 4, 0, 0)
	resetAll.label.Text = "Reset All"

	local chipRefs, catRefs = {}, {}
	-- a chip: 28 px high, the label centred in it, the underline on its bottom edge (the template is 22 px high)
	local function styleChip(C, width, text)
		C.Root.Size = UDim2.new(0, width, 0, 28)
		C.text.Text = text
		C.text.Position, C.text.Size = UDim2.new(0, 0, 0, 0), UDim2.new(1, 0, 1, -2)
		C.text.TextSize = 13
		C.dot.Position, C.dot.Size = UDim2.new(0, 1, 1, -3), UDim2.new(1, -2, 0, 2)
	end
	-- every chip of a row is as wide as the longest label (min 64), so the row reads as columns
	local function chipWidth(names)
		local longest = 0
		for _, n in names do longest = math.max(longest, #tostring(n)) end
		return math.max(64, longest * 7 + 28)
	end
	local function weaponsOf(cat) return cat and cat.Weapons or {} end
	local function currentCat() return ch.Catalog[ch.Category] end
	local function currentWeapon()
		for _, w in weaponsOf(currentCat()) do if w.Name == ch.Weapon then return w end end
	end
	local function count() local n = 0 for _ in ch.Selected do n += 1 end return n end
	local function refreshInfo()
		local n = count()
		local sel = ch.Weapon and ch.Selected[ch.Weapon]
		info.Text = (ch.Weapon and (ch.Weapon .. ":  " .. (sel or "default") .. "     |     ") or "") .. n .. (n == 1 and " skin" or " skins") .. " chosen"
	end
	local function paintChip(ref, active)
		Library.themed(ref.Root, "BackgroundColor3", active and "Accent" or "Element")
		Library.themed(ref.text, "TextColor3", active and Color3.fromRGB(15, 15, 15) or Color3.fromRGB(169, 169, 178))
	end
	local renderCards, setCategory

	local function paintStates()
		for name, ref in chipRefs do ref.dot.Visible = ch.Selected[name] ~= nil end
	end

	local function buildChips()
		for _, r in chipRefs do pcall(function() r.Root:Destroy() end) end
		table.clear(chipRefs)
		local names = {}
		for _, w in weaponsOf(currentCat()) do names[#names + 1] = w.Name end
		local width = chipWidth(names)
		for i, w in weaponsOf(currentCat()) do
			local C = Build.Chip(chipRow)
			C.Root.LayoutOrder = i
			styleChip(C, width, w.Name)
			C.dot.ZIndex = C.Root.ZIndex + 3
			chipRefs[w.Name] = C
			paintChip(C, w.Name == ch.Weapon)
			Library.click(C.Root, function()
				ch.Weapon = w.Name
				for name, ref in chipRefs do paintChip(ref, name == ch.Weapon) end
				renderCards()
			end)
		end
		paintStates()
	end

	local function categoryOf(weapon)
		for _, cat in ch.Catalog do for _, w in cat.Weapons or {} do if w.Name == weapon then return cat end end end
	end

	function ch:Select(weapon, skin)
		if type(weapon) ~= "string" then return end
		local cat = categoryOf(weapon)
		if skin ~= nil and cat and cat.Exclusive then
			for other in ch.Selected do
				if other ~= weapon then
					for _, w in cat.Weapons do if w.Name == other then ch.Selected[other] = nil fire(other, nil) break end end
				end
			end
		end
		ch.Selected[weapon] = skin
		save()
		paintStates()
		renderCards()
		fire(weapon, skin)
	end
	function ch:Toggle(weapon, skin)
		if ch.Selected[weapon] == skin then skin = nil end
		ch:Select(weapon, skin)
	end
	function ch:Get() return table.clone(ch.Selected) end
	function ch:ResetAll()
		local old = ch.Selected
		ch.Selected = {}
		save()
		paintStates()
		renderCards()
		for w in old do fire(w, nil) end
	end

	local function cardClick(weapon, skin) ch:Toggle(weapon, skin) end
	-- the parts of a card follow the card's size (cw x chh): the image takes the upper ~58 %, the name and the collection sit under it
	local cards = {}
	local function layoutCard(C, cw, chh)
		local imgH = math.floor(chh * 0.58)
		C.stripe.Position, C.stripe.Size = UDim2.new(0, 1, 0, 1), UDim2.new(1, -2, 0, 3)
		C.image.Position, C.image.Size = UDim2.new(0, 10, 0, 12), UDim2.new(1, -20, 0, imgH)
		C.name.Position, C.name.Size = UDim2.new(0, 6, 0, 12 + imgH + 8), UDim2.new(1, -12, 0, 18)
		C.name.TextSize = 13
		C.sub.Position, C.sub.Size = UDim2.new(0, 6, 0, 12 + imgH + 28), UDim2.new(1, -12, 0, 16)
		C.sub.TextSize = 11
		C.badge.Position, C.badge.Size = UDim2.new(1, -32, 0, 9), UDim2.new(0, 26, 0, 14)
	end
	-- cards fill the row edge to edge: as many columns as fit MIN_CARD, the rest of the width shared out (sizes are offsets, so the
	-- window's UIScale is divided out; the card box's own height gives the scale)
	local cardW, cardH = MIN_CARD, math.floor(MIN_CARD * 1.25)
	local function relayout()
		local k = S.card.AbsoluteSize.Y / math.max(height, 1)
		if k <= 0 then k = 1 end
		local W = grid.AbsoluteSize.X / k - 6
		if W < MIN_CARD then return end
		local cols = math.max(1, math.floor((W + GAP) / (MIN_CARD + GAP)))
		local cw = math.floor((W - GAP * (cols - 1)) / cols)
		local chh = math.floor(cw * 1.25)
		if cw == cardW and chh == cardH then return end
		cardW, cardH = cw, chh
		gl.CellSize = UDim2.fromOffset(cw, chh)
		for c in cards do
			if c.Root.Parent then layoutCard(c, cw, chh) else cards[c] = nil end
		end
	end
	Library:Connect(grid:GetPropertyChangedSignal("AbsoluteSize"), relayout)
	local function makeCard(order, weapon, entry)
		local C = Build.SkinCard(grid)
		C.Root.LayoutOrder = order
		layoutCard(C, cardW, cardH)
		cards[C] = true
		local on
		if entry then
			on = ch.Selected[weapon] == entry.Skin
			C.stripe.BackgroundColor3 = entry.Color or Library.Theme.Border
			local img = Instance.new("ImageLabel")
			img.BackgroundTransparency, img.Size, img.ScaleType = 1, UDim2.fromScale(1, 1), Enum.ScaleType.Fit
			img.Image = tostring(entry.Image or "")
			img.Parent = C.image
			C.name.Text = tostring(entry.Skin)
			C.sub.Text = tostring(entry.Sub or entry.Rarity or "")
		else
			on = ch.Selected[weapon] == nil
			C.stripe.BackgroundColor3 = Library.Theme.Border
			label(C.image, "DEFAULT", UDim2.new(), UDim2.fromScale(1, 1), Library.Theme["Dim Text"], 13, Enum.TextXAlignment.Center)
			C.name.Text = "Default " .. weapon
			C.sub.Text = ""
		end
		C.name.TextTruncate = Enum.TextTruncate.AtEnd
		C.badge.Visible = on and true or false
		local stroke = C.Root:FindFirstChildOfClass("UIStroke")
		if stroke then stroke.Color = on and Library.Theme.Accent or Library.Theme.Border stroke.Thickness = on and 2 or 1 end
		local cardBtn = Library.click(C.Root, function() cardClick(weapon, entry and entry.Skin or nil) end)
		if pv then
			-- hovering a card previews it; leaving shows the chosen one again
			Library:Connect(cardBtn.MouseEnter, function() pv.Show(weapon, entry and entry.Skin or nil) end)
			Library:Connect(cardBtn.MouseLeave, function() if ch.PreviewCurrent then ch.PreviewCurrent() end end)
		end
		return C
	end

	function ch.PreviewCurrent()
		if pv then pv.Show(ch.Weapon, ch.Weapon and ch.Selected[ch.Weapon] or nil) end
	end
	function renderCards()
		ch.PreviewCurrent()
		for _, c in grid:GetChildren() do if c:IsA("Frame") then c:Destroy() end end
		table.clear(cards)
		relayout()
		grid.CanvasPosition = Vector2.new()
		emptyLabel.Text = ""
		refreshInfo()
		local w = currentWeapon()
		if not w then emptyLabel.Text = "No weapon in this category." return end
		local skins, q = {}, ch.Query:lower()
		for _, e in w.Skins or {} do
			if q == "" or tostring(e.Skin):lower():find(q, 1, true) or tostring(e.Sub or ""):lower():find(q, 1, true) or tostring(e.Rarity or ""):lower():find(q, 1, true) then
				skins[#skins + 1] = e
			end
		end
		table.sort(skins, function(a, b)
			local ra, rb = RARITY_RANK[a.Rarity] or 9, RARITY_RANK[b.Rarity] or 9
			if ra ~= rb then return ra < rb end
			return tostring(a.Skin) < tostring(b.Skin)
		end)
		local order = 0
		if q == "" then order += 1 makeCard(order, w.Name, nil) end
		for _, e in skins do order += 1 makeCard(order, w.Name, e) end
		if #skins == 0 then emptyLabel.Text = q == "" and "This weapon has no skins." or ('No skin matches "' .. ch.Query .. '".') end
	end

	function setCategory(i)
		ch.Category = i
		for idx, ref in catRefs do paintChip(ref, idx == i) end
		local keep = false
		for _, w in weaponsOf(currentCat()) do if w.Name == ch.Weapon then keep = true end end
		if not keep then local first = weaponsOf(currentCat())[1] ch.Weapon = first and first.Name or nil end
		buildChips()
		renderCards()
	end
	local function buildCategories()
		for _, r in catRefs do pcall(function() r.Root:Destroy() end) end
		table.clear(catRefs)
		local names = {}
		for _, cat in ch.Catalog do names[#names + 1] = cat.Name end
		local width = chipWidth(names)
		for i, cat in ch.Catalog do
			local C = Build.Chip(catRow)
			C.Root.LayoutOrder = i
			styleChip(C, width, cat.Name)
			C.dot.Visible = false
			catRefs[i] = C
			Library.click(C.Root, function() setCategory(i) end)
		end
	end
	function ch:SetCatalog(c)
		ch.Catalog = c or {}
		if ch.Category > #ch.Catalog then ch.Category = 1 end
		buildCategories()
		setCategory(ch.Category)
	end
	function ch:Refresh() setCategory(ch.Category) end

	local token = 0
	Library:Connect(sbox:GetPropertyChangedSignal("Text"), function()
		token += 1
		local mine = token
		task.delay(0.15, function() if mine == token then ch.Query = sbox.Text renderCards() end end)
	end)
	Library.click(resetWeapon.Root, function() if ch.Weapon and ch.Selected[ch.Weapon] ~= nil then ch:Select(ch.Weapon, nil) end end)
	Library.click(resetAll.Root, function() ch:ResetAll() end)

	Library.SetFlags[flag] = function(value)
		local decoded = value
		if type(value) == "string" then
			local ok, d = pcall(function() return HttpService:JSONDecode(value) end)
			decoded = ok and d or nil
		end
		if type(decoded) ~= "table" then return end
		local new = {}
		for w, s in decoded do if type(w) == "string" and type(s) == "string" then new[w] = s end end
		local old = ch.Selected
		ch.Selected = new
		save()
		paintStates()
		renderCards()
		for w, s in new do if old[w] ~= s then fire(w, s) end end
		for w in old do if new[w] == nil then fire(w, nil) end end
	end

	buildCategories()
	setCategory(1)
	return ch
end


-- ===== runtime/extras.lua =====
-- Otterhook runtime part 8: the extras - ESP preview window, body part picker, loader.

-- ---- Library:EspPreview(Data) -> preview ----
-- A floating window with a turning model of your character (a ViewportFrame) and the ESP drawn over it, laid out like a real ESP: flags right of the box,
-- name + weapon above it, distance below. preview:Sync({ key = value, ... }) sets many at once, preview:Set(key, value) one. Keys (defaults in `state` below):
--   Box, BoxColor, OutlineColor | Fill, FillColor1, FillColor2, FillTransparency1, FillTransparency2, FillSpin | Glow
--   Name, NameText, NameColor, NameSize, NameOutline, NameOutlineColor | Distance | Weapon, WeaponText, FlagSize, FlagColor, FlagLines ({ { text, col } ... })
--   Health, HealthPos (Left / Right / Top / Bottom), HealthGap, HealthWidth, HealthOutline (Full / Fit / None), HealthOutlineColor, HealthGradient, HealthColor1 / 2 / 3,
--   HealthText, HealthTextFollow, HealthTextHideFull, HealthTextGradient, HealthTextSize
--   Chams, ChamsColor, ChamsStyle (Flat / Liquid / Test), ChamsTransparency, LiquidSpeed, TestGlow, ChamsWalls, ChamsOutline, ChamsOutlineColor, ChamsOutlineThickness,
--   ChamsOutlineWalls, ChamsVisCheck, ChamsVisibleColor | Skeleton, HeadCircle, LookDir, LookCone, LookLength, LineColor | Wall, AutoRotate
-- The view is 3D: drag in it to turn the camera around the model, scroll to zoom. Two toggles under it: "half body behind wall" (a waist-high wall
-- in front of the model, flag Data.WallFlag or "EspPreviewWall") and "auto rotate" (flag Data.SpinFlag or "EspPreviewSpin").
-- Or Data.Flags = { Box = "MyBoxFlag", ... } and it follows those flags (Color3 or colorpicker flags). The model only turns while the preview is shown.
-- A zoom slider sits under the view (flag Data.ZoomFlag, default "EspPreviewZoom", saved with configs). Text is drawn like the ESP: flags, weapon, distance and the
-- health number in Arial, one size under the setting, with a black outline; the name in Code. Lines have an outline in OutlineColor.
local PREVIEW_BONES = {
	{ "Head", "UpperTorso" }, { "UpperTorso", "LowerTorso" },
	{ "UpperTorso", "LeftUpperArm" }, { "LeftUpperArm", "LeftLowerArm" }, { "LeftLowerArm", "LeftHand" },
	{ "UpperTorso", "RightUpperArm" }, { "RightUpperArm", "RightLowerArm" }, { "RightLowerArm", "RightHand" },
	{ "LowerTorso", "LeftUpperLeg" }, { "LeftUpperLeg", "LeftLowerLeg" }, { "LeftLowerLeg", "LeftFoot" },
	{ "LowerTorso", "RightUpperLeg" }, { "RightUpperLeg", "RightLowerLeg" }, { "RightLowerLeg", "RightFoot" },
}
function Library:EspPreview(Data)
	Data = Data or {}
	local fx = Library.fx
	-- Section:EspPreview(...) (or Data.Section): the preview is an element of that section, inside the menu. Library:EspPreview(...) floats.
	local host = (self ~= Library and type(self) == "table" and self.Items and self.Items["Content"]) and self or Library.field(Data, "Section", "section")
	local P = Build.EspPreview(host and host.Items["Content"].Instance or Library.Holder.Instance)
	local root = P.Root
	root.Name = "\0"
	if host then
		root.ZIndex = 1
		root.Size = UDim2.new(1, 0, 0, tonumber(Library.field(Data, "Height", "height")) or 330)
		root.BackgroundTransparency = 1
		local st = root:FindFirstChildOfClass("UIStroke")
		if st then st.Enabled = false end
		P.inner.Visible, P.line.Visible, P.title.Visible = false, false, false
		P.view.Position, P.view.Size = UDim2.new(0, 1, 0, 2), UDim2.new(1, -2, 1, -50)
		fx.shade(P.view, 0.35)
	else
		root.ZIndex = 1400
		root.Size = UDim2.fromOffset(320, 420)   -- room for the flags right of the box, the toggles and the zoom under the view
		P.view.Size = UDim2.new(1, -18, 1, -90)
		P.line.ZIndex = 3
		fx.shadow(root, { radius = 14, transparency = 0.1 })
		fx.shade(P.inner, 0.22)
	end
	P.title.Text = tostring(Library.field(Data, "Name", "name") or "esp preview")
	P.view.ClipsDescendants = true
	-- next to the first window when there is one
	local main = (not host) and Library.Windows[1] or nil
	if host then
		-- (inside the menu: nothing to place)
	elseif main then
		local r = main._W.Root
		root.AnchorPoint = Vector2.new(0, 0.5)
		root.Position = UDim2.new(r.Position.X.Scale, r.Position.X.Offset + r.Size.X.Offset / 2 + 10, r.Position.Y.Scale, r.Position.Y.Offset)
	else
		root.Position = UDim2.new(0.5, 330, 0.5, -165)
	end
	if not host then Library.MakeDraggable(P.title, root) end
	local white, black = Color3.new(1, 1, 1), Color3.new(0, 0, 0)
	local state = {
		Box = true, BoxColor = white, OutlineColor = black,
		Fill = false, FillColor1 = white, FillColor2 = white, FillTransparency1 = 0.5, FillTransparency2 = 1, FillSpin = false, Glow = false,
		Name = true, NameText = Players.LocalPlayer.Name, NameColor = white, NameSize = 13, NameOutline = true, NameOutlineColor = black,
		Distance = true, Weapon = true, WeaponText = tostring(Library.field(Data, "Weapon", "weapon") or "AK-47"), FlagSize = 12, FlagColor = Color3.fromRGB(235, 235, 235), FlagLines = {},
		Health = true, HealthPos = "Left", HealthGap = 2, HealthWidth = 2, HealthOutline = "Full", HealthOutlineColor = black, HealthGradient = false,
		HealthColor1 = Color3.fromRGB(0, 255, 0), HealthColor2 = Color3.fromRGB(255, 255, 0), HealthColor3 = Color3.fromRGB(255, 0, 0),
		HealthText = false, HealthTextFollow = false, HealthTextHideFull = false, HealthTextGradient = false, HealthTextSize = 9,
		Chams = false, ChamsColor = Library.Theme.Accent, ChamsStyle = "Flat", ChamsTransparency = 0, LiquidSpeed = 1, TestGlow = 1,
		ChamsWalls = true, ChamsOutline = false, ChamsOutlineColor = white, ChamsOutlineThickness = 0.12, ChamsOutlineWalls = true,
		ChamsVisCheck = false, ChamsVisibleColor = Color3.fromRGB(60, 255, 60), Wall = false, AutoRotate = true,
		Skeleton = false, HeadCircle = false, LookDir = false, LookCone = true, LookLength = 8, LineColor = white, Zoom = 1,
	}
	local ARIAL, CODE = Font.fromEnum(Enum.Font.Arial), Font.fromEnum(Enum.Font.Code)

	-- the model: a clone of your character in a ViewportFrame. A second ViewportFrame on top of it, with the same camera, is the "through walls"
	-- layer: what the real ESP draws AlwaysOnTop (the chams boxes, their outline, the Liquid shell) goes there and shows over the wall; the rest
	-- sits in the first one, where the wall hides it. Roblox draws no adornments or Highlights inside a ViewportFrame, so the chams are built from
	-- parts the way the in-game ones are laid out: one box per body part (its size, over the skin), thin boxes along its edges for the outline.
	local function viewport(z)
		local v = Instance.new("ViewportFrame")
		v.Name = "\0"
		v.BackgroundTransparency, v.BorderSizePixel = 1, 0
		v.Size = UDim2.fromScale(1, 1)
		v.Ambient, v.LightColor = Color3.fromRGB(150, 150, 150), white
		v.LightDirection = Vector3.new(-0.4, -1, -0.6)
		v.ZIndex = z
		v.Parent = P.view
		local c = Instance.new("Camera")
		c.FieldOfView = 40
		c.Parent = v
		v.CurrentCamera = c
		local w = Instance.new("WorldModel")
		w.Parent = v
		return v, c, w
	end
	local vp, cam, world = viewport(1)
	local vpTop, camTop, worldTop = viewport(2)
	local CHAM_PARTS = {
		"Head", "UpperTorso", "LowerTorso", "LeftUpperArm", "LeftLowerArm", "LeftHand", "RightUpperArm", "RightLowerArm", "RightHand",
		"LeftUpperLeg", "LeftLowerLeg", "LeftFoot", "RightUpperLeg", "RightLowerLeg", "RightFoot",
	}
	local FULL_EDGES = { Head = true, UpperTorso = true, LowerTorso = true }
	local chamsBase, chamsTop = Instance.new("Folder"), Instance.new("Folder")
	chamsBase.Parent, chamsTop.Parent = world, worldTop
	local model, parts, body, wall = nil, {}, {}, nil
	local chamSig, chamFills, chamLines, shells = nil, {}, {}, {}
	local glows, neonParts = {}, {}   -- the Test style: glow hint shells, the body parts turned Neon
	local shellOf = setmetatable({}, { __mode = "k" })   -- shell / glow copy -> the body part it covers
	local testSaved = { sas = {}, tex = {}, decals = {} }   -- what the Test style set aside on the clone (put back by restoreBody)
	local function buildModel()
		if model then model:Destroy() model, parts, body = nil, {}, {} end
		if wall then wall:Destroy() wall = nil end
		chamSig = nil
		local char = Players.LocalPlayer.Character
		if not char then return end
		local was = char.Archivable
		char.Archivable = true
		local ok, c = pcall(function() return char:Clone() end)
		char.Archivable = was
		if not (ok and c) then return end
		for _, d in c:GetDescendants() do
			if d:IsA("Script") or d:IsA("LocalScript") or d:IsA("ModuleScript") or d:IsA("Sound") then d:Destroy()
			elseif d:IsA("BasePart") then
				d.Anchored = true
				parts[#parts + 1] = { part = d, color = d.Color, mat = d.Material, trans = d.Transparency, refl = d.Reflectance }
			end
		end
		c:PivotTo(CFrame.new())
		c.Parent = world
		model = c
		for _, n in CHAM_PARTS do
			local p = c:FindFirstChild(n)
			if p and p:IsA("BasePart") then body[#body + 1] = p end
		end
		-- the half wall: across the front of the model (it faces -Z), from under the feet up to the waist
		local lo, hi = math.huge, -math.huge
		for _, p in body do
			lo, hi = math.min(lo, p.Position.Y - p.Size.Y / 2), math.max(hi, p.Position.Y + p.Size.Y / 2)
		end
		if lo < hi then
			local top = lo + (hi - lo) * 0.5
			wall = Instance.new("Part")
			wall.Name = "PreviewWall"
			wall.Anchored, wall.CanCollide, wall.CastShadow = true, false, false
			wall.Material, wall.Color = Enum.Material.Concrete, Color3.fromRGB(120, 116, 110)
			wall.TopSurface, wall.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth
			wall.Size = Vector3.new(6, top - lo + 0.5, 0.6)
			wall.CFrame = CFrame.new(0, (top + lo - 0.5) / 2, -2.4)
		end
	end
	local function clearChams()
		chamsBase:ClearAllChildren()
		chamsTop:ClearAllChildren()
		chamFills, chamLines, shells, glows, neonParts = {}, {}, {}, {}, {}
	end
	local function boxPart(size, cf, parent)
		local b = Instance.new("Part")
		b.Name = "Cham"
		b.Anchored, b.CanCollide, b.CanQuery, b.CastShadow = true, false, false, false
		b.Material = Enum.Material.SmoothPlastic
		b.TopSurface, b.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth
		b.Size, b.CFrame = size, cf
		b.Parent = parent
		return b
	end
	-- the outline of one part: thin boxes on its edges (all 12 for head / torso, the 4 long ones for limbs), like the in-game chams
	local function edges(p, thick, full, parent)
		local h = p.Size / 2
		local function corner(i)
			return Vector3.new(i % 2 == 0 and -h.X or h.X, math.floor(i / 2) % 2 == 0 and -h.Y or h.Y, math.floor(i / 4) % 2 == 0 and -h.Z or h.Z)
		end
		local axes = { 1, 2, 4 }
		if not full then
			local sz = p.Size
			axes = { sz.X >= sz.Y and (sz.X >= sz.Z and 1 or 4) or (sz.Y >= sz.Z and 2 or 4) }
		end
		for i = 0, 7 do
			for _, bit in axes do
				if math.floor(i / bit) % 2 == 0 then
					local a, b = corner(i), corner(i + bit)
					local d = b - a
					chamLines[#chamLines + 1] = boxPart(Vector3.new(math.abs(d.X) + thick, math.abs(d.Y) + thick, math.abs(d.Z) + thick), p.CFrame * CFrame.new((a + b) / 2), parent)
				end
			end
		end
	end
	local function restoreBody()
		for _, p in parts do
			p.part.Material, p.part.Color, p.part.Transparency, p.part.Reflectance = p.mat, p.color, p.trans, p.refl
		end
		for _, e in testSaved.sas do pcall(function() e[1].Parent = e[2] end) end
		for mp, tex in testSaved.tex do pcall(function() mp.TextureID = tex end) end
		for d, tr in testSaved.decals do pcall(function() d.Transparency = tr end) end
		testSaved = { sas = {}, tex = {}, decals = {} }
	end
	-- (re)built when a setting that changes their shape moves; their colours are set every frame (chamsFrame)
	local function paintChams()
		-- the wall is destroyed with the preview (unload / the window going away) while a script's Sync can still run: its Parent is locked then
		if wall and not pcall(function() wall.Parent = state.Wall and world or nil end) then wall = nil end
		local sig = table.concat({ tostring(state.Chams), tostring(state.ChamsStyle), tostring(state.ChamsWalls), tostring(state.ChamsOutline),
			tostring(state.ChamsOutlineThickness), tostring(state.ChamsOutlineWalls), tostring(state.ChamsTransparency), tostring(model),
			tostring(state.ChamsStyle == "Test" and state.Wall), tostring((tonumber(state.TestGlow) or 0) > 0) }, "|")
		if sig == chamSig then return end
		chamSig = sig
		clearChams()
		restoreBody()
		if not (state.Chams and model) then return end
		local fillTo = state.ChamsWalls and chamsTop or chamsBase
		-- a tinted copy of every body part, a little bigger (the shell the in-game Highlight stands for)
		local function makeShells(list, parent, scale, material)
			for _, p in body do
				local okS, sh = pcall(function() return p:Clone() end)
				if okS and sh then
					sh:ClearAllChildren()
					if sh:IsA("MeshPart") then pcall(function() sh.TextureID = "" end) end
					sh.Name = "ChamShell"
					sh.Material, sh.CastShadow = material or Enum.Material.SmoothPlastic, false
					sh.Size, sh.CFrame = p.Size * scale, p.CFrame
					sh.Parent = parent
					shellOf[sh] = p
					list[#list + 1] = sh
				end
			end
		end
		if state.ChamsStyle == "Liquid" then
			-- the body turns to tinted glass (the wave runs up it) and a shell around it stands for the Highlight
			local transp = math.clamp((tonumber(state.ChamsTransparency) or 0) * 0.7, 0, 0.9)
			for _, p in body do p.Material, p.Transparency = Enum.Material.Glass, transp end
			makeShells(shells, fillTo, 1.05)
			return
		end
		if state.ChamsStyle == "Test" then
			-- like the in-game Test chams: every visible part of the body is Neon (what hides the material, the SurfaceAppearance, the mesh
			-- texture and decals, is set aside until the next rebuild; weapons are left alone). Every frame (chamsFrame): while any body part is
			-- behind something (a ray from the camera) the smooth liquid shell covers the body (like the in-game Highlight); the Neon parts carry
			-- a bigger Neon copy that hints at the bloom (a viewport has none)
			for _, p in parts do
				local part = p.part
				if part.Transparency < 0.95 and part.Name ~= "HumanoidRootPart" and not part:FindFirstAncestor("WeaponModel") and not part:FindFirstAncestor("WeaponAttachments") then
					for _, k in part:GetChildren() do
						if k:IsA("SurfaceAppearance") then
							testSaved.sas[#testSaved.sas + 1] = { k, part }
							k.Parent = nil
						elseif (k:IsA("Decal") or k:IsA("Texture")) and k.Transparency < 1 then
							testSaved.decals[k] = k.Transparency
							k.Transparency = 1
						end
					end
					if part:IsA("MeshPart") and part.TextureID ~= "" then
						testSaved.tex[part] = part.TextureID
						part.TextureID = ""
					end
					part.Material = Enum.Material.Neon
					neonParts[#neonParts + 1] = part
				end
			end
			if (tonumber(state.TestGlow) or 0) > 0 then makeShells(glows, chamsBase, 1.1, Enum.Material.Neon) end
			if state.ChamsWalls then makeShells(shells, chamsTop, 1.05) end
			return
		end
		for _, p in body do chamFills[#chamFills + 1] = boxPart(p.Size, p.CFrame, fillTo) end
		if state.ChamsOutline then
			local thick = math.clamp(tonumber(state.ChamsOutlineThickness) or 0.12, 0.02, 1)
			local lineTo = state.ChamsOutlineWalls and chamsTop or chamsBase
			for _, p in body do edges(p, thick, FULL_EDGES[p.Name] == true, lineTo) end
		end
	end

	-- the overlay (the box is a fixed frame around where the turning model stands)
	local overlay = Instance.new("Frame")
	overlay.Name = "\0"
	overlay.BackgroundTransparency = 1
	overlay.Size = UDim2.fromScale(1, 1)
	overlay.ZIndex = 5
	overlay.Parent = P.view
	local box = Instance.new("Frame")
	box.Name = "\0"
	box.BackgroundTransparency = 1
	box.Position, box.Size = UDim2.fromScale(0.35, 0.15), UDim2.fromOffset(100, 200)   -- (fitted to the model every frame)
	box.Parent = overlay
	local fill = Instance.new("Frame")
	fill.Name = "\0"
	fill.BorderSizePixel = 0
	fill.BackgroundColor3 = white
	fill.Size = UDim2.fromScale(1, 1)
	fill.Parent = box
	local fillGrad = Instance.new("UIGradient", fill)
	local glow = fx.shadow(box, { force = true, glow = true, radius = 10, transparency = 0.45, color = white })
	local boxStroke = Instance.new("UIStroke", box)
	boxStroke.Thickness = 1
	local boxOuter = Instance.new("Frame")
	boxOuter.Name = "\0"
	boxOuter.BackgroundTransparency = 1
	boxOuter.AnchorPoint, boxOuter.Position, boxOuter.Size = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5), UDim2.new(1, 2, 1, 2)
	boxOuter.Parent = box
	local outer = Instance.new("UIStroke", boxOuter)
	outer.Thickness = 1
	local function text(size)
		local t = Instance.new("TextLabel")
		t.Name = "\0"
		t.BackgroundTransparency = 1
		t.FontFace, t.TextSize = ARIAL, size or 12
		t.TextColor3 = white
		t.TextStrokeTransparency = 1   -- outlined like the game ESP: a 1 px stroke
		local st = Instance.new("UIStroke")
		st.Name, st.Thickness, st.Color, st.LineJoinMode = "\0Outline", 1, black, Enum.LineJoinMode.Miter
		st.Parent = t
		t.Size = UDim2.fromOffset(160, size or 12)
		t.ZIndex = 3
		t.Parent = box
		return t
	end
	local nameT, weapT, distT, hpT = text(13), text(12), text(12), text(9)
	nameT.FontFace = CODE
	nameT.AnchorPoint, weapT.AnchorPoint, distT.AnchorPoint = Vector2.new(0.5, 1), Vector2.new(0.5, 1), Vector2.new(0.5, 0)
	local hpBack = Instance.new("Frame")
	hpBack.Name = "\0"
	hpBack.BorderSizePixel = 0
	hpBack.Parent = box
	local hpFill = Instance.new("Frame")
	hpFill.Name = "\0"
	hpFill.BorderSizePixel = 0
	hpFill.Parent = hpBack
	local flagRows = {}

	-- skeleton, head circle, look line: projected from the model each frame
	local lines = Instance.new("Frame")
	lines.Name = "\0"
	lines.BackgroundTransparency = 1
	lines.Size = UDim2.fromScale(1, 1)
	lines.ZIndex = 4
	lines.Parent = overlay
	local function line(z)
		local l = Instance.new("Frame")
		l.Name = "\0"
		l.BorderSizePixel = 0
		l.AnchorPoint = Vector2.new(0.5, 0.5)
		l.Visible = false
		l.ZIndex = z or 2
		l.Parent = lines
		return l
	end
	local bones, boneEdges = {}, {}
	for i = 1, #PREVIEW_BONES do bones[i], boneEdges[i] = line(), line(1) end
	local lookLine, lookEdge, lookTip = line(), line(1), line()
	lookTip.Rotation = 45
	local function ring(z, thick)
		local f = line(z)
		f.BackgroundTransparency = 1
		Instance.new("UICorner", f).CornerRadius = UDim.new(1, 0)
		local st = Instance.new("UIStroke", f)
		st.Thickness = thick
		return f, st
	end
	local headRing, ringStroke = ring(2, 1)
	local headEdge, edgeStroke = ring(1, 3)
	local function project(pos)
		local o = cam.CFrame:PointToObjectSpace(pos)
		if o.Z >= -0.1 then return nil end
		local size = P.view.AbsoluteSize
		local t = math.tan(math.rad(cam.FieldOfView / 2))
		return Vector2.new((0.5 + o.X / (-o.Z * t * (size.X / math.max(size.Y, 1))) / 2) * size.X, (0.5 - o.Y / (-o.Z * t) / 2) * size.Y), o.Z
	end
	local function place(l, a, b, thick)
		local d, m = b - a, (a + b) / 2
		l.Position, l.Size, l.Rotation = UDim2.fromOffset(m.X, m.Y), UDim2.fromOffset(d.Magnitude + (thick or 1), thick or 1), math.deg(math.atan2(d.Y, d.X))
		l.Visible = true
	end
	local function hpColor(hp)
		if hp > 0.5 then return state.HealthColor2:Lerp(state.HealthColor1, (hp - 0.5) * 2) end
		return state.HealthColor3:Lerp(state.HealthColor2, hp * 2)
	end

	local function paint()
		local cornered = state.BoxStyle == "2D Cornered"
		boxStroke.Enabled, outer.Enabled = state.Box and not cornered, state.Box and not cornered
		boxStroke.Color, outer.Color = state.BoxColor, state.OutlineColor
		fill.Visible = state.Box and state.Fill
		fillGrad.Color = ColorSequence.new(state.FillColor1, state.FillColor2)
		fillGrad.Transparency = NumberSequence.new(math.clamp(state.FillTransparency1, 0, 1), math.clamp(state.FillTransparency2, 0, 1))
		glow.Visible = state.Box and state.Glow
		glow.ImageColor3 = state.BoxColor
		-- above the box: the weapon, then the name; a Top bar pushes them up
		local width = math.max(math.floor(state.HealthWidth), 1)
		local gap = math.max(math.floor(state.HealthGap), 0)
		local side = state.Health and state.HealthPos or nil
		local y = -2 - (side == "Top" and width + gap + 2 or 0)
		weapT.Visible = state.Weapon
		if state.Font then for _, t in { nameT, weapT, distT, hpT } do t.FontFace = state.Font end end
		weapT.Text, weapT.TextSize, weapT.TextColor3 = tostring(state.WeaponText), state.FlagSize, state.FlagColor
		weapT.Size = UDim2.fromOffset(160, state.FlagSize)
		weapT.Position = UDim2.new(0.5, 0, 0, y)
		if state.Weapon then y -= state.FlagSize + 1 end
		nameT.Visible = state.Name
		nameT.Text, nameT.TextSize, nameT.TextColor3 = tostring(state.NameText), state.NameSize, state.NameColor
		nameT.Size = UDim2.fromOffset(160, state.NameSize)
		local nst = nameT:FindFirstChild("\0Outline")
		if nst then nst.Enabled, nst.Color = state.NameOutline ~= false, state.NameOutlineColor or black end
		nameT.Position = UDim2.new(0.5, 0, 0, y)
		distT.Visible = state.Distance
		distT.Text, distT.TextSize, distT.TextColor3 = "[2m]", state.FlagSize, white
		distT.Position = UDim2.new(0.5, 0, 1, 2 + (side == "Bottom" and width + gap + 2 or 0))
		-- the flags, right of the box (past a Right bar)
		local fx0 = 3 + (side == "Right" and width + gap + 4 + (state.HealthText and 18 or 0) or 0)
		for i, ln in state.FlagLines do
			local r = flagRows[i]
			if not r then
				r = text(12)
				r.TextXAlignment = Enum.TextXAlignment.Left
				flagRows[i] = r
			end
			r.Visible = true
			r.Text, r.TextSize, r.TextColor3 = tostring(ln.text), state.FlagSize, ln.col or state.FlagColor
			if state.Font then r.FontFace = state.Font end
			r.Size = UDim2.fromOffset(120, state.FlagSize)
			r.Position = UDim2.new(1, fx0, 0, 1 + (i - 1) * (state.FlagSize + 1))
		end
		for i = #state.FlagLines + 1, #flagRows do flagRows[i].Visible = false end
		hpBack.BackgroundColor3 = state.HealthOutlineColor
		hpBack.BackgroundTransparency = state.HealthOutline == "None" and 1 or 0
		hpBack.Visible = state.Health
		hpT.TextSize = state.HealthTextSize
		hpT.Size = UDim2.fromOffset(30, state.HealthTextSize)
		ringStroke.Color, edgeStroke.Color = state.LineColor, state.OutlineColor
		for i, l in bones do l.BackgroundColor3, boneEdges[i].BackgroundColor3 = state.LineColor, state.OutlineColor end
		lookLine.BackgroundColor3, lookTip.BackgroundColor3, lookEdge.BackgroundColor3 = state.LineColor, state.LineColor, state.OutlineColor
		paintChams()
	end
	local function layoutHealth(hp)
		if not state.Health then hpT.Visible = false return end
		local w = math.max(math.floor(state.HealthWidth), 1)
		local g = math.max(math.floor(state.HealthGap), 0)
		local pos, fit = state.HealthPos, state.HealthOutline == "Fit"
		local horizontal = pos == "Top" or pos == "Bottom"
		if horizontal then
			hpBack.AnchorPoint = Vector2.new(0, pos == "Top" and 1 or 0)
			hpBack.Position = UDim2.new(0, -1, pos == "Top" and 0 or 1, pos == "Top" and -g - 1 or g + 1)
			hpBack.Size = fit and UDim2.new(hp, 2, 0, w + 2) or UDim2.new(1, 2, 0, w + 2)
			hpFill.AnchorPoint, hpFill.Position = Vector2.zero, UDim2.fromOffset(1, 1)
			hpFill.Size = fit and UDim2.new(1, -2, 1, -2) or UDim2.new(hp, -2, 1, -2)
		else
			hpBack.AnchorPoint = Vector2.new(pos == "Right" and 0 or 1, fit and 1 or 0)
			hpBack.Position = UDim2.new(pos == "Right" and 1 or 0, pos == "Right" and g + 1 or -g - 1, fit and 1 or 0, fit and 1 or -1)
			hpBack.Size = fit and UDim2.new(0, w + 2, hp, 2) or UDim2.new(0, w + 2, 1, 2)
			hpFill.AnchorPoint, hpFill.Position = Vector2.new(0, 1), UDim2.new(0, 1, 1, -1)
			hpFill.Size = fit and UDim2.new(1, -2, 1, -2) or UDim2.new(1, -2, hp, -2)
		end
		local col = hpColor(hp)
		hpFill.BackgroundColor3 = col
		local showText = state.HealthText and not (state.HealthTextHideFull and hp >= 0.995)
		hpT.Visible = showText
		if showText then
			hpT.Text = tostring(math.floor(hp * 100))
			hpT.TextColor3 = state.HealthTextGradient and col or white
			local along = state.HealthTextFollow and (horizontal and hp or 1 - hp) or 0
			if horizontal then
				hpT.AnchorPoint = Vector2.new(0.5, pos == "Top" and 1 or 0)
				hpT.Position = UDim2.new(along, 0, pos == "Top" and 0 or 1, pos == "Top" and -g - w - 3 or g + w + 3)
			elseif pos == "Right" then
				hpT.AnchorPoint = Vector2.new(0, 0.5)
				hpT.Position = UDim2.new(1, g + w + 4, along, 0)
			else
				hpT.AnchorPoint = Vector2.new(1, 0.5)
				hpT.Position = UDim2.new(0, -g - w - 4, along, 0)
			end
		end
	end
	local preview = { Instance = root, State = state }
	function preview:Set(key, value) state[key] = value paint() end
	function preview:Sync(values)
		for k, v in values do state[k] = v end
		paint()
	end
	function preview:SetVisibility(b) root.Visible = b end
	function preview:Refresh() buildModel() paint() end
	-- the zoom slider under the view
	local zoomSet
	do
		local MIN, MAX = 0.6, 2.5
		local row = Instance.new("Frame")
		row.Name = "\0"
		row.BackgroundTransparency, row.BorderSizePixel = 1, 0
		row.AnchorPoint, row.Position, row.Size = Vector2.new(0, 1), UDim2.new(0, host and 2 or 9, 1, host and -3 or -9), UDim2.new(1, host and -4 or -18, 0, 16)
		row.Parent = root
		local function small(txt, x, align, width)
			local t = Instance.new("TextLabel")
			t.Name = "\0"
			t.BackgroundTransparency = 1
			t.FontFace, t.TextSize, t.Text = Library.Font, 12, txt
			t.TextColor3, t.TextXAlignment = Library.Theme["Dim Text"], align
			t.AnchorPoint, t.Position, t.Size = Vector2.new(x, 0), UDim2.fromScale(x, 0), UDim2.new(0, width, 1, 0)
			Library:AddToTheme(t, { TextColor3 = "Dim Text" })
			t.Parent = row
			return t
		end
		small("zoom", 0, Enum.TextXAlignment.Left, 36)
		local value = small("1.0x", 1, Enum.TextXAlignment.Right, 36)
		local track = Instance.new("Frame")
		track.Name = "\0"
		track.BorderSizePixel = 0
		track.BackgroundColor3 = Library.Theme.Inline
		Library:AddToTheme(track, { BackgroundColor3 = "Inline" })
		track.Position, track.Size = UDim2.fromOffset(40, 4), UDim2.new(1, -80, 0, 8)
		track.Parent = row
		local trackStroke = Instance.new("UIStroke", track)
		trackStroke.Color = Library.Theme.Outline
		Library:AddToTheme(trackStroke, { Color = "Outline" })
		local fill = Instance.new("Frame")
		fill.Name = "\0"
		fill.BorderSizePixel = 0
		fill.BackgroundColor3 = Library.Theme.Accent
		Library:AddToTheme(fill, { BackgroundColor3 = "Accent" })
		fill.Parent = track
		local flag = tostring(Library.field(Data, "ZoomFlag", "zoomflag") or "EspPreviewZoom")
		local function setZoom(v)
			v = tonumber(v)
			if not v then return end
			v = math.clamp(Library:Round(v, 0.05), MIN, MAX)
			state.Zoom = v
			Library.Flags[flag] = v
			fill.Size = UDim2.new((v - MIN) / (MAX - MIN), 0, 1, 0)
			value.Text = string.format("%.2gx", v)
		end
		Library.SetFlags[flag] = setZoom
		zoomSet = setZoom
		setZoom(host and 0.8 or 1)
		local hit = Library.click(track)
		hit.Size, hit.Position = UDim2.new(1, 0, 1, 8), UDim2.fromOffset(0, -4)
		local drag = false
		local function at(x) setZoom(MIN + (MAX - MIN) * math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)) end
		Library:Connect(hit.InputBegan, function(i) if (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then drag = true at(i.Position.X) end end)
		Library:Connect(UserInputService.InputChanged, function(i) if drag and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then at(i.Position.X) end end)
		Library:Connect(UserInputService.InputEnded, function(i) if (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then drag = false end end)
	end
	-- two toggles over the zoom row (the design sheet's Toggle): the half wall and the auto turn, saved with configs
	do
		local row = Instance.new("Frame")
		row.Name = "\0"
		row.BackgroundTransparency, row.BorderSizePixel = 1, 0
		row.AnchorPoint, row.Position, row.Size = Vector2.new(0, 1), UDim2.new(0, host and 2 or 9, 1, host and -24 or -31), UDim2.new(1, host and -4 or -18, 0, 19)
		row.Parent = root
		local function mini(name, flag, key, default, x)
			local T = Build.Toggle(row)
			T.Root.Position, T.Root.Size = UDim2.new(x, 0, 0, 0), UDim2.new(0.5, -4, 0, 18)
			T.label.Text = name
			T.label.Position, T.label.Size = UDim2.new(0, 19, 0, 0), UDim2.new(1, -19, 1, 0)
			T.label.TextTruncate = Enum.TextTruncate.AtEnd
			T.check.AnchorPoint, T.check.Position, T.check.Size = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5), UDim2.fromScale(1, 1)
			local value
			local function set(v)
				value = v and true or false
				Library.Flags[flag] = value
				Library:ChangeItemTheme(T.box, { BackgroundColor3 = value and "Accent" or "Inline" })
				fx.tween(T.box, { BackgroundColor3 = value and Library.Theme.Accent or Library.Theme.Inline }, 0.14)
				fx.tween(T.check, { BackgroundTransparency = value and 0 or 1 }, 0.14)
				Library.themed(T.label, "TextColor3", value and "Accent" or "Dim Text")
				state[key] = value
				paint()
			end
			Library.SetFlags[flag] = set
			Library.click(T.Root, function() set(not value) end)
			set(default)
		end
		mini("behind wall", tostring(Library.field(Data, "WallFlag", "wallflag") or "EspPreviewWall"), "Wall", false, 0)
		mini("auto rotate", tostring(Library.field(Data, "SpinFlag", "spinflag") or "EspPreviewSpin"), "AutoRotate", true, 0.5)
	end
	-- the camera: drag in the view to turn around the model, the wheel zooms
	local yaw, pitch, dragging, lastPos = math.pi, 0.05, false, nil
	do
		local hit = Instance.new("TextButton")
		hit.Name = "\0"
		hit.Text, hit.AutoButtonColor = "", false
		hit.BackgroundTransparency = 1
		hit.Size = UDim2.fromScale(1, 1)
		hit.ZIndex = 20
		hit.Parent = P.view
		local MB1, TOUCH = Enum.UserInputType.MouseButton1, Enum.UserInputType.Touch
		Library:Connect(hit.InputBegan, function(i)
			if i.UserInputType == MB1 or i.UserInputType == TOUCH then dragging, lastPos = true, i.Position end
		end)
		Library:Connect(UserInputService.InputChanged, function(i)
			if dragging and lastPos and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == TOUCH) then
				local d = i.Position - lastPos
				lastPos = i.Position
				yaw -= d.X * 0.012
				pitch = math.clamp(pitch + d.Y * 0.01, -1.2, 1.2)
			end
		end)
		Library:Connect(UserInputService.InputEnded, function(i)
			if i.UserInputType == MB1 or i.UserInputType == TOUCH then dragging = false end
		end)
		Library:Connect(hit.InputEnded, function(i)
			if i.UserInputType == MB1 or i.UserInputType == TOUCH then dragging = false end
		end)
		Library:Connect(hit.InputChanged, function(i)
			if i.UserInputType == Enum.UserInputType.MouseWheel and zoomSet then zoomSet(state.Zoom + i.Position.Z * 0.1) end
		end)
	end
	-- the chams' colours: the visible colour when the camera sees the head or chest (a ray in the preview world, the wall stops it)
	local rayParams = RaycastParams.new()
	rayParams.FilterType = Enum.RaycastFilterType.Exclude
	function preview:Camera() return yaw, pitch, dragging end
	local function seenNow()
		if not model then return false end
		rayParams.FilterDescendantsInstances = { model, chamsBase }
		local from = cam.CFrame.Position
		for _, n in { "Head", "UpperTorso" } do
			local p = model:FindFirstChild(n)
			if p and not world:Raycast(from, p.Position - from, rayParams) then return true end
		end
		return false
	end
	local function chamsFrame(t)
		if not (state.Chams and model) then return end
		if state.ChamsStyle == "Test" then
			local col = state.ChamsColor
			local ts = t * (tonumber(state.LiquidSpeed) or 1)
			-- (the in-game neon is lightened to clear the bloom threshold; a viewport has no bloom, so here it is barely lightened)
			local neonCol = col:Lerp(white, 0.12)
			for _, part in neonParts do if part.Color ~= neonCol then part.Color = neonCol end end
			-- is any body part behind something right now? (only the wall can be: the model's own parts and the chams are filtered out)
			rayParams.FilterDescendantsInstances = { model, chamsBase }
			local from = cam.CFrame.Position
			local anyHidden = false
			if state.ChamsWalls then
				for _, p in body do
					if world:Raycast(from, p.Position - from, rayParams) then anyHidden = true break end
				end
			end
			-- the glow hint: a bigger Neon copy around every part, as strong as the Test Glow slider says (0 = none, like in game)
			local glowTr = math.clamp(0.85 - 0.2 * (tonumber(state.TestGlow) or 0), 0.3, 0.95)
			local glowCol = col:Lerp(white, 0.35)
			for _, g in glows do g.Color, g.Transparency = glowCol, glowTr end
			-- like in game the smooth shell covers the whole body while any part is hidden; its fill is light, the neon stays bright under it
			local fillC = col:Lerp(white, 0.25 + 0.12 * math.sin(ts * 1.6))
			local ft = math.clamp(0.62 + (tonumber(state.ChamsTransparency) or 0) * 0.35 + 0.08 * math.sin(ts * 1.3), 0, 1)
			for _, sh in shells do
				if anyHidden then sh.Color, sh.Transparency = fillC, ft else sh.Transparency = 1 end
			end
			return
		end
		local col, lineCol = state.ChamsColor, state.ChamsOutlineColor
		if state.ChamsVisCheck and seenNow() then
			if state.ChamsOutline and state.ChamsStyle ~= "Liquid" then lineCol = state.ChamsVisibleColor else col = state.ChamsVisibleColor end
		end
		if state.ChamsStyle == "Liquid" then
			local ts = t * (tonumber(state.LiquidSpeed) or 1)
			for _, p in body do
				local wave = 0.5 + 0.5 * math.sin(ts * 3 - p.Position.Y * 2.4)
				p.Color = col:Lerp(white, 0.18 + 0.5 * wave * wave)
				p.Reflectance = 0.15 + 0.35 * wave
			end
			local fillC = col:Lerp(white, 0.2 + 0.12 * math.sin(ts * 1.6))
			local ft = math.clamp(0.62 + 0.12 * math.sin(ts * 1.3) + (tonumber(state.ChamsTransparency) or 0) * 0.2, 0, 1)
			for _, sh in shells do sh.Color, sh.Transparency = fillC, ft end
			return
		end
		local tr = math.clamp(tonumber(state.ChamsTransparency) or 0, 0, 1)
		for _, b in chamFills do b.Color, b.Transparency = col, tr end
		for _, l in chamLines do l.Color = lineCol end
	end
	-- the ESP box: around the body parts' corners as the camera sees them
	-- Box Style "2D Cornered": 8 arms (1 px line over a 3 px outline) at the corners of the box
	local cornerArms
	local function placeCorners(w, h)
		local on = state.Box and state.BoxStyle == "2D Cornered"
		if not cornerArms then
			if not on then return end
			cornerArms = {}
			for i = 1, 8 do
				local o = Instance.new("Frame") o.Name, o.BorderSizePixel, o.ZIndex = "\0", 0, 2 o.Parent = box
				local l = Instance.new("Frame") l.Name, l.BorderSizePixel, l.ZIndex = "\0", 0, 3 l.Parent = box
				cornerArms[i] = { out = o, line = l }
			end
		end
		local L = math.max(math.floor(math.min(w, h) * 0.25), 3)
		local rects = { { 0, 0, L, 1 }, { 0, 0, 1, L }, { w - L, 0, L, 1 }, { w - 1, 0, 1, L },
			{ 0, h - 1, L, 1 }, { 0, h - L, 1, L }, { w - L, h - 1, L, 1 }, { w - 1, h - L, 1, L } }
		for i, a in cornerArms do
			local r = rects[i]
			a.out.Visible, a.line.Visible = on, on
			a.line.Position, a.line.Size = UDim2.fromOffset(r[1], r[2]), UDim2.fromOffset(r[3], r[4])
			a.out.Position, a.out.Size = UDim2.fromOffset(r[1] - 1, r[2] - 1), UDim2.fromOffset(r[3] + 2, r[4] + 2)
			a.line.BackgroundColor3, a.out.BackgroundColor3 = state.BoxColor, state.OutlineColor
		end
	end
	-- the box the game ESP draws (BloxStrike Otterhook): height = head top -> feet straight through the root, width = a root-space box
	-- (X +-1.2, Z +-0.5) projected; Static = 0.55 x the height. Without a root: the bounds of the body parts.
	local function fitBox()
		local root = model and model:FindFirstChild("HumanoidRootPart")
		local x0, y0, x1, y1 = math.huge, math.huge, -math.huge, -math.huge
		if root then
			local rcf, head = root.CFrame, model:FindFirstChild("Head")
			local top = head and (rcf:PointToObjectSpace(head.Position).Y + head.Size.Y * 0.5 + 0.1) or 2.4
			for _, cy in { -3.1, top } do
				for _, cx in { -1.2, 1.2 } do
					for _, cz in { -0.5, 0.5 } do
						local sp = project(rcf * Vector3.new(cx, cy, cz))
						if sp then x0, x1 = math.min(x0, sp.X), math.max(x1, sp.X) end
					end
				end
			end
			local s1, s2 = project(rcf.Position + Vector3.new(0, top, 0)), project(rcf.Position - Vector3.new(0, 3.1, 0))
			if s1 and s2 and s2.Y > s1.Y then
				y0, y1 = s1.Y, s2.Y
				if state.BoxStyle == "2D Static" then
					local mid, half = project(rcf.Position), (s2.Y - s1.Y) * 0.55 / 2
					if mid then x0, x1 = mid.X - half, mid.X + half end
				end
			end
		else
			for _, p in body do
				local cf, h = p.CFrame, p.Size / 2
				for i = 0, 7 do
					local sp = project(cf * Vector3.new(i % 2 == 0 and -h.X or h.X, math.floor(i / 2) % 2 == 0 and -h.Y or h.Y, math.floor(i / 4) % 2 == 0 and -h.Z or h.Z))
					if sp then x0, y0, x1, y1 = math.min(x0, sp.X), math.min(y0, sp.Y), math.max(x1, sp.X), math.max(y1, sp.Y) end
				end
			end
		end
		if x0 < x1 and y0 < y1 then
			local w, h = math.max(math.floor(x1 - x0), 2), math.max(math.floor(y1 - y0), 2)
			box.Position = UDim2.fromOffset(math.floor(x0), math.floor(y0))
			box.Size = UDim2.fromOffset(w, h)
			placeCorners(w, h)
		end
	end
	buildModel()
	paint()
	-- the health bar sweeps 100 -> 25 -> 100 so it shows how it moves
	local t0 = os.clock()
	Library:Connect(RunService.RenderStepped, function(dt)
		if not (root.Visible and root.Parent) then return end
		local t = os.clock() - t0
		-- a release the view did not see (outside the window, a menu on top) must not leave the drag on
		if dragging and not (UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) or UserInputService.TouchEnabled) then dragging = false end
		if state.AutoRotate and not dragging then yaw += dt * 0.6 end
		local target = Vector3.new(0, 0.2, 0)
		local orbit = CFrame.new(target) * CFrame.Angles(0, yaw, 0) * CFrame.Angles(-pitch, 0, 0) * CFrame.new(0, 0, 11 / state.Zoom)
		cam.CFrame = CFrame.lookAt(orbit.Position, target)
		camTop.CFrame = cam.CFrame
		chamsFrame(t)
		fitBox()
		local hp = 0.625 + 0.375 * math.cos(t * 0.8)
		layoutHealth(hp)
		if state.Fill and state.FillSpin then fillGrad.Rotation = (fillGrad.Rotation + dt * 40) % 360 end
		local function at(name)
			local part = model and model:FindFirstChild(name)
			return part and part:IsA("BasePart") and part or nil
		end
		for i, pair in PREVIEW_BONES do
			local a, b = at(pair[1]), at(pair[2])
			local pa, pb = a and project(a.Position), b and project(b.Position)
			if state.Skeleton and pa and pb then
				place(boneEdges[i], pa, pb, 3)
				place(bones[i], pa, pb, 1)
			else
				bones[i].Visible, boneEdges[i].Visible = false, false
			end
		end
		local head = at("Head")
		local ph = head and project(head.Position)
		if state.HeadCircle and ph then
			local _, z = project(head.Position)
			local r = head.Size.Y * 0.6 / (-z * math.tan(math.rad(cam.FieldOfView / 2))) * P.view.AbsoluteSize.Y / 2
			headRing.Position, headRing.Size, headRing.Rotation = UDim2.fromOffset(ph.X, ph.Y), UDim2.fromOffset(r * 2, r * 2), 0
			headEdge.Position, headEdge.Size, headEdge.Rotation = headRing.Position, headRing.Size, 0
			headRing.Visible, headEdge.Visible = true, true
		else
			headRing.Visible, headEdge.Visible = false, false
		end
		local tip = head and project(head.Position + head.CFrame.LookVector * state.LookLength)
		if state.LookDir and ph and tip then
			place(lookEdge, ph, tip, 3)
			place(lookLine, ph, tip, 1)
			lookTip.Visible = state.LookCone
			lookTip.Position, lookTip.Size = UDim2.fromOffset(tip.X, tip.Y), UDim2.fromOffset(6, 6)
		else
			lookLine.Visible, lookEdge.Visible, lookTip.Visible = false, false, false
		end
	end)
	-- following flags
	local map = Library.field(Data, "Flags", "flags")
	if type(map) == "table" then
		task.spawn(function()
			while Library.Alive and root.Parent do
				local changed = false
				for key, flag in map do
					local v = Library.Flags[flag]
					if type(v) == "table" and typeof(v.Color) == "Color3" then v = v.Color end
					if v ~= nil and state[key] ~= v then state[key] = v changed = true end
				end
				if changed then paint() end
				task.wait(0.15)
			end
		end)
	end
	-- a respawn changes the look: rebuild the model
	Library:Connect(Players.LocalPlayer.CharacterAdded, function() task.wait(1) if root.Parent then buildModel() paint() end end)
	-- open / close with the menu
	if main and not host then
		local prev = main.OnOpen
		table.insert(main.FadeWith, root)
		main.OnOpen = function(b)
			if prev then prev(b) end
			if b then root.Visible = preview.Shown ~= false return end
			-- closing: it fades out with the window, then hides
			if not (Library.Animations and Library.SmoothOpen) then root.Visible = false return end
			task.delay(0.16, function() if not main.IsOpen then root.Visible = false end end)
		end
	end
	function preview:SetShown(b) preview.Shown = b root.Visible = b and (host ~= nil or not main or main.IsOpen) end
	return preview
end

-- ---- Section:PartPicker(Data) -> picker ----
-- A clickable R6 body: Head, Torso, Left Arm, Right Arm, Left Leg, Right Leg. Multi (default) keeps a list, single one name.
-- Data: Name, Flag, Default (a name or a list), Multi, Callback(value).
-- Data.Priority = true: each click moves a part on (off -> 1st -> 2nd -> 3rd -> off), the colour shows which, a legend sits bottom right, and the value is a map
-- { Head = 1, Torso = 2 }. A plain list (an older config) also loads: every part in it is 1st priority.
local R6 = {
	{ "Head", 0.5, 0.02, 0.2, 0.17 },
	{ "Torso", 0.5, 0.21, 0.32, 0.36 },
	{ "Left Arm", 0.25, 0.21, 0.15, 0.36 },
	{ "Right Arm", 0.75, 0.21, 0.15, 0.36 },
	{ "Left Leg", 0.415, 0.59, 0.15, 0.38 },
	{ "Right Leg", 0.585, 0.59, 0.15, 0.38 },
}
function Library:PartPicker(Data)
	Data = Data or {}
	local section = self
	local fx = Library.fx
	local flag = Library.field(Data, "Flag", "flag") or Library:NextFlag()
	local multi = Library.field(Data, "Multi", "multi") ~= false
	local priority = Library.field(Data, "Priority", "priority") == true
	local callback = Library.field(Data, "Callback", "callback")
	local LEVEL = { "Accent", "Priority 2", "Priority 3" }
	if priority then
		Library.Theme["Priority 2"] = Library.Theme["Priority 2"] or Color3.fromRGB(240, 140, 45)
		Library.Theme["Priority 3"] = Library.Theme["Priority 3"] or Color3.fromRGB(225, 205, 70)
	end
	local T = Build.PartPicker(section.Items["Content"].Instance)
	T.Root.Size = UDim2.new(1, 0, 0, 150)
	local name = tostring(Library.field(Data, "Name", "name") or "")
	T.label.Text = name
	Library.regSearch(section, T.Root, name)
	T.figure.Size = UDim2.new(1, -20, 0, 128)
	-- the body keeps the proportions of an R6 character, centred in the box
	local body = Instance.new("Frame")
	body.Name = "\0"
	body.BackgroundTransparency = 1
	body.AnchorPoint, body.Position, body.Size = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5), UDim2.new(0, 100, 0, 118)
	body.Parent = T.figure
	local picker = { Flag = flag, Value = (multi or priority) and {} or nil, Items = { Picker = Library.Wrap(T.Root) }, Section = section }
	local blocks = {}
	local function isOn(n)
		if priority then return picker.Value[n] ~= nil end
		if multi then return table.find(picker.Value, n) ~= nil end
		return picker.Value == n
	end
	local function paint()
		for n, b in blocks do
			local on = isOn(n)
			local key = on and (priority and LEVEL[picker.Value[n]] or "Accent") or "Inline"
			Library:ChangeItemTheme(b, { BackgroundColor3 = key })
			fx.tween(b, { BackgroundColor3 = Library.Theme[key] }, 0.15)
		end
	end
	local function fire()
		Library.Flags[flag] = picker.Value
		if callback then Library:SafeCall(callback, picker.Value) end
	end
	local function set(v)
		if priority then
			if type(v) == "string" then v = { v } end
			if type(v) ~= "table" then return end
			local out = {}
			if #v > 0 then
				for _, n in ipairs(v) do if type(n) == "string" then out[n] = 1 end end
			else
				for n, level in pairs(v) do
					if type(n) == "string" and tonumber(level) then out[n] = math.clamp(math.floor(tonumber(level)), 1, 3) end
				end
			end
			picker.Value = out
		elseif multi then
			if type(v) == "string" then v = { v } end
			if type(v) ~= "table" then return end
			picker.Value = table.clone(v)
		else
			picker.Value = type(v) == "string" and v or nil
		end
		paint()
		fire()
	end
	for _, d in R6 do
		local n = d[1]
		local b = Instance.new("Frame")
		b.Name = n
		b.BorderSizePixel = 0
		b.AnchorPoint = Vector2.new(0.5, 0)
		b.Position, b.Size = UDim2.fromScale(d[2], d[3]), UDim2.fromScale(d[4], d[5])
		b.BackgroundColor3 = Library.Theme.Inline
		b.Parent = body
		local st = Instance.new("UIStroke", b)
		st.Color = Library.Theme.Outline
		Library:AddToTheme(st, { Color = "Outline" })
		blocks[n] = b
		local btn = Library.click(b, function()
			if priority then
				local level = (picker.Value[n] or 0) + 1
				picker.Value[n] = level <= 3 and level or nil
			elseif multi then
				local at = table.find(picker.Value, n)
				if at then table.remove(picker.Value, at) else table.insert(picker.Value, n) end
			else
				picker.Value = picker.Value ~= n and n or nil
			end
			paint()
			fire()
		end)
		fx.hover(btn, function() if not isOn(n) then fx.tween(b, { BackgroundColor3 = Library.Theme["Element Hover"] }, 0.1) end end,
			function() if not isOn(n) then fx.tween(b, { BackgroundColor3 = Library.Theme.Inline }, 0.15) end end)
		Library.attachTooltip(b, n)
	end
	-- the legend, bottom right of the box
	if priority then
		local legend = Instance.new("Frame")
		legend.Name = "\0"
		legend.BackgroundTransparency, legend.BorderSizePixel = 1, 0
		legend.AnchorPoint, legend.Position, legend.Size = Vector2.new(1, 1), UDim2.new(1, -8, 1, -6), UDim2.fromOffset(84, 56)
		legend.Parent = T.figure
		Library.listLayout(legend, 2)
		for i, row in { { "Accent", "1st priority" }, { "Priority 2", "2nd priority" }, { "Priority 3", "3rd priority" }, { "Inline", "off" } } do
			local line = Instance.new("Frame")
			line.Name = "\0"
			line.BackgroundTransparency, line.BorderSizePixel = 1, 0
			line.Size, line.LayoutOrder = UDim2.new(1, 0, 0, 12), i
			line.Parent = legend
			local dot = Instance.new("Frame")
			dot.Name = "\0"
			dot.BorderSizePixel = 0
			dot.Position, dot.Size = UDim2.fromOffset(0, 2), UDim2.fromOffset(8, 8)
			dot.BackgroundColor3 = Library.Theme[row[1]]
			Library:AddToTheme(dot, { BackgroundColor3 = row[1] })
			dot.Parent = line
			local st = Instance.new("UIStroke", dot)
			st.Color = Library.Theme.Outline
			Library:AddToTheme(st, { Color = "Outline" })
			local t = Instance.new("TextLabel")
			t.Name = "\0"
			t.BackgroundTransparency = 1
			t.Position, t.Size = UDim2.fromOffset(13, 0), UDim2.new(1, -13, 1, 0)
			t.FontFace, t.TextSize, t.Text = Library.Font, 11, row[2]
			t.TextColor3 = Library.Theme["Dim Text"]
			t.TextXAlignment = Enum.TextXAlignment.Left
			Library:AddToTheme(t, { TextColor3 = "Dim Text" })
			t.Parent = line
		end
	end
	function picker:Set(v) set(v) end
	function picker:Get() return picker.Value end
	function picker:SetVisibility(b) T.Root.Visible = b end
	Library.SetFlags[flag] = set
	local default = Library.field(Data, "Default", "default")
	if default ~= nil then set(default) else paint() Library.Flags[flag] = picker.Value end
	return picker
end

-- ---- Library:Loader(Data) -> loader ----
-- A small window: a list of games (or any choices), a status line, a progress bar and a load button. Data: Name, Games = { "name" or
-- { Name, Status } ... }, Callback(choice, loader) when the button is pressed (it can call loader:SetStatus / :SetProgress / :Close).
function Library:Loader(Data)
	Data = Data or {}
	local fx = Library.fx
	local L = Build.Loader(Library.Holder.Instance)
	local root = L.Root
	root.Name = "\0"
	root.AnchorPoint, root.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
	root.ZIndex = 1600
	local first, rest = tostring(Library.field(Data, "Name", "name") or "aurora hex"):match("^(%S+)%s*(.*)$")
	L.title.Text, L.title2.Text = first or "", rest or ""
	for _, t in { L.title, L.title2 } do
		t.FontFace = Library.FontBold
		t.AutomaticSize = Enum.AutomaticSize.X
		t.Size = UDim2.new(0, 0, 0, 14)
	end
	-- centre the two title words
	local tRow = Instance.new("Frame")
	tRow.BackgroundTransparency = 1
	tRow.Position, tRow.Size = UDim2.new(0, 2, 0, 5), UDim2.new(1, -4, 0, 18)
	tRow.Parent = root
	L.title.Parent, L.title2.Parent = tRow, tRow
	L.title.LayoutOrder, L.title2.LayoutOrder = 1, 2
	local tl = Library.listLayout(tRow, 4, Enum.FillDirection.Horizontal)
	tl.HorizontalAlignment, tl.VerticalAlignment = Enum.HorizontalAlignment.Center, Enum.VerticalAlignment.Center
	Library.MakeDraggable(tRow, root)
	-- the list
	local scroll = Instance.new("ScrollingFrame")
	scroll.BackgroundTransparency, scroll.BorderSizePixel = 1, 0
	scroll.ScrollBarThickness, scroll.ScrollBarImageColor3 = 2, Library.Theme.Accent
	scroll.CanvasSize, scroll.AutomaticCanvasSize = UDim2.new(), Enum.AutomaticSize.Y
	scroll.Position, scroll.Size = UDim2.new(0, 1, 0, 1), UDim2.new(1, -2, 1, -2)
	scroll.Parent = L.list
	Library.listLayout(scroll, 0)
	local loader = { Instance = root, Choice = nil }
	local rows = {}
	local function select(name)
		loader.Choice = name
		for n, r in rows do
			local on = n == name
			Library:ChangeItemTheme(r.text, { TextColor3 = on and "Accent" or "Dim Text" })
			fx.tween(r.text, { TextColor3 = on and Library.Theme.Accent or Library.Theme["Dim Text"] }, 0.15)
			fx.tween(r.row, { BackgroundTransparency = on and 0 or 1 }, 0.15)
		end
	end
	for i, g in Library.field(Data, "Games", "games") or {} do
		local gname = type(g) == "table" and (g.Name or g.name) or tostring(g)
		local gstatus = type(g) == "table" and (g.Status or g.status) or nil
		local O = Build.Option(scroll)
		O.Root.Size, O.Root.LayoutOrder, O.Root.BackgroundTransparency = UDim2.new(1, 0, 0, 18), i, 1
		O.text.Text = gname
		O.text.Size = UDim2.new(1, -80, 0, 14)
		if gstatus then
			local st = O.text:Clone()
			st.Text, st.TextXAlignment = tostring(gstatus), Enum.TextXAlignment.Right
			st.AnchorPoint, st.Position, st.Size = Vector2.new(1, 0), UDim2.new(1, -6, 0, 2), UDim2.new(0, 70, 0, 14)
			st.Parent = O.Root
		end
		rows[gname] = { row = O.Root, text = O.text }
		Library.click(O.Root, function() select(gname) end)
		if i == 1 then select(gname) end
	end
	function loader:SetStatus(t, frac)
		L.status.Text = tostring(t)
		if frac then loader:SetProgress(frac) end
	end
	function loader:SetProgress(frac)
		fx.tween(L.fill, { Size = UDim2.new(math.clamp(tonumber(frac) or 0, 0, 1), 0, 1, 0) }, 0.25)
	end
	local popScale = Instance.new("UIScale", root)
	function loader:Close()
		fx.tween(popScale, { Scale = 0.94 }, 0.12).Completed:Connect(function() root:Destroy() end)
	end
	L.fill.Size = UDim2.new(0, 0, 1, 0)
	loader:SetStatus(tostring(Library.field(Data, "Status", "status") or "select a game"))
	L.buttonText.Text = tostring(Library.field(Data, "Button", "button") or "load")
	local callback = Library.field(Data, "Callback", "callback")
	local btn = Library.click(L.button, function()
		if callback then task.spawn(function() Library:SafeCall(callback, loader.Choice, loader) end) end
	end)
	Library.raiseButton(L.button, btn)
	-- it pops in
	popScale.Scale = 0.94
	fx.tween(popScale, { Scale = 1 }, 0.22)
	return loader
end

-- ---- Library:BombWindow(Data) -> bomb ----
-- A floating window: a ring that runs down around a C4, then time left, HP left, damage and status. Data: Name.
-- bomb:Set({ left, total, hp, damage, status, statusColor, site }) (site = the bombsite letter, shown under the C4), bomb:SetVisibility(b), bomb:Destroy(), bomb.Instance. Hidden until shown; drag it by the title.
function Library:BombWindow(Data)
	Data = Data or {}
	local P = Build.BombWindow(Library.Holder.Instance)
	local root = P.Root
	root.Name = "\0"
	root.ZIndex = 1300
	root.Visible = false
	root.Position = UDim2.fromOffset(24, 300)
	P.title.Text = tostring(Library.field(Data, "Name", "name") or "bomb")
	Library.MakeDraggable(P.title, root)
	for _, k in { "time", "hp", "damage", "status" } do P[k].TextXAlignment = Enum.TextXAlignment.Right end
	P.title.Active = true
	-- the ring: square segments, bright while there is time left
	local N, SIZE = 60, 150
	local holder = Instance.new("Frame")
	holder.Name = "\0"
	holder.BackgroundTransparency, holder.BorderSizePixel = 1, 0
	holder.AnchorPoint, holder.Position, holder.Size = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5), UDim2.fromOffset(SIZE, SIZE)
	holder.Parent = P.view
	local ring = {}
	for i = 1, N do
		local a = (i - 1) / N * math.pi * 2
		local seg = Instance.new("Frame")
		seg.Name = "\0"
		seg.BorderSizePixel = 0
		seg.AnchorPoint = Vector2.new(0.5, 0.5)
		seg.Position = UDim2.fromOffset(SIZE / 2 + math.sin(a) * (SIZE / 2 - 6), SIZE / 2 - math.cos(a) * (SIZE / 2 - 6))
		seg.Size, seg.Rotation = UDim2.fromOffset(3, 9), math.deg(a)
		seg.BackgroundColor3 = Library.Theme.Inline
		seg.Parent = holder
		ring[i] = seg
	end
	-- the C4: flat blocks in the theme's greys
	local function block(parent, x, y, w, h, key)
		local f = Instance.new("Frame")
		f.Name = "\0"
		f.BorderSizePixel = 0
		f.Position, f.Size = UDim2.fromOffset(x, y), UDim2.fromOffset(w, h)
		f.BackgroundColor3 = Library.Theme[key]
		Library:AddToTheme(f, { BackgroundColor3 = key })
		f.Parent = parent
		return f
	end
	local c4 = Instance.new("Frame")
	c4.Name = "\0"
	c4.BackgroundTransparency, c4.BorderSizePixel = 1, 0
	c4.AnchorPoint, c4.Position, c4.Size = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5), UDim2.fromOffset(70, 46)
	c4.Parent = holder
	block(c4, 0, 12, 8, 22, "Border")
	block(c4, 8, 0, 62, 46, "Inline")
	block(c4, 13, 6, 26, 14, "Outline")
	local led = block(c4, 16, 9, 8, 8, "Accent")
	block(c4, 13, 26, 26, 12, "Highlight")
	for r = 0, 2 do
		for c = 0, 2 do block(c4, 44 + c * 8, 6 + r * 12, 5, 8, "Dark Liner") end
	end
	local siteLabel = Instance.new("TextLabel")
	siteLabel.Name = "\0"
	siteLabel.BackgroundTransparency, siteLabel.BorderSizePixel = 1, 0
	siteLabel.AnchorPoint, siteLabel.Position, siteLabel.Size = Vector2.new(0.5, 0), UDim2.new(0.5, 0, 0.5, 26), UDim2.fromOffset(90, 18)
	siteLabel.FontFace, siteLabel.TextSize = Library.FontBold or Library.Font, 14
	siteLabel.TextColor3 = Library.Theme["Bright Text"]
	Library:AddToTheme(siteLabel, { TextColor3 = "Bright Text" })
	siteLabel.Text = ""
	siteLabel.Parent = holder
	local bomb = { Instance = root }
	local GREEN, RED = Color3.fromRGB(90, 230, 120), Color3.fromRGB(255, 85, 75)
	local lit, litColor = -1, nil
	function bomb:Set(d)
		d = d or {}
		local total = math.max(tonumber(d.total) or 40, 0.1)
		local left = math.max(tonumber(d.left) or 0, 0)
		local frac = math.clamp(left / total, 0, 1)
		local n = math.floor(frac * N + 0.5)
		local col = RED:Lerp(GREEN, frac)
		if n ~= lit or col ~= litColor then
			lit, litColor = n, col
			for i = 1, N do ring[i].BackgroundColor3 = i <= n and col or Library.Theme.Inline end
		end
		-- the light on the C4 blinks faster as it runs down
		led.Visible = left <= 0 or (os.clock() * (1 + (1 - frac) * 5)) % 1 < 0.5
		P.time.Text, P.time.TextColor3 = string.format("%.1fs", left), col
		P.hp.Text = tostring(math.floor((tonumber(d.hp) or 0) + 0.5))
		P.damage.Text = tostring(math.floor((tonumber(d.damage) or 0) + 0.5))
		P.status.Text = tostring(d.status or "")
		P.status.TextColor3 = d.statusColor or Library.Theme.Text
		siteLabel.Text = d.site and ("Site " .. tostring(d.site)) or ""
	end
	function bomb:SetVisibility(b) root.Visible = b end
	function bomb:Destroy() root:Destroy() end
	return bomb
end

-- ---- Library:ChatWindow(Data) -> chat ----
-- A floating, resizable chat. Data: Name, Who (top right), Placeholder, Size, OnSend(text) -> false keeps the text, CanDrag() -> false locks it in place.
-- chat:Add({ name, text, time, mine, color }), chat:System(text), chat:Clear(), chat:SetVisibility(b), chat.Instance, chat.Box.
function Library:ChatWindow(Data)
	Data = Data or {}
	local P = Build.ChatWindow(Library.Holder.Instance)
	local root = P.Root
	root.Name = "\0"
	root.ZIndex = 1200
	root.Visible = false
	local size = Library.field(Data, "Size", "size")
	if size then root.Size = size end
	P.title.Text = tostring(Library.field(Data, "Name", "name") or "chat")
	P.who.Text = tostring(Library.field(Data, "Who", "who") or "")
	P.who.TextXAlignment = Enum.TextXAlignment.Right
	-- the corners follow the window as it is resized
	P.who.AnchorPoint, P.who.Position = Vector2.new(1, 0), UDim2.new(1, -10, 0, P.who.Position.Y.Offset)
	P.field.AnchorPoint, P.field.Position, P.field.Size = Vector2.new(0, 1), UDim2.new(0, 9, 1, -10), UDim2.new(1, -18, 0, 24)
	P.list.Size = UDim2.new(1, -18, 1, -74)
	P.dragBar.Active = true
	local canDrag = Library.field(Data, "CanDrag", "candrag")
	local dragging, start, from
	Library:Connect(P.dragBar.InputBegan, function(i)
		if (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) and not (canDrag and canDrag() == false) then
			dragging, start, from = true, i.Position, root.Position
		end
	end)
	local resizing, startSize
	local grip = Instance.new("TextButton")
	grip.Name = "\0"
	grip.Text, grip.AutoButtonColor, grip.BorderSizePixel = "", false, 0
	grip.AnchorPoint, grip.Position, grip.Size = Vector2.new(1, 1), UDim2.new(1, -2, 1, -2), UDim2.fromOffset(6, 6)
	grip.BackgroundColor3 = Library.Theme.Border
	Library:AddToTheme(grip, { BackgroundColor3 = "Border" })
	grip.ZIndex = 5
	grip.Parent = root
	Library:Connect(grip.InputBegan, function(i)
		if (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then resizing, start, startSize = true, i.Position, root.AbsoluteSize end
	end)
	Library:Connect(UserInputService.InputChanged, function(i)
		if not (dragging or resizing) or not (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then return end
		local d = i.Position - start
		if dragging then
			root.Position = UDim2.new(from.X.Scale, from.X.Offset + d.X, from.Y.Scale, from.Y.Offset + d.Y)
		else
			root.Size = UDim2.fromOffset(math.clamp(startSize.X + d.X, 280, 900), math.clamp(startSize.Y + d.Y, 180, 700))
		end
	end)
	Library:Connect(UserInputService.InputEnded, function(i)
		if (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then dragging, resizing = false, false end
	end)
	-- the messages
	local scroll = Instance.new("ScrollingFrame")
	scroll.Name = "\0"
	scroll.BackgroundTransparency, scroll.BorderSizePixel = 1, 0
	scroll.Position, scroll.Size = UDim2.fromOffset(8, 6), UDim2.new(1, -12, 1, -12)
	scroll.ScrollBarThickness, scroll.ScrollBarImageColor3 = 2, Library.Theme.Accent
	scroll.ScrollingDirection = Enum.ScrollingDirection.Y
	scroll.CanvasSize, scroll.AutomaticCanvasSize = UDim2.new(), Enum.AutomaticSize.Y
	scroll.Parent = P.list
	Library:AddToTheme(scroll, { ScrollBarImageColor3 = "Accent" })
	Library.listLayout(scroll, 6)
	local stick = true
	Library:Connect(scroll:GetPropertyChangedSignal("CanvasPosition"), function()
		stick = scroll.CanvasPosition.Y >= scroll.AbsoluteCanvasSize.Y - scroll.AbsoluteWindowSize.Y - 4
	end)
	Library:Connect(scroll:GetPropertyChangedSignal("AbsoluteCanvasSize"), function()
		if stick then scroll.CanvasPosition = Vector2.new(0, math.max(0, scroll.AbsoluteCanvasSize.Y - scroll.AbsoluteWindowSize.Y)) end
	end)
	-- the box
	local box = Instance.new("TextBox")
	box.Name = "\0"
	box.BackgroundTransparency, box.BorderSizePixel = 1, 0
	box.Position, box.Size = UDim2.fromOffset(8, 0), UDim2.new(1, -16, 1, 0)
	box.FontFace, box.TextSize = Library.Font, 12
	box.TextColor3, box.PlaceholderColor3 = Library.Theme.Text, Library.Theme["Dim Text"]
	Library:AddToTheme(box, { TextColor3 = "Text", PlaceholderColor3 = "Dim Text" })
	box.PlaceholderText = tostring(Library.field(Data, "Placeholder", "placeholder") or "message")
	box.TextXAlignment, box.ClearTextOnFocus, box.Text = Enum.TextXAlignment.Left, false, ""
	box.ClipsDescendants = true
	box.Parent = P.field
	local fieldStroke = P.field:FindFirstChildOfClass("UIStroke")
	Library:Connect(box.Focused, function() if fieldStroke then fieldStroke.Color = Library.Theme.Accent end end)
	Library:Connect(box.FocusLost, function() if fieldStroke then fieldStroke.Color = Library.Theme.Outline end end)
	local onSend = Library.field(Data, "OnSend", "onsend")
	Library:Connect(box.FocusLost, function(enter)
		if not enter then return end
		local result
		if onSend then
			local ok, r = pcall(onSend, box.Text)
			result = ok and r or nil
		end
		if result ~= false then box.Text = "" end
		task.defer(function() if root.Parent and root.Visible then box:CaptureFocus() end end)
	end)
	local MAX = tonumber(Library.field(Data, "MaxLines", "maxlines")) or 150
	local rows, order = {}, 0
	local function esc(t) return (tostring(t):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;")) end
	local function text(parent, size, key)
		local t = Instance.new("TextLabel")
		t.Name = "\0"
		t.BackgroundTransparency, t.BorderSizePixel = 1, 0
		t.FontFace, t.TextSize = Library.Font, size
		t.TextColor3 = Library.Theme[key]
		Library:AddToTheme(t, { TextColor3 = key })
		t.TextXAlignment, t.TextYAlignment = Enum.TextXAlignment.Left, Enum.TextYAlignment.Top
		t.Parent = parent
		return t
	end
	local function push(row)
		order += 1
		row.LayoutOrder = order
		row.Parent = scroll
		rows[#rows + 1] = row
		if #rows > MAX then table.remove(rows, 1):Destroy() end
	end
	local chat = { Instance = root, Box = box }
	-- a message: the name and time on top, the text under it
	function chat:Add(m)
		m = m or {}
		local row = Instance.new("Frame")
		row.Name = "\0"
		row.BackgroundTransparency, row.BorderSizePixel = 1, 0
		row.Size, row.AutomaticSize = UDim2.new(1, -6, 0, 0), Enum.AutomaticSize.Y
		local bar = Instance.new("Frame")
		bar.Name = "\0"
		bar.BorderSizePixel = 0
		bar.Size = UDim2.new(0, 2, 1, 0)
		bar.BackgroundColor3 = m.mine and Library.Theme.Accent or Library.Theme.Border
		Library:AddToTheme(bar, { BackgroundColor3 = m.mine and "Accent" or "Border" })
		bar.Parent = row
		local name = text(row, 12, m.mine and "Accent" or "Bright Text")
		name.Position, name.Size = UDim2.fromOffset(8, 0), UDim2.new(1, -70, 0, 14)
		name.Text = tostring(m.name or "") .. (m.mine and "  (you)" or "")
		if m.color then Library:ChangeItemTheme(name, {}) name.TextColor3 = m.color end
		local when = text(row, 11, "Dim Text")
		when.AnchorPoint, when.Position, when.Size = Vector2.new(1, 0), UDim2.new(1, 0, 0, 1), UDim2.fromOffset(60, 12)
		when.TextXAlignment = Enum.TextXAlignment.Right
		when.Text = tostring(m.time or "")
		local body = text(row, 12, "Text")
		body.Position, body.Size = UDim2.fromOffset(8, 15), UDim2.new(1, -8, 0, 0)
		body.AutomaticSize = Enum.AutomaticSize.Y
		body.TextWrapped = true
		body.Text = tostring(m.text or "")
		push(row)
		return row
	end
	-- a grey line without a name
	function chat:System(t)
		local row = text(nil, 11, "Dim Text")
		row.Size, row.AutomaticSize = UDim2.new(1, -6, 0, 0), Enum.AutomaticSize.Y
		row.TextWrapped = true
		row.Text = tostring(t)
		push(row)
		return row
	end
	function chat:Clear()
		for _, r in rows do r:Destroy() end
		table.clear(rows)
	end
	function chat:SetVisibility(b) root.Visible = b end
	function chat:Destroy() root:Destroy() end
	return chat
end


-- ===== runtime/config.lua =====
-- runtime part 9 (Cadia only): configs, auto load and the ready-made Settings page.
-- Library:SaveConfig(name) / LoadConfig(name) / DeleteConfig(name) / ConfigList() write every flag to <Folders.Configs>/<name>.json.
-- Library:SetAutoload(name) names the config that Library:RunAutoload() loads; a window schedules RunAutoload once, shortly after it is
-- built (Window({ AutoLoad = false }) turns that off), so a script only has to create its elements.
-- Flags that start with "_" (the Settings page's own controls) are not saved.

local function fsReady() return type(writefile) == "function" and type(readfile) == "function" and type(isfile) == "function" end
local function ensureFolders()
	pcall(function()
		for _, f in { Library.Folders.Directory, Library.Folders.Configs } do
			if makefolder and not (isfolder and isfolder(f)) then makefolder(f) end
		end
	end)
end
local function pathOf(name) return Library.Folders.Configs .. "/" .. tostring(name) .. ".json" end

local function pack(v)
	local t = typeof(v)
	if t == "boolean" or t == "number" or t == "string" then return v end
	if t ~= "table" then return nil end
	if v.HexValue or typeof(v.Color) == "Color3" then
		return { __t = "color", Color = v.HexValue or v.Color:ToHex(), Alpha = tonumber(v.Alpha) or 0 }
	end
	if v.Mode ~= nil then
		return { __t = "key", Key = v.Key and tostring(v.Key) or "None", Mode = v.Mode }
	end
	local out = {}
	for i, x in ipairs(v) do
		local tx = type(x)
		if tx == "string" or tx == "number" or tx == "boolean" then out[i] = x end
	end
	return { __t = "list", v = out }
end

function Library:ConfigList()
	local out = {}
	if not (fsReady() and type(listfiles) == "function") then return out end
	ensureFolders()
	pcall(function()
		for _, f in listfiles(Library.Folders.Configs) do
			local n = tostring(f):match("([^/\\]+)%.json$")
			if n then out[#out + 1] = n end
		end
	end)
	table.sort(out)
	return out
end

function Library:SaveConfig(name)
	name = tostring(name or "")
	if name == "" or not fsReady() then return false end
	ensureFolders()
	local data = {}
	for flag, v in Library.Flags do
		if type(flag) == "string" and flag:sub(1, 1) ~= "_" and Library.SetFlags[flag] then
			local p = pack(v)
			if p ~= nil then data[flag] = p end
		end
	end
	local ok = pcall(function() writefile(pathOf(name), HttpService:JSONEncode(data)) end)
	return ok
end

function Library:LoadConfig(name)
	name = tostring(name or "")
	if name == "" or not fsReady() then return false end
	local ok, data = pcall(function()
		if not isfile(pathOf(name)) then return nil end
		return HttpService:JSONDecode(readfile(pathOf(name)))
	end)
	if not ok or type(data) ~= "table" then return false end
	-- keybinds first: one in "Always" mode switches its toggle on, and the toggle's own saved value must win
	local order = {}
	for flag, v in data do order[#order + 1] = { flag, v, (type(v) == "table" and v.__t == "key") and 0 or 1 } end
	table.sort(order, function(a, b) if a[3] ~= b[3] then return a[3] < b[3] end return a[1] < b[1] end)
	for _, e in order do
		local flag, v = e[1], e[2]
		local set = Library.SetFlags[flag]
		if set then
			if type(v) == "table" then
				if v.__t == "color" then v = { Color = v.Color, Alpha = v.Alpha }
				elseif v.__t == "key" then v = { Key = v.Key, Mode = v.Mode }
				elseif v.__t == "list" then v = v.v end
			end
			pcall(set, v)
		end
	end
	return true
end

function Library:DeleteConfig(name)
	name = tostring(name or "")
	if name == "" or type(delfile) ~= "function" then return false end
	local ok = pcall(function() delfile(pathOf(name)) end)
	if Library:GetAutoload() == name then Library:SetAutoload("") end
	return ok
end

local function autoPath() return Library.Folders.Directory .. "/autoload.txt" end
function Library:GetAutoload()
	if not fsReady() then return "" end
	local ok, v = pcall(function() return isfile(autoPath()) and readfile(autoPath()) or "" end)
	return ok and tostring(v) or ""
end
function Library:SetAutoload(name)
	if not fsReady() then return end
	ensureFolders()
	pcall(function() writefile(autoPath(), tostring(name or "")) end)
end
function Library:RunAutoload()
	local n = Library:GetAutoload()
	if n == "" then return false end
	if Library:LoadConfig(n) then
		Library:Notification(('Auto loaded <font color="#%s">%s</font>'):format(Library.Theme.Accent:ToHex(), n), 4)
		return true
	end
	return false
end

-- every window schedules the auto load once (the script builds its elements in the same frame, so they exist by then)
do
	local makeWindow = Library.Window
	local queued = false
	function Library:Window(Data)
		local w = makeWindow(self, Data)
		if not queued and not (type(Data) == "table" and (Data.AutoLoad == false or Data.autoload == false)) then
			queued = true
			task.delay(0.75, function() if Library.Alive then Library:RunAutoload() end end)
		end
		return w
	end
end

-- Window:SettingsPage(name) -> page: configs (save / load / delete, auto load), the menu key, the theme and accent, the HUD, unload
function Library:SettingsPage(Name)
	local window = self
	local page = window:Page({ Name = Name or "Settings" })
	local function accentHex() return Library.Theme.Accent:ToHex() end
	local function note(fmt, n) Library:Notification(fmt:format(accentHex(), tostring(n)), 3) end

	local C = page:Section({ Name = "Configs", Side = 1 })
	local nameBox = C:Textbox({ Name = "Config Name", Placeholder = "default", Flag = "_CfgName" })
	local list = C:Listbox({ Name = "Saved Configs", Items = Library:ConfigList(), Flag = "_CfgList", Size = 106 })
	local auto
	local function selected()
		local typed = nameBox:Get()
		if typed and typed ~= "" then return typed end
		return list:Get()
	end
	C:Buttons({
		{ Name = "Save", Confirm = false, Callback = function()
			local n = selected() or "default"
			if Library:SaveConfig(n) then list:Refresh(Library:ConfigList()) note('Saved <font color="#%s">%s</font>', n) end
		end },
		{ Name = "Load", Confirm = false, Callback = function()
			local n = list:Get() or selected()
			if n and Library:LoadConfig(n) then note('Loaded <font color="#%s">%s</font>', n) end
		end },
		{ Name = "Delete", Callback = function()
			local n = list:Get()
			if n and Library:DeleteConfig(n) then list:Refresh(Library:ConfigList()) note('Deleted <font color="#%s">%s</font>', n) end
		end },
	})
	C:Button({ Name = "Refresh List", Callback = function() list:Refresh(Library:ConfigList()) end })
	local autoLabel
	auto = C:Toggle({ Name = "Auto Load Selected", Flag = "_CfgAuto", Callback = function(v)
		if v then
			local n = list:Get() or selected()
			if n then Library:SetAutoload(n) end
		else
			Library:SetAutoload("")
		end
		if autoLabel then
			local n = Library:GetAutoload()
			autoLabel:SetText(n ~= "" and ('Auto load: <font color="#%s">%s</font>'):format(accentHex(), n) or "Auto load: off")
		end
	end })
	do
		local n = Library:GetAutoload()
		autoLabel = C:Label(n ~= "" and ('Auto load: <font color="#%s">%s</font>'):format(accentHex(), n) or "Auto load: off")
	end

	local M = page:Section({ Name = "Menu", Side = 2 })
	M:Keybind({ Name = "Menu Bind", Menu = true, Flag = "_MenuKey" })
	M:Dropdown({ Name = "Theme", Items = Library.ThemeOrder, Default = "Default", Flag = "_Theme", Callback = function(v)
		local th = v and Library.Themes[v]
		if th then for k, c in th do Library:ChangeTheme(k, c) end end
	end })
	M:Label("Accent"):Colorpicker({ Flag = "_Accent", Default = Library.Theme.Accent, Callback = function(c) Library:ChangeTheme("Accent", c) end })
	M:Toggle({ Name = "Keybind List", Flag = "_KeyList", Default = true, Callback = function(v) if Library.KeyList then Library.KeyList:SetVisibility(v) end end })
	M:Toggle({ Name = "Menu Blur", Flag = "_Blur", Default = Library.Blur.Enabled, Callback = function(v) Library:SetBlur(v) end })
	M:Toggle({ Name = "Animations", Flag = "_Anim", Default = true, Callback = function(v) Library.Animations = v end })
	M:Button({ Name = "Unload", Callback = function() Library:Unload() end })
	return page
end


if getgenv then getgenv().Library = Library end
return Library
